(window.GIM_TS=window.GIM_TS||{})["Pesachim.3"]={"from":72,"a":[["\u0003מצות של מעשר שני, לדברי ר' מאיר — אין אדם יוצא בו ידי חובתו\u0004 בליל ראשון של \u0003פסח,\u0004 שצריכה המצה להיות שלו ולא של גבוה. \u0003לדברי חכמים — יוצא בה ידי חובתו בפסח.\u0004","וכן \u0003אתרוג של מעשר שני, לדברי ר' מאיר — אין יוצא בה ידי חובתו ביום טוב\u0004 ראשון של סוכות, לפי שאינו שלו. \u0003לדברי חכמים — אדם יוצא בו ידי חובתו ביום טוב.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003עיסה\u0004 שממנה מפרישים חלה יש לסברה זו בסיס, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \"מראשית \u0003עריסתיכם\u0004 תתנו לה' תרומה לדורותיכם\" (במדבר טו, כא), ונדרוש \"עריסותיכם\" — משמע: \u0003משלכם.\u0004","\u0003אתרוג נמי\u0004 \u0005[גם כן]\u0006 יש מקור לדבר, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 באתרוג \u0003\"ולקחתם לכם\u0004 ביום הראשון פרי עץ הדר כפות תמרים וענף עץ עבות וערבי נחל\u0003\"\u0004 (ויקרא כג, מ), \u0003\"לכם\"\u0004 — משמע: \u0003משלכם יהא, אלא מצה, מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003מצתכם?\u0004 ואם כן, אף כשהמצה של גבוה, אין סיבה שלא תהא כשרה!","\u0003אמר רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יימר בר שלמיא: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שוה \u0003\"לחם\" \"לחם\"; כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 במצות \u0003\"לחם עני\"\u0004 (דברים טז, ג), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בענין חלה \u0003\"והיה באכלכם מלחם הארץ תרימו\u0004 תרומה לה'\u0003\"\u0004 (במדבר טו, יט), \u0003מה להלן\u0004 בחלה — \u0003משלכם, אף כאן\u0004 במצה — \u0003משלכם.\u0004","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 לרב אסי בהלכות אלה שקבע ממה ששנינו: \u0003עיסה של מעשר שני פטורה מן החלה, דברי ר' מאיר. וחכמים אומרים: חייבת.\u0004 הוכחה זו הוכחה גמורה היא, ומשום כך תוהים על לשון התלמוד: מדוע נאמר רק \u0003\"לימא מסייע\"\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע]?\u0006 הלוא \u0003היינו הך\u0004 \u0005[זהו זה]\u0006 בפירוש נאמר בברייתא מה שאמר רב אסי!","ודוחים: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 כך יש להסביר את הלשון; \u0003לימא מדפליגי\u0004 \u0005[האם לומר\u0006 שכשם \u0005שחולקים]\u0006 \u0003בעיסה, בהנך נמי פליגי\u0004 \u0005[באותם\u0006 דברים נוספים \u0005גם כן חולקים].\u0006 \u0003או דילמא, שאני התם\u0004 \u0005[שמא, שונה שם]\u0006 בענין חלה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"עריסתיכם\" \"עריסתיכם\" תרי זימני\u0004 \u0005[שתי פעמים],\u0006 וכיון שיש הדגשה כפולה על הצורך בבעלות גמורה ולא רק ברשות אכילה, סבור ר' מאיר שאין מפרישים ממעשר שני, אבל לא יאמר כן במצה או באתרוג, ובהלכות אלה אין ההוכחה מפורשת.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' שמעון בן לקיש: מהו שיצא אדם ידי חובתו\u0004 באכילת מצה \u0003בחלה\u0004 שמפרישים מעיסה \u0003של מעשר שני בירושלים?\u0004 ומבארים: \u0003אליבא\u0004 \u0005[לפי\u0006 שיטת\u0005]\u0006 \u0003ר' יוסי הגלילי\u0004 שלדעתו יוצאים ידי חובת מצה רק בדבר הנאכל גם באנינות — \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, \u0003השתא\u0004 \u0005[\u0006הרי \u0005עכשיו]\u0006 \u0003בחולין\u0004 כלומר במעשר שני עצמו שלא הוקדש בקדושת חלה \u0003לא נפיק\u0004 \u0005[יוצא],\u0006 \u0003בחלתו מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאינו יוצא?! \u0003כי תיבעי לך אליבא\u0004 \u0005[כאשר תסתפק לך\u0006 הרי זה \u0005לשיטתו]\u0006 של \u0003ר' עקיבא\u0004 שאינו לומד כר' יוסי הגלילי \"לחם אוני\", וכך יש להעמיד את הבעיה:","\u0003בחולין הוא דנפיק\u0004 \u0005[שיוצא] —\u0006 \u0003דאי מיטמו\u0004 \u0005[שאם נטמאים]\u0006 החולין של מעשר שני \u0003יש להן היתר\u0004 אכילה \u0003ב\u0004כל \u0003מושבות\u0004 ישראל לאחר פדיון, שר' עקיבא מסכים שכל דבר שראוי בנסיבות מסויימות להיות נאכל בכל מושבות ישראל יוצא בו חובת מצה. \u0003אבל חלה, דאי מיטמיא\u0004 \u0005[שאם נטמאת]\u0006 \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה היתר ב\u0004שאר \u0003מושבות ולשריפה אזלא\u0004 \u0005[הולכת]\u0006 \u0003לא נפיק\u0004 \u0005[יוצא]\u0006 בה","\u0003או דילמא אמרינן\u0004 \u0005[שמא אומרים אנו]:\u0006 \u0003הואיל ואילו לא קרא עליה שם\u0004 אילו לא היה מפריש אותה להיות חלה \u0003ואיטמי\u0004 \u0005[והיתה נטמאת],\u0006 \u0003אית\u0004 \u0005[היה]\u0006 \u0003לה היתר ב\u0004שאר \u0003מושבות\u0004 ישראל \u0003ונפיק\u0004 \u0005[והיה\u0006 יכול \u0005לצאת בה],\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 במצה זו העשויה מחלה \u0003נמי נפיק\u0004 \u0005[גם כן יוצא],\u0006 שמעיקרה אין בה פגם זה, וקדושתה אינה צריכה לפגום בכך.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת: \u0003הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003ודאי לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך,\u0004 ש\u0003ודאי אמרינן\u0004 \u0005[אומרים אנו]\u0006 בכגון זה \u0003\"הואיל\"\u0004 וחלת מעשר שני ודאי ראויה. \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה הרי זה ביחס ל\u0003חלה הלקוחה\u0004 (הקנויה) \u0003בכסף מעשר שני,\u0004 שגם דבר שנקנה בכסף מעשר שני ונטמא יש לו תקנה.","\u0003ו\u0004עוד, \u0003אליבא דרבנן\u0004 \u0005[לפי\u0006 שיטת \u0005חכמים]\u0006 \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה \u0003כיון דאמרי\u0004 \u0005[שאומרים\u0006 הם\u0005]\u0006 \u0003יפדה\u0004 שנית — \u0003היינו\u0004 \u0005[הריהו]\u0006 כ\u0003מעשר,\u0004 שאין הבדל בין לקוח בכספי מעשר או מעשר עצמו. אלא, \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה, הרי זה \u0003אליבא\u0004 \u0005[לפי\u0006 שיטת\u0005]\u0006 \u0003ר' יהודה,\u0004 ש\u0003אמר\u0004 שהלקוח בכסף מעשר ונטמא — \u0003יקבר.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 דבר \u0003הלקוח בכסף מעשר שני שנטמא — יפדה,\u0004 ובמחירו יקח מעשר שני אחר. \u0003ר' יהודה אומר: יקבר,\u0004 שכיון שהוא עצמו נלקח בכסף מעשר אין קדושתו מרובה כמעשר עצמו עד שאפשר יהא לפדותו על ידי שתחול קדושה שבו על חפץ אחר, אלא יקבר כשאר דברים שאין להם תקנה.","ולעניננו השאלה היא: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003הואיל ואי\u0004 \u0005[ואם]\u0006 \u0003לא לקוח\u0004 בכסף מעשר \u0003הוי\u0004 \u0005[היה],\u0006 \u0003ו\u0004כן \u0003הואיל ולא קרא עליה שם ואיטמי\u0004 \u0005[והיה נטמא],\u0006 \u0003יש לו היתר במושבות ונפיק ביה\u0004 \u0005[ויוצא בו]\u0006 ידי חובה, \u0003השתא נמי נפיק ביה\u0004 \u0005[עכשיו גם כן יוצא בו].\u0006","\u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003חד\u0004 \u0005[\u0006פעם \u0005אחת]\u0006 \u0003\"הואיל\" אמרינן\u0004 \u0005[אומרים אנו],\u0006 \u0003תרי\u0004 \u0005[שתי]\u0006 פעמים \u0003\"הואיל\" לא אמרינן\u0004 \u0005[אומרים אנו],\u0006 ואינו יוצא במצת חלה הלקוחה בכסף מעשר שני? \u0003אמר רבא: מסתברא\u0004 \u0005[מסתבר]\u0006 הדבר כי \u0003שם מעשר חד\u0004 \u0005[אחד]\u0006 \u0003הוא,\u0004 שכיון שהדבר כלול במסגרת הכללית של מעשר, יכול לצאת בו חובת מצה. שכשם שיוצא במצת מעשר שני, כך יוצא גם בחלתו.","שנינו במשנה כי \u0003חלת תודה ורקיקי נזיר\u0004 אם עשאם לעצמו אינו יוצא בהם ידי חובת מצה בפסח. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רבה:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006"],["\u0003\"ושמרתם את המצות\"\u0004 (שמות יב, יז), ולמד מכאן: \u0003מצה המשתמרת\u0004 מחמץ \u0003לשם מצה\u0004 — יוצאים בה בפסח, \u0003יצתה\u0004 (יצאה) \u0003זו\u0004 של נזיר או תודה \u0003שאין משתמרת לשם מצה אלא לשום\u0004 \u0005[לשם]\u0006 \u0003זבח.\u0004","\u0003רב יוסף אמר, אמר קרא:\u0004 הטעם הוא ממקרא אחר, שנאמר \u0003\"שבעת ימים מצות תאכלו\"\u0004 (שמות יב, טו) ומכאן נלמד: \u0003מצה הנאכלת\u0004 או ראויה להיאכל \u0003לשבעת ימים\u0004 שלמים — יוצאים בה, \u0003יצתה זו\u0004 של נזיר ותודה \u0003שאינה נאכלת לשבעת ימים אלא ליום ולילה\u0004 בלבד.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבה, ותניא כוותיה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב יוסף. תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבה: יכול יצא אדם ידי חובתו\u0004 באכילת מצה \u0003בחלות תודה ורקיקי נזיר — תלמוד לומר \"ושמרתם את המצות\" מצה המשתמרת לשם מצה, יצתה זו שאינה משתמרת לשם מצה אלא לשום\u0004 \u0005[לשם]\u0006 \u0003זבח.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב יוסף: יכול יצא אדם ידי חובתו בחלות תודה ורקיקי נזיר, תלמוד לומר \"שבעת ימים מצות תאכלו\" — מצה הנאכלת לשבעה\u0004 ימים, \u0003יצתה זו שאינה נאכלת לשבעה\u0004 ימים \u0003אלא ליום ולילה\u0004 בלבד.","ושואלים לשתי השיטות: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 אותה הלכה עצמה \u0003מ\u0004המקרא \u0003\"לחם עני\"\u0004 שפירשו ר' יוסי הגלילי שמשמעו: \u0003מי שנאכל\u0004 אף \u0003באנינות\u0004 (צער) יוצאים בו ידי חובת מצה, \u0003יצא זה\u0004 כגון חלות תודה ורקיקי נזיר \u0003שאינו נאכל באנינות אלא בשמחה,\u0004 שהרי האונן אסור לו לאכול מן הזבחים!","ומשיבים: \u0003סבר לה\u0004 \u0005[סבר אותו\u0006 חכם\u0005]\u0006 \u0003כר' עקיבא,\u0004 ש\u0003אמר \"עני\" כתיב\u0004 \u0005[נאמר]\u0006 ואין למדים ממקרא זה לענין אנינות.","ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 אותה הלכה מזה \u0003דהוה ליה\u0004 \u0005[שהרי היא]\u0006 \u0003מצה עשירה\u0004, שכן חלות התודה ורקיקי נזיר נבללים בשמן, ומצה האפויה שלא במים בלבד הרי היא מצה עשירה!","\u0003אמר שמואל בר רב יצחק:\u0004 זה אינו טעם מספיק, כי כל השמן המצוי בחלות וברקיקים הללו \u0003רביעית\u0004 הלוג \u0003היא. ומתחלקת היא לכמה חלות —\u0004 וכמות שמן קטנה זו בטלה בהן, ואינן קרויות משום כך מצה עשירה.","ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 אותה הלכה ממה ש\u0003אינן נאכלות בכל מושבות,\u0004 שהרי למדנו מהמקרא שהמצה צריכה להיות ראויה להיאכל בכל מושבות ישראל, וקודשים נאכלים רק בירושלים!","\u0003אמר ריש לקיש:\u0004 מאחר שלא השתמשו בנימוק זה, \u0003זאת אומרת חלות תודה ורקיקי נזיר נאכלין בנוב וגבעון,\u0004 כלומר בבמות הגדולות שנעשו לפני הקמת המקדש. ומאחר שראויות להיאכל בכל מקום, שהרי כל מקום כשר לבמה, ואינן כקרבנות מסויימים שלא הותרו להיות קרבים אלא \"במקום אשר יבחר ה'\", לכן חלות התודה נחשבות הן כראויות לכל מושבות ישראל.","מסופר, \u0003אמר ר' אילעאי: שאלתי את ר' אליעזר\u0004 בן הורקנוס: \u0003מהו שיצא אדם\u0004 ידי חובתו בפסח \u0003בחלות תודה ורקיקי נזיר? אמר לי: לא שמעתי. באתי ושאלתי לפני ר' יהושע, אמר לי: הרי אמרו\u0004 בענין זה \u0003חלות תודה ורקיקי נזיר שעשאן\u0004 אדם \u0003לעצמו\u0004 לצרף לקרבנו — \u0003אין אדם יוצא בהן,\u0004 אם עשאן \u0003למכור בשוק — יוצא בהן.\u0004","ו\u0003כשבאתי\u0004 וחזרתי \u0003והרציתי דברים\u0004 ששמעתי \u0003לפני ר' אליעזר, אמר לי\u0004 בהתפעלות: \u0003ברית\u0004 (לשון שבועה)! \u0003הן הן הדברים שנאמרו לו למשה מסיני,\u0004 כלומר, נשבע שכך היא אכן ההלכה המקובלת מדורות ונאמרה למשה מסיני. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאמר דברים אלה בתמיהה: \u0003ברית\u0004 (שבועה) \u0003הן הן הדברים שנאמרו לו למשה בסיני?! ולא טעמא בעיא\u0004 \u0005[וכי אינו צריך טעם]\u0006 כלומר, כיצד אפשר לקבוע הלכה כזו בלא מסורת, כהלכה מסיני, בלא לתת בה טעם?!","ושואלים: ובאמת \u0003וטעמא מאי\u0004 \u0005[וטעם\u0006 הדבר \u0005מהו]?\u0006 \u0003אמר רבה: כל\u0004 דבר שנמכר \u0003לשוק\u0004 הרי המוכר \u0003אימלוכי מימלך\u0004 \u0005[נמלך בדעתו].\u0006 \u0003אמר: אי מזדבן\u0004 \u0005[אם ימכר] —\u0006 \u0003מזדבן\u0004 \u0005[ימכר],\u0006 \u0003אי לא מזדבן\u0004 \u0005[אם לא ימכר\u0006 לצורך הקרבנות\u0005] —\u0006 \u0003איפוק בהו אנא\u0004 \u0005[אצא בהם אני]\u0006 לצורך מצה, וכיון שמתחילה חשב על האפשרות שישמשו לצורך מצה — יכול לצאת בהן."],["\u0003ואלו ירקות שאדם יוצא בהן ידי חובתו בפסח\u0004 לשם מרור: \u0003בחזרת, בתמכא, ובחרחבינא, ובעולשין, ובמרור. יוצאין בהן בין\u0004 שהיו \u0003לחין בין\u0004 שהיו \u0003יבשין, אבל לא כבושין\u0004 במים או בחומץ \u0003ולא שלוקין\u0004 ברותחים \u0003ולא מבושלין.\u0004","וירקות שונים אלה כולם יחד \u0003מצטרפין לכזית\u0004 ואין צורך לאכול כדי שיעור דווקא מאחד מהן \u0003ויוצאין\u0004 ידי חובה \u0003בקלח שלהן\u0004 ולאו דווקא בעלים. ויוצאים בהם ידי חובה גם \u0003בדמאי ובמעשר ראשון שנטלה תרומתו\u0004 ונתנה לכהן \u0003ומעשר שני והקדש שנפדו.\u0004","תחילה מזהים את שמות הצמחים. \u0003חזרת\u0004 היא \u0003חסא. עולשין\u0004 הם הקרויים \u0003הינדבי. תמכא, אמר רבה בר בר חנה:\u0004 בארמית \u0003תמכתא שמה. חרחבינא, אמר ר' שמעון בן לקיש:\u0004 זוהי \u0003אצוותא דדיקלא\u0004 (צמח המטפס מסביב לדקל), \u0003ובמרור\u0004 הוא הצמח הקרוי \u0003מרירתא.\u0004","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003בר קפרא: אלו ירקות שאדם יוצא בהן ידי חובתו בפסח\u0004 לשם מרור: \u0003בעולשין, ובתמכא, בחרחלין, בחרחבינין, ובחזרין\u0004 (חזרת). \u0003רב יהודה אומר: אף עולשי שדה, ועולשי גינה, וחזרת.\u0004","ותוהים: מדוע אמר אף \u0003עולשי גינה וחזרת? הא תנא לה רישא\u0004 \u0005[הרי שנה אותה\u0006 ב\u0005תחילה]!\u0006 ומפרשים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך היתה כוונתו: \u0003אף עולשי שדה\u0004 דינם \u0003כעולשי גינה וחזרת\u0004 ויוצאים בהם ידי חובת מרור. \u0003ר' מאיר אומר: אף\u0004 הצמחים \u0003עסווס וטורא ומר ירואר. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוסי: עסווס וטורא\u0004 צמח \u0003אחד הוא\u0004 ויש לו שני שמות. \u0003ומר זה הוא\u0004 הקרוי \u0003ירואר,\u0004 כלומר גם כאן יש שני שמות של צמח אחד.","\u0003תני דבי\u0004 \u0005[שנה\u0006 חכם \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שמואל: אלו ירקות שאדם יוצא בהן ידי חובתו בפסח: בחזרת, בעולשין, ובתמכא, ובחרבינין, ובחרגינין, ובהרדופנין. ר' יהודה אומר: אף חזרת יולין וחזרת גלין כיוצא בהן.\u0004","\u0003ר' אילעא אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' אליעזר: אף ערקבלים\u0004 יוצאים בהם משום מרור, \u0003וחזרתי על כל תלמידיו\u0004 של ר' אליעזר \u0003ובקשתי לי חבר\u0004 ששמע אף הוא דברים אלה מפיו, \u0003ולא מצאתי. וכשבאתי לפני ר' אליעזר בן יעקב, הודה לדברי.\u0004","\u0003ר' יהודה אומר: כל\u0004 צמח \u0003ש\u0004חותכים אותו ו\u0003יש לו\u0004 במקום החתך \u0003שרף\u0004 לבן ראוי למרור. \u0003ר' יוחנן בן ברוקה אומר: כל שפניו מכסיפין\u0004 \u0005[חוורים],\u0006 כלומר שצבעו ירוק בהיר. ו\u0003אחרים אומרים: כל ירק מר יש לו שרף ופניו מכסיפין. אמר ר' יוחנן: מדברי כולן נלמד\u0004 אם נסתכל בירקות שהזכירו: \u0003ירק מר יש לו שרף ופניו מכסיפין. אמר רב הונא: הלכה כאחרים.\u0004","\u0003רבינא אשכחיה\u0004 \u0005[מצא]\u0006 את \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא דהוה מהדר אמרירתא\u0004 \u0005[שהיה מחזר על מרור]\u0006 לצאת דווקא בו חובת מרור. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 שאתה מחזר אחריה? משום \u0003דמרירין טפי\u0004 \u0005[ש\u0006הם \u0005מרים ביותר],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003חזרת תנן\u0004 \u0005[שנינו]\u0006 ראשונה במשנה, משמע שהיא ראשונה במעלה. וכן \u0003תנא דבי\u0004 \u0005[שנה\u0006 חכם \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל: חזרת\u0004 בראשונה, \u0003ואמר ר' אושעיא: מצוה\u0004 יתרה \u0003בחזרת\u0004 לצאת בה חובת מרור. \u0003ואמר רבא: מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003חזרת — חסא.\u0004","\u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003חסא,\u0004 כלומר מה משמעות שם זה לענין פסח — ש\u0003חס רחמנא עילוון\u0004 \u0005[הקדוש ברוך הוא עלינו].\u0006 \u0003ואמר ר' שמואל בר נחמני אמר ר' יונתן: למה נמשלו מצריים כמרור?\u0004 שהכתוב אומר \"וימררו את חייהם\", \u0003לומר לך מה מרור זה שתחילתו רך וסופו קשה, אף מצריים תחילתן רכה\u0004 שהיו משלמים שכרם, \u0003וסופן קשה\u0004 שנשתעבדו בהם כעבדים, ודבר זה נכון לגבי החסה שבסופה נעשית מרה. אבל אינו כן לגבי הצמחים האחרים שהם מרים מתחילתם. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הדרי\u0004 \u0005[חוזר אני]\u0006 \u0003בי,\u0004 ואף אני אהדר לצאת ידי חובת מרור בחזרת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב רחומי לאביי: ממאי דהאי\u0004 \u0005[ממה,\u0006 מנין לנו \u0005שזה]\u0006 \u0003המרור מין ירק הוא? אימא מרירתא דכופיא\u0004 \u0005[ו\u0006אולי \u0005אומר\u0006 שהוא \u0005מרתו של\u0006 דג \u0005הכופיא]\u0006 המרה ביותר, ולא רק מין צמח? ענה לו: \u0003דומיא\u0004 \u0005[בדומה]\u0006 \u0003למצה, מה מצה\u0004 נעשית מ\u0003גידולי קרקע\u0004 בלבד — \u0003אף מרור גידולי קרקע\u0004 בלבד. ושואלים בכל זאת: מדוע דווקא ירקות \u0003ואימא\u0004 \u0005[ו\u0006אולי \u0005אומר]\u0006 שיצאו ידי חובת מרור בצמח ה\u0003הירדוף\u0004 שהוא מין עץ מר? ומשיבים: \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003מצה, מה מצה מין זרעים\u0004 ולא אילן, \u0003אף מרור מין זרעים.\u0004","ושואלים: \u0003ואימא\u0004 \u0005[ו\u0006אולי \u0005אומר]\u0006 \u0003הרזיפו\u0004 שהוא מין זרעים! והשיב: \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003מצה, מה מצה\u0004 הנעשית מצמחים כאלה \u0003שניקחת בכסף מעשר\u0004 שהם מוגדרים כמאכל אדם, \u0003אף מרור\u0004 צריך להיות מין \u0003שניקח בכסף מעשר\u0004 ולא ירק בר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר רב חנין לאביי: אימא\u0004 \u0005[אומר]\u0006 \u0003מרור\u0004 שכתוב במקרא \u0003חד\u0004 \u0005[אחד]\u0006 בלבד הוא, שיוצאים ידי חובה רק בצמח אחד המר ביותר! ענה לו: \u0003\"מרורים\" כתיב\u0004 \u0005[נאמר]\u0006 ונלמד מכאן שכל המינים המרים כשרים. והקשה לו: \u0003ואימא\u0004 \u0005[ואומר]\u0006 \u0003\"מרורים\" — תרי\u0004 \u0005[שניים],\u0006 ונצא ידי חובה רק בשני מינים ולא יותר! אמר לו: \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003מצה, מה מצה — מינין הרבה\u0004 יוצאים בהם משום מצה, \u0003אף מרור מינין הרבה.\u0004","\u0003אמר רבה בר רב הונא אמר רב: ירקות שאמרו חכמים שאדם יוצא בהן ידי חובתו בפסח\u0004 לשם מרור, \u0003כולן נזרעין בערוגה אחת.\u0004 ושואלים: האם דבר זה בא \u0003למימרא\u0004 \u0005[לומר]\u0006 \u0003דלית בהו\u0004 \u0005[שאין בהם]\u0006 \u0003משום כלאים?\u0004 שכולם מינים קרובים כל כך, שאפשר לזורעם בערוגה אחת ואין בעירובם משום כלאי זרעים?","על כך \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא:\u0004 שנינו, \u0003חזרת וחזרת גלין, עולשין ועולשי שדה, כרישין וכרישי שדה, כוסבר וכוסבר שדה, חרדל וחרדל מצרי, ודלעת המצרי והרמוצה\u0004 (מין דלעת) — \u0003אינם כלאים זה בזה.\u0004 ומכאן נלמד: \u0003חזרת וחזרת גלין — אין\u0004 \u0005[כן]\u0006 מותר לזרעם יחד, אולם \u0003חזרת ועולשין\u0004 — \u0003לא,\u0004 שהם כלאים!","\u0003וכי תימא כולהו בהדדי קתני להו\u0004 \u0005[ואם תאמר כולם יחד שנה אותם],\u0006 שכל הצמחים המנויים כאן כולם יחד אין בהם משום כלאים זה בזה. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב\u0004 עצמו: \u0003זוגות זוגות קתני\u0004 \u0005[שנינו]\u0006 כלומר, שכל אחד מזוגות הצמחים ששנינו במשנה מותר לזרעו יחד עם בן זוגו, כי רק הם בני אותו מין, ואם כן ברור שאי אפשר לזרוע חזרת ועולשין יחד, וכיצד אמר רב שכולם נזרעים בערוגה אחת!","ומתרצים: \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 \u0003נזרעין\u0004 ש\u0003אמר רב\u0004 — הכוונה \u0003נזרעין כהלכתן,\u0004 כלומר שאפשר לזרוע אותם כפי שמתירה ההלכה לזרוע זרעים שונים בערוגה אחת בהפסק ראוי, בלא לעבור על דיני כלאים. ותוהים: אם בזריעה \u0003כהלכתן,\u0004 הלוא כבר \u0003תנינא\u0004 \u0005[שנינו]:\u0006"],["\u0003ערוגה שהיא ששה על ששה טפחים — זורעין בתוכה חמשה\u0004 מיני \u0003זרעונין, ארבעה\u0004 סוגים \u0003על ארבע רוחות הערוגה ואחת באמצע,\u0004 משמע שמותר לזרוע מינים שונים בערוגה אחת בהפסק הראוי. ודוחים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003בזרעים\u0004 בלבד, \u0003אבל בירקות לא,\u0004 שאסור לזרוע מיני ירק אחדים בערוגה אחת אפילו בהפסק הראוי, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמותר.","ותוהים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003ירקות אלימא\u0004 \u0005[חמורים]\u0006 \u0003מזרעים\u0004 לענין זה? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה בכלאים\u0005]:\u0006 \u0003כל מיני זרעים אין זורעים בערוגה אחת\u0004 אפילו על ידי הפסק, \u0003וכל מיני ירקות זורעים בערוגה אחת,\u0004 הרי שירקות חמורים פחות מזרעים! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003הני מרור\u0004 \u0005[מרור זה]\u0006 \u0003מין זרעים נינהו\u0004 \u0005[הוא]\u0006 ולא ירקות ויהיה אסור לזורעם בערוגה אחת עם זרעים אחרים, על זה \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכולם מיני ירקות הם.","ותוהים: מרור מין \u0003זרעים סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]\u0006 \u0003ירקות, ו\u0004אף \u0003תני\u0004 \u0005[שנה]\u0006 \u0003בר קפרא ירקות, ו\u0004כן \u0003תני דבי\u0004 \u0005[שנה\u0006 חכם \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל: ירקות!\u0004 ומשיבים: \u0003חזרת איצטריכא ליה\u0004 \u0005[נצרכה לו]\u0006 להשמיענו. \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וסופה להקשות\u0004 — נעשית כאחד ממיני הזרעים, \u0003ניתיב לה רווחא טפי\u0004 \u0005[ניתן לה\u0006 בערוגה \u0005רווח יותר].\u0006","וכעין ראיה לדבר: \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003אמר ר' יוסי בר חנינא, קלח של כרוב שהוקשה — מרחיבין לו\u0004 מקום כדי \u0003בית רובע,\u0004 ואין זורעים דברים אחרים בצידו! \u0003אלמא\u0004 \u0005[מכאן]:\u0006 \u0003כיון\u0004 ש\u0003סופו להקשות — יהבינן ליה רווחא טפי\u0004 \u0005[נותנים לו רווח יותר],\u0006 \u0003הכא נמי ניתיב ליה רווחא טפי\u0004 \u0005[כאן גם כן ניתן לה\u0006 בחזרת \u0005רווח יותר],\u0006 \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכל מיני המרור ואפילו החזרת נזרעים יחד בערוגה אחת, ואין צורך בהגדלת הרווח.","שנינו במשנה שמיני המרור \u0003יוצאין בהן בין לחין בין יבשין. אמר רב חסדא: לא שנו אלא בקלח\u0004 (שורש), \u0003אבל\u0004 אם רוצה לצאת ידי חובה \u0003בעלין,\u0004 אם היו \u0003לחין — אין\u0004 \u0005[כן]\u0006 יוצא ידי חובתו, אבל \u0003יבשין — לא.\u0004","ושואלים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי מששנינו\u0006 ב\u0005סוף\u0006 המשנה\u0005]\u0006 \u0003בקלח שלהן, מכלל דרישא\u0004 \u0005[שבתחילת\u0006 המשנה\u0005]\u0006 הכוונה היא ל\u0003עלין?\u0004 ומשיבים: \u0003פרושי קא\u0004 \u0005[פירוש הוא]\u0006 \u0003מפרש\u0004 התנא את דבריו שבראש המשנה: \u0003כי קתני\u0004 \u0005[כאשר שנינו]\u0006 \u0003בין לחין בין יבשין — על ה\u0004\u0003קלח\u0004 שנינו ולא על העלים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממקור אחר, שנינו: \u0003יוצאין בהן ובקלח שלהן — בין לחין בין יבשין,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: לחין — יוצאין בהן, יבשין\u0004 — \u0003אין יוצאין בהן. ושוין\u0004 ר' מאיר וחכמים \u0003שיוצאין בהן כמושין\u0004 אם נבלו קצת ואינם רעננים עוד. \u0003אבל לא כבושין ולא שלוקין ולא מבושלין,\u0004","\u0003כללו של דבר: כל שיש בו טעם מרור — יוצאין בו, וכל שאין בו טעם מרור — אין יוצאין בו.\u0004 ומכאן שגם ר' מאיר וגם חכמים אינם מחלקים בין העלים ובין הקלח! ומשיבים: \u0003תרגומא\u0004 \u0005[תרגומו\u0006 והסברו\u0005]\u0006 על ה\u0003קלח,\u0004 שמה שאמר ר' מאיר שיוצאים בלחים וביבשים — הכוונה היתה לקלח ולא לעלים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין יוצאין בהן כמושין. משום\u0004 \u0005[בשם]\u0006 \u0003ר' אליעזר בר' צדוק אמרו: יוצאין בהן\u0004 אף \u0003כמושין.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: מהו שיצא אדם ידי חובתו במרור של מעשר שני בירושלים? אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' עקיבא\u0004 המתיר במצת מעשר שני משום שיש לה היתר במושבות לכשתיטמא \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003במצה\u0004 שחובתה \u0003דאורייתא, נפיק\u0004 \u0005[מן התורה, יוצא].\u0006 \u0003במרור דרבנן\u0004 \u0005[ש\u0006הוא \u0005מדברי סופרים]\u0006 בדורותינו שאין קרבן הפסח \u0003מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר כן?","\u0003כי תיבעי לך אליבא\u0004 \u0005[כאשר תישאל לך\u0006 הרי זה \u0005על פי\u0006 שיטת\u0005]\u0006 \u0003ר' יוסי הגלילי\u0004 האוסר במצת מעשר שני, \u0003מאי\u0004 \u0005[מה\u0006 ההלכה\u0005]?\u0006 וצדדי הספק: \u0003במצה דאורייתא\u0004 \u0005[ש\u0006היא \u0005מן התורה]\u0006 \u0003הוא\u0004 ש\u0003לא נפיק\u0004 \u0005[יוצא],\u0006 \u0003אבל במרור דרבנן נפיק\u0004 \u0005[ש\u0006הוא \u0005מדברי סופרים יוצא\u0006 בו\u0005],\u0006","\u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כל\u0004 מה \u0003דתקינו רבנן\u0004 \u0005[שתיקנו חכמים]\u0006 \u0003כעין דאורייתא תקון\u0004 \u0005[דיני התורה תיקנו],\u0006 ומה שאין יוצאים בו למצוה שהיא חיוב מהתורה, אף אין יוצאים בו למצוה שהיא מדברי סופרים. \u0003אמר רבא: מסתברא\u0004 \u0005[מסתבר\u0006 לומר\u0005]\u0006 \u0003מצה ומרור\u0004 הושוו בכתוב, ולכן ראוי לומר שכשם שאין יוצאים במעשר שני משום מצה, אף אין יוצאים בו משום מרור.","\u0003אין שורין את המורסן\u0004 (הפסולת הגסה של הקמח) \u0003לתרנגולים\u0004 שמא יחמיץ, \u0003אבל חולטין\u0004 (מרתיחים) אותו ברותחים שאינו יכול להחמיץ, ואז מותר להאכילו להם. \u0003האשה לא תשרה את המורסן שתוליך בידה למרחץ\u0004 (להשתמש בו לניקוי בשרה), \u0003אבל שפה היא\u0004 את המורסן \u0003בבשרה\u0004 כשהמורסן \u0003יבש,\u0004 ואפילו היה בשרה לח מן המים. וכן אמרו: \u0003לא ילעוס אדם חיטין ויניח על מכתו\u0004 (פצעו) \u0003מפני שהן מחמיצות\u0004 על ידי לעיסה ורוק.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אלו דברים שאין באין לידי חימוץ: האפוי, והמבושל וחלוט שחלטו ברותחין.\u0004 על הקביעה כי ה\u0003מבושל\u0004 אינו בא לידי חימוץ שואלים: מדוע? והלוא עד ש\u0003מבשל ליה, מחמע\u0004 \u0005[אותו, יחמיץ]!\u0006 ומשיבים, \u0003אמר רב פפא: האפוי שבישלו קאמר\u0004 \u0005[הוא אומר]\u0006 כלומר, אם דבר אפוי מתחילה ואחר כך בושל — אינו מחמיץ, אבל אם בישלו בלבד — מחמיץ.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יוסי בר' יהודה אומר: קמח שנפל לתוכו דלף\u0004 (טיפות נוטפות) של מים \u0003אפילו\u0004 היה דולף \u0003כל היום כולו — אינו בא לידי חימוץ,\u0004 משום שכל עוד המים הדולפים הם בתנועה אינם מניחים לקמח להחמיץ, \u0003אמר רב פפא: והוא דעביד טיף להדי טיף\u0004 \u0005[שמטפטף טיפה בתוך טיפה],\u0006 שאין רגע שבו נמצא הקמח או חלקו ללא טיפטוף מים.","\u0003אמרי דבי\u0004 \u0005[אמרו\u0006 חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא: ותיקא\u0004 (מאכל קמח הבלול במשקים שונים) \u0003שרי\u0004 \u0005[מותר]\u0006 לאוכלו בפסח. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003ותיקא אסור?!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דעבדיה במישחא ומילחא\u0004 \u0005[שעשאו בשמן ובמלח],\u0006 הריהו מותר. אבל \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דעבדיה במיא ומילחא\u0004 \u0005[שעשאו במים ומלח],\u0006 הריהו מחמיץ מחמת המים.","\u0003אמר מר זוטרא: לא לימחי איניש\u0004 \u0005[ימחה אדם]\u0006 את \u0003קדרא בקמחא דאבישנא\u0004 \u0005[\u0006קצף \u0005הקדירה בקמח קלי],\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 הוא \u0003לא בשיל שפיר\u0004 \u0005[מבושל יפה]\u0006 שלא נקלה כראוי, ויש בו משהו של קמח שלא נאפה ונקלה, \u0003ואתי\u0004 \u0005[ויבוא]\u0006 \u0003לידי חימוץ\u0004 בתוך הקדירה. \u0003אמר רב יוסף: לא ליחלוט איניש\u0004 \u0005[יחלוט אדם]\u0006 ברותחים"],["\u0003תרי חיטי בהדי הדדי\u0004 \u0005[שתי חיטים זו עם זו],\u0006 \u0003דילמא אזלא חדא ויתבה בציריא\u0004 \u0005[שמא תלך אחת ותשב בסדק]\u0006 של \u0003חברתה, ולא סליק להו דיקולא דמיא מארבע רוחתא\u0004 \u0005[ולא תעלה רתיחת המים מארבע רוחות],\u0006 \u0003ואתי\u0004 \u0005[ותבוא]\u0006 \u0003לידי חימוץ.\u0004","\u0003ואמר אביי: לא ליחרוך איניש תרי שבולי בהדי הדדי\u0004 \u0005[אל יקלה אדם שתי שיבולים זו עם זו],\u0006 \u0003דילמא נפקי מיא מהאי ובלע אידך\u0004 \u0005[שמא יצאו מים,\u0006 נוזלים, \u0005מזו ותבלע האחרת]\u0006 \u0003ואתיא\u0004 \u0005[ותבוא]\u0006 \u0003לידי חימוץ. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו חדא נמי\u0004 \u0005[אחת גם כן]\u0006 לא יקלה, \u0003דילמא נפיק מהאי רישא ובלע אידך רישא\u0004 \u0005[שמא יצא,\u0006 הנוזל \u0005מראשו ויבלעו\u0006 החיטים \u0005מראשו\u0006 מן הקצה \u0005הזה האחר]\u0006 של השיבולת! \u0003אלא אמר רבא:\u0004 אין לחשוש לכך, כי אלה \u0003מי פירות נינהו\u0004 \u0005[הם],\u0006 \u0003ומי פירות אינן מחמיצין.\u0004","ומוסיפים: \u0003והדר ביה\u0004 \u0005[וחזר בו]\u0006 \u0003אביי מההיא\u0004 \u0005[מ\u0006הלכתו \u0005זו]\u0006 בענין השיבולים, והגיע למסקנה ש\u0003כל אגב מדלייהו\u0004 \u0005[נפילתם]\u0006 \u0003לא מחמצי\u0004 \u0005[מחמיצים]\u0006 אלא כאשר הם שרויים ממש במים. ש\u0003אמר אביי: האי חצבא דאבישנא\u0004 \u0005[כד זה של קליות]\u0006 שמייבשים בו את השיבולים בתנור, אם היה \u0003סחיפא\u0004 \u0005[הפוך] —\u0006 \u0003שרי\u0004 \u0005[מותר],\u0006 שהמים שנפלטים אגב הקלייה נוזלים ויוצאים החוצה. אבל אם הוא \u0003זקיפא\u0004 \u0005[זקוף]\u0006 — \u0003אסור,\u0004 שהמים מצטברים למטה ונבלעים בחזרה בחיטים ועשויים להחמיץ אותם. \u0003רבא אמר: אפילו זקיפא\u0004 \u0005[זקוף] —\u0006 \u0003נמי שרי\u0004 \u0005[גם כן מותר],\u0006 כי \u0003מי פירות נינהו\u0004 \u0005[הן],\u0006 \u0003ומי פירות אינן מחמיצין.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין לותתין שעורין בפסח\u0004 (כלומר, אין שורין את התבואה במים להקל על קילוף המוץ או הטחינה). \u0003ואם לתת,\u0004 אם \u0003נתבקעו\u0004 השעורים מחמת התחלת החימוץ — \u0003אסורות, לא נתבקעו — מותרות.\u0004","\u0003ר' יוסי אומר:\u0004 אם רואה שהן מתנפחות — \u0003שורן בחומץ, וחומץ צומתן\u0004 \u0005[\u0006מחזיקן, \u0005מצמצמן]\u0006 ואינו נותן להן להחמיץ. \u0003אמר שמואל: אין הלכה כר' יוסי.\u0004","\u0003אמר רב חסדא אמר מר עוקבא:\u0004 מה שאמרו נתבקעו \u0003לא נתבקעו ממש\u0004 שרואים שיש בהן סדק, \u0003אלא כל שאילו מניחן על פי חבית\u0004 יין \u0003והן נתבקעות מאליהן\u0004 מחמת ריח היין הרי הן קרויות מבוקעות, \u0003ושמואל אמר: נתבקעו ממש.\u0004 מסופר: \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003שמואל עובדא בדורא דבי\u0004 \u0005[מעשה בכפר\u0006 של \u0005בית]\u0006 \u0003בר חשו\u0004 ואסר חיטים ש\u0003נתבקעו ממש,\u0004 ולא אסר באלה העומדות להיבקע.","\u0003אמר רבה: בעל נפש\u0004 כלומר, חסיד החושש ומחמיר על עצמו, \u0003לא ילתות\u0004 חיטים בפסח. ותוהים: \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דוקא\u0005]\u0006 \u0003בעל נפש? אפילו כולי עלמא נמי\u0004 \u0005[כולם גם כן]\u0006 \u0003דהא תניא\u0004 \u0005[שהרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין לותתין שעורין בפסח!\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003בעל נפש — אפילו חיטין דשרירי\u0004 \u0005[שהן קשות\u0006 משעורים\u0005]\u0006 \u0003לא ילתות,\u0004 שמא יבואו לידי חימוץ.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: מאן דציית ליה\u0004 \u0005[מי שמקשיב לו]\u0006 \u0003לאבא\u0004 (שמו הפרטי של רבה) — \u0003אכיל נהמא דעיפושא\u0004 \u0005[אוכל לחם מעופש]\u0006 בפסח, שבלא לתיתה אין הקמח מתוקן כל צרכו ואין לאכול מצה שאיננה מתוקנת כראוי. \u0003דהא בי\u0004 \u0005[שהרי בבית]\u0006 \u0003רב הונא לתתי\u0004 \u0005[היו לותתים]\u0006 \u0003ובי\u0004 \u0005[ובבית]\u0006 \u0003רבא בר אבין לתתי\u0004 \u0005[היו לותתים].\u0006 \u0003ורבא אמר:\u0004 לא רק בעל נפש צריך להחמיר, אלא \u0003אסור ללתות\u0004 כלל.","ותוהים: \u0003אלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]\u0006 \u0003אין לותתין שעורין בפסח,\u0004 הרי מכאן אפשר ללמוד: \u0003שעורין הוא\u0004 ש\u0003לא\u0004 ילתות, \u0003הא חיטי\u0004 \u0005[הרי חיטים] —\u0006 \u0003שרי\u0004 \u0005[מותר].\u0006 ומסבירים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר]\u0006 \u0003לא מיבעיא\u0004 \u0005[נצרכה לומר]\u0006 ב\u0003חיטין, כיון דאית ביה ציריא\u0004 \u0005[שיש בהן סדק] —\u0006 \u0003עיילי בהו מיא\u0004 \u0005[נכנסים בהם המים]\u0006 וממהרות להחמיץ מלתיתה, \u0003אבל שערי דשיעי, אימא שפיר דמי\u0004 \u0005[שעורים שהן חלקות, אמור שיפה,\u0006 שמותר \u0005הדבר],\u0006 \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאפילו שעורים אין לותתים.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא:\u0004 לא כך הוא אלא \u0003מותר ללתות, דתניא\u0004 \u0005[שכן שנינו\u0006 בברייתא\u0005]\u0006 ראיה לדבר: \u0003יוצאין\u0004 ידי חובת מצה \u0003בפת נקיה והדראה\u0004 (פת קיבר), \u0003ואי אפשר\u0004 שתהא פת \u0003נקיה בלא לתיתה,\u0004 שרק כך מסלקים לחלוטין את המוץ והקליפה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב פפא לרבא:\u0004 הרי שנינו \u0003הקמחין והסלתות של גוים של כפרים\u0004 אלה שעושים בכפרים — \u0003טהורים, ושל כרכין — טמאין\u0004 משום שבוודאי טחנו אותם רק לאחר לתיתה. ולאחר שנפלו מים על הדגן הרי הוא מוכשר לקבל טומאה, ונטמא מפני מגע הגוים.","של \u0003כפרים מאי טעמא\u0004 \u0005[מה הטעם]\u0006 אינם טמאים? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דלא לתתי\u0004 \u0005[שאינם לותתים]\u0006 ואינם מוכשרים לקבל טומאה, בכל זאת \u0003וקא קרי ליה\u0004 \u0005[והוא קורא לזה]\u0006 \u0003סולת,\u0004 משמע שאפשר לעשות סולת, כלומר קמח נקי, אף בלא לתיתה!","משיב לו: \u0003תרגומא אקמחא\u0004 \u0005[יש לתרגם\u0006 ולהסביר לגבי \u0005קמח]\u0006 שחילוק זה נאמר רק לגבי קמח בלבד, ולא בסולת שהיא טמאה תמיד מפני הלתיתה. \u0003בתר דנפיק\u0004 \u0005[אחר שיצא]\u0006 רבא \u0003אמר\u0004 רב פפא: \u0003מאי טעמא לא אימא ליה מהא\u0004 \u0005[מה הטעם לא אומר לו\u0006 הוכחה \u0005מכאן]\u0006 הלוא \u0003אמר ר' זירא אמר רב ירמיה אמר שמואל: חיטין של מנחות — אין לותתין אותם\u0004 ובכל זאת \u0003וקא קרי להו\u0004 \u0005[קורא אותן]\u0006 \u0003סולת,\u0004 שהרי נאמר בתורה במפורש שיש לעשותן סולת.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא:\u0004 לא זו בלבד שמותר ללתות אלא \u0003מצוה ללתות, שנאמר \"ושמרתם את המצות\"\u0004 (שמות יב, יז). ומדייקים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא דבעי\u0004 \u0005[שצריכים]\u0006 \u0003לתיתה — שימור למאי\u0004 \u0005[ל\u0006שם \u0005מה]\u0006 נאמר? \u0003אי\u0004 \u0005[אם]\u0006 \u0003שימור\u0004 של \u0003לישה — שימור\u0004 של \u0003לישה\u0004 בזמן לישת הקמח \u0003לאו\u0004 \u0005[לא]\u0006 \u0003שימור הוא,\u0004 שכן אם לא שמר קודם לכן את החיטים והקמח מחשש חימוץ, אין זו שמירה אם משגיח עליהן בשעת לישה שלא יחמיצו, ולא לכך נאמר ציווי השמירה.","וכן \u0003אמר רב הונא: בצקות של גוים\u0004 שיודעים שלא החמיצו — \u0003אדם ממלא כריסו מהן\u0004 בפסח, \u0003ובלבד שיאכל כזית מצה באחרונה\u0004 לצאת ידי חובת אכילת מצת מצוה. ונדייק: \u0003באחרונה — אין\u0004 \u0005[כן],\u0006 \u0003בראשונה\u0004 — \u0003לא,\u0004","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שאינו יוצא באלו? \u0003משום\u0004 ש\u0003לא עבד בהו\u0004 \u0005[עשה בהם\u0006 בבציקות אלה\u0005]\u0006 \u0003שימור,\u0004 ולכאורה יש אפשרות לשמירה כלשהי: \u0003ולעביד ליה\u0004 \u0005[ושיעשה להם]\u0006 \u0003שימור מ\u0004זמן \u0003אפיה ואילך\u0004 \u0005[והלאה]!\u0006 \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא נלמד מזה]\u0006 \u0003שימור מעיקרא בעינן\u0004 \u0005[מתחילה צריכים אנו],\u0006 ואם כן מתקבל על הדעת שהשימור צריך להיות מזמן לתיתה.","ודוחים: \u0003וממאי\u0004 \u0005[וממה]\u0006 מוכיח אתה דבר זה? \u0003דילמא שאני התם\u0004 \u0005[שמא שונה שם]\u0006 \u0003דבעידנא דנחית\u0004 \u0005[שבזמן שירד]\u0006 \u0003לשימור\u0004 שהוא זמן נתינת המים לקמח, \u0003לא עבד\u0004 \u0005[עשה]\u0006 \u0003לה שימור, אבל היכא דבעידנא דנחית\u0004 \u0005[במקום שבזמן שירד]\u0006 \u0003לשימור\u0004 שזהו זמן נתינת המים לקמח \u0003עביד לה\u0004 \u0005[עשה לו]\u0006 \u0003שימור, הכי נמי\u0004 \u0005[כך גם כן]\u0006 ש\u0003שימור\u0004 שב\u0003לישה הוי\u0004 \u0005[הרי הוא]\u0006 \u0003שימור,\u0004 ואין להוכיח מבצקות של גויים.","\u0003ואפילו הכי\u0004 \u0005[כך]\u0006 אף שהוכיחו שאין זו הוכחה מוכרחת \u0003לא הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003רבא\u0004 מדבריו ששימור מתחיל לפני הלישה. \u0003דאמר להו להנהו דמהפכי כיפי\u0004 \u0005[ש\u0006היה \u0005אומר להם לאלה שהופכים\u0006 וקושרים את \u0005עומרי התבואה\u0006 בשדה\u0005]:\u0006 \u0003כי מהפכיתו\u0004 \u0005[כאשר אתם מהפכים] —\u0006 \u0003הפיכו לשום\u0004 \u0005[הפכו לשם]\u0006 \u0003מצוה, אלמא קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003שימור מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003מתחלתו ועד סופו בעינן\u0004 \u0005[צריכים אנו].\u0006","ומסופר, כי \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא\u0004"],["\u0003מנקטא ליה אימיה בארבי\u0004 \u0005[היתה מביאה לו אמו\u0006 חיטים \u0005בעריבות],\u0006 שהיתה מכינה לו חיטים ומשמרתן מתחילת הקציר ומכניסה אותן בכלים כדי לשמרן עד פסח.","מסופר: \u0003ההוא ארבא דחיטי דטבעא\u0004 \u0005[ספינה אחת של חיטים שטבעה]\u0006 לפני פסח \u0003ב\u0004נהר \u0003חישתא, שריא\u0004 \u0005[התיר]\u0006 \u0003רבא לזבוני\u0004 \u0005[למוכרה]\u0006 \u0003לגוים\u0004 בפסח.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבה בר ליואי לרבא:\u0004 שנינו, \u0003בגד שאבד בו כלאים\u0004 כלומר, שנארג בו חוט צמר בבגד פשתים, או להיפך, ואין ידוע היכן הוא — \u0003הרי זה לא ימכרנו לגוי, ו\u0004אף \u0003לא יעשה בו מרדעת לחמור,\u0004 שיש לחשוש שמא יטול ממנו חתיכה שבה הכלאים ויתפרנה בבגדו. \u0003אבל עושין אותו תכריכין למת,\u0004 שאין לחשוש שמא יטול מן המת.","ונברר: \u0003לגוי מאי טעמא\u0004 \u0005[מה הטעם]\u0006 \u0003לא\u0004 ימכרנו — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דהדר מזבין\u0004 \u0005[שחוזר ומוכר אותו]\u0006 \u0003לישראל,\u0004 וכיון שאין הכלאים גלויים לכל — ישתמש בהם. ומטעם זה אף כאן יש לאסור למכור את החיטים הללו לגוים, שמא יחזרו וימכרו לישראל.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא: לזבינהו\u0004 \u0005[שימכרו]\u0006 את החיטים הללו \u0003קבא קבא\u0004 \u0005[קב קב],\u0006 כלומר כמויות קטנות \u0003לישראל\u0004 ולא כמות גדולה לאדם אחד, \u0003כי היכי דכליא\u0004 \u0005[כדי שיכלו]\u0006 החיטים הללו \u0003קמי פיסחא\u0004 \u0005[לפני הפסח]\u0006 ולא יבואו להיכשל באכילתן בפסח.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מוללין את הקדירה בפסח.\u0004 כלומר, אין נותנים קמח בקדירה כדי לספוג את הקצף והלכלוך העולים עליה בעת הבישול, \u0003והרוצה שימלול — נותן את הקמח, ואחר כך נותן את החומץ,\u0004 והחומץ מעכב את החימוץ. \u0003ויש אומרים: אף נותן את החומץ, ואחר כך נותן את הקמח,\u0004 שהחומץ מעכב את הקמח מלהחמיץ אפילו כשהוא מהול במים.","ושואלים: \u0003מאן\u0004 \u0005[מי הם]\u0006 \u0003יש אומרים\u0004 אלה?","\u0003אמר רב חסדא: ר' יהודה היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003האילפס והקדירה שהעבירן\u0004 (הורידם) מן האש כשהם \u0003מרותחין — לא יתן לתוכן תבלין\u0004 בשבת משום שהוא כמבשל, \u0003אבל נותן\u0004 תבלין \u0003לתוך הקערה או לתוך התמחוי\u0004 (כלי גדול) ששופכים לתוכם מן האילפס. \u0003ר' יהודה אומר: לכל\u0004 המאכלים שבכלי שהוסר מעל האש \u0003הוא נותן\u0004 תבלין, \u0003חוץ מדבר שיש בו חומץ וציר\u0004 שמפני חריפותו הריהו כרותח. וכיון שלדעת ר' יהודה חומץ הריהו כרותח, אם כן כשם שמכניסים קמח במים רותחים אינו מחמיץ, אף כשמכניסים אותו בחומץ כן הוא.","ושואלים: \u0003ונוקמה\u0004 \u0005[ונעמידה]\u0006 את דעת \"יש אומרים\" \u0003כ\u0004דברי \u0003ר' יוסי\u0004, \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' יוסי אומר\u0004 לגבי חיטים שהיו במים: \u0003שורן בחומץ, וחומץ צומתן\u0004 \u0005(\u0006מחזיקן, מצמצמן) ואינו נותן להן להחמיץ!","ומשיבים: \u0003כי אשמעינן ליה\u0004 \u0005[כאשר שמענו אותו]\u0006 את \u0003ר' יוסי, הני מילי דאיתיה בעיניה\u0004 \u0005[דברים אלה\u0006 אמורים \u0005כשישנו\u0006 החומץ \u0005בעינו],\u0006 ומפני חריפותו הוא פועל למניעת חימוץ, \u0003אבל על ידי תערובת — לא.\u0004","\u0003עולא אמר: אחד זה\u0004 חומץ בין בתחילה \u0003ואחד זה\u0004 בין בסוף — \u0003אסור,\u0004 שיש להחמיר באיסורים ולהשתדל שלא להגיע לחשש עבירה, \u0003משום\u0004 הפתגם הידוע: \u0003\"לך לך\" אמרינן נזירא, \"סחור סחור, לכרמא לא תקרב\"\u0004 \u0005[\"לך לך\" אומרים אנו לנזיר, \"סביב סביב, לכרם אל תקרב\"].\u0006 שהנזיר האסור ביין ובפרי הגפן, מוטב שאף לא יכנס בכרם, שמא מתוך כך ייכשל באכילה, וכן הוא בשאר איסורים.","מסופר: \u0003רב פפי שרי ליה לבורדיקי דבי ריש גלותא\u0004 \u0005[התיר להם לאופים שבבית ראש הגולה]\u0006 \u0003לממחה\u0004 \u0005[למחות]\u0006 את ה\u0003קדירה בחסיסי\u0004 \u0005[בקמח קלי],\u0006 \u0003אמר רבא: איכא דשרי כי האי מילתא בדוכתא דשכיחי עבדי\u0004 \u0005[\u0006האם \u0005יש\u0006 מי \u0005שמתיר דבר כמו זה במקום שמצויים העבדים]?\u0006 שהעבדים מזלזלים באיסורים, ועלולים להטיל קמח רגיל, ויכשילו באיסור חמץ בפסח! \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003רבא גופא מחי לה קידרא בחסיסי\u0004 \u0005[עצמו היה ממחה את הקדירה בקמח קלי].\u0006","\u0003אין נותנין קמח לתוך חרוסת\u0004 (מאכל מתובל חריף) כדי להקהות את חריפותו \u0003או לתוך החרדל,\u0004 שחריפותם של אלה מחישה את חימוץ הקמח. \u0003ואם נתן — יאכל מיד\u0004 לפני שיחמיץ, \u0003ור' מאיר אוסר,\u0004 שמא יחמיץ מיד.","ועוד אמרו: \u0003אין מבשלין את\u0004 קרבן \u0003הפסח לא במשקין ולא במי פירות\u0004 שהרי אמרה התורה שצריך לאכלו צלוי, \u0003אבל סכין\u0004 אותו בשעת צלייתו \u0003ומטבילין אותו\u0004 בשעת האכילה \u0003בהן.\u0004","ועוד אמרו: \u0003מי תשמישו של נחתום\u0004 שהוא מצנן בהם את ידיו או רוחץ בהם את הכלים — \u0003ישפכו\u0004 ולא ישתמשו בהם, \u0003מפני שהן מחמיצין,\u0004 שהרי משהו מן הקמח והעיסה נכנס לתוכם.","\u0003אמר רב כהנא: מחלוקת\u0004 ר' מאיר וחכמים כשנתן מקמח \u0003לתוך החרדל\u0004 שהוא חריף ביותר ואינו מניח להחמיץ, \u0003אבל לתוך חרוסת\u0004 שאינה כה חריפה — \u0003דברי הכל ישרף מיד,\u0004 שאינה מונעת חימוץ.","\u0003ותניא נמי הכי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אין נותנין קמח לתוך החרוסת, ואם נתן — ישרף מיד.\u0004 ואם נתנו \u0003לתוך החרדל, ר' מאיר אומר: ישרף מיד, וחכמים אומרים: יאכל מיד\u0004 לפני שיחמיץ. \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה אמר רב נחמן אמר שמואל: הלכה כדברי חכמים\u0004 בענין זה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה:\u0004"],["\u0003אחרוסת קאמר מר או אחרדל קאמר מר\u0004 \u0005[\u0006האם \u0005על חרוסת אמר אדוני\u0006 הלכה זו \u0005או על החרדל אמר אדוני]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]?\u0006 והלוא נאמרו יחד ולשניהם דין אחד!","אמר לו: יש הבדל על פי דברי \u0003רב כהנא,\u0004 שהרי \u0003אמר רב כהנא: מחלוקת\u0004 שנפל \u0003לתוך החרדל, אבל לתוך החרוסת — דברי הכל ישרף מיד.\u0004 והאם גם בענין זה נאמרה הלכה כדברי חכמים?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא שמיע לי\u0004 \u0005[שמעתי\u0006 הלכה זו\u0005],\u0006 \u0003כלומר לא סבירא\u0004 \u0005[סבור,\u0006 נראה\u0005]\u0006 \u0003לי\u0004 כמותה, ואיני מחלק בהלכה, ולדעתי אף בחרוסת התירו חכמים, והלכה כמותם אף בזה.","\u0003אמר רב אשי: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב כהנא מסתברא\u0004 \u0005[מסתבר],\u0006 \u0003מ\u0004מה ש\u0003אמר שמואל: אין הלכה כר' יוסי,\u0004 ואין אנו מקבלים את דעתו (לעיל פסחים מ,ב) שהחומץ אינו מניח לקמח להחמיץ. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003צמותי\u0004 \u0005[לצמת,\u0006 להפריע לחימוץ\u0005]\u0006 \u0003הוא\u0004 ש\u0003לא צמית\u0004 \u0005[מצמת],\u0006 \u0003הא חמועי מחמעא\u0004 \u0005[הרי להחמיץ,\u0006 הוא עצמו \u0005מחמיץ],\u0006 ולכן דבר שיש בו חומץ (כחרוסת) — יש לחשוש שהוא מחמיץ מיד.","ודוחים: \u0003לא,\u0004 אין מכאן הוכחה; \u0003דילמא\u0004 \u0005[שמא]\u0006 הוא \u0003לא מצמת צמית\u0004 \u0005[מצמת],\u0006 \u0003ו\u0004אף \u0003לא חמועי מחמע\u0004 \u0005[מחמיץ]\u0006 ואין להוכיח מכאן לעניננו.","שנינו במשנה ש\u0003אין מבשלין\u0004 את הפסח במשקים. \u0003תנו רבנן: \u0004להסברת הענין מביאים את הכתוב \"אל תאכלו ממנו נא ובשל מבושל במים כי אם צלי אש ראשו על כרעיו ועל קרבו\" (שמות יב, ט), ומדרש הכתוב \u0003\"במים\" — אין לי אלא\u0004 שאסור לבשלו \u0003במים,\u0004 שאסור לבשלו בתוך \u0003שאר משקין מנין?\u0004","\u0003אמרת: קל וחומר\u0004 הדברים, \u0003ומה מים שאין מפיגין טעמן\u0004 של הדברים המתבשלים בהם — \u0003אסורין, שאר משקין\u0004 שלהם טעם משלהם \u0003שמפיגין טעמן\u0004 של הדברים שמבשלים בהם \u0003לא כל שכן!\u0004","\u0003רבי אומר\u0004 לימוד אחר: \u0003\"במים\" — אין לי אלא מים, שאר משקין מניין\u0004 שאסורים לבשל בהם את הפסח — \u0003תלמוד לומר \"ובשל מבשל\", מכל מקום\u0004 כל סוג של בישול אסור.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 הלכה למעשה? ומשיבים: \u0003איכא בינייהו צלי קדר\u0004 כלומר, צלי שצולים בתוך קדירה ואין מוסיפים בו מים, אבל הוא מתבשל בתוך הרוטב שלו עצמו. שלדעת רבי אסור הוא משום בישול, ולדעת חכמים כל עוד אין מוסיפים מין משקה, אינו קרוי בישול.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"בשל מבשל\", מאי עבדי להו\u0004 \u0005[מה עושים\u0006 הם \u0005בו],\u0006 כיצד הם מבינים אותו? ומשיבים: \u0003מבעי ליה לכדתניא\u0004 \u0005[צריכים אותו לכמו ששנויה\u0006 הברייתא\u0005]:\u0006 \u0003בשלו ואחר כך צלאו, או שצלאו ואחר כך בשלו — חייב\u0004 משום בישול הפסח ולוקה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בשלו ואחר כך צלאו חייב, דהא בשליה\u0004 \u0005[שהרי בישלו]\u0006 וחייב על בישולו. \u0003אלא צלאו ואחר כך בשלו, הא\u0004 \u0005[הרי]\u0006 \u0003צלי אש הוא, אמאי\u0004 \u0005[מדוע]\u0006 חייב עליו?","\u0003אמר רב כהנא: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 של \u0005מי היא]?\u0006 שיטת \u0003ר' יוסי היא\u0004 שבישול שלאחר צליה מבטל את הצליה. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יוצאין\u0004 ידי חובת מצה \u0003ברקיק השרוי\u0004 במים או ברקיק \u0003מבושל\u0004 שעדיין \u0003לא נימוח,\u0004 אלו \u0003דברי ר' מאיר. ר' יוסי אומר: יוצאין ברקיק השרוי\u0004 בתבשיל, \u0003אבל לא במבושל, אף על פי שלא נימוח.\u0004 הרי שדעתו: שדבר שנאפה ואחר כך נתבשל איננו קרוי עוד אפוי אלא מבושל.","\u0003עולא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שההלכה במצה מבושלת היא כ\u0003ר' מאיר,\u0004 אין מקום להשוות, כי \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 בפסח, ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"ובשל מבשל\",\u0004 משמע \u0003מכל מקום\u0004 בכל דרך בישול אסור, מה שאין כן במצה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יכול צלאו כל צורכו יהא חייב — תלמוד לומר \"אל תאכלו ממנו נא ובשל מבשל במים\"\u0004 (שמות יב, ט). \u0003נא ובשל מבושל אמרתי לך\u0004 שאסור, \u0003ולא שצלאו כל צורכו.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 מדובר כאן\u0005]\u0006 \u0003אמר רב אשי: דשויא חרוכא\u0004 \u0005[שעשה\u0006 אותו \u0005חרוך],\u0006 כלומר, אפילו צלאו יותר מן הצורך אינו עובר עליו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יכול אכל כזית\u0004 מקרבן הפסח כשהוא \u0003חי יהא חייב — תלמוד לומר \"אל תאכלו ממנו נא ובשל מבשל\", נא ובשל אמרתי לך\u0004 בו איסור \u0003ולא חי.\u0004","\u0003יכול יהא מותר\u0004 לאוכלו חי אף מלכתחילה — \u0003תלמוד לומר \"כי אם צלי אש\"\u0004 (שמות יב, ט), שמצות עשה מלכתחילה לאוכלו צלי אש. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא\u0006 בדיוק\u0005]\u0006 \u0003נא? אמר רב:\u0004 זוהי דרגת צלי \u0003כדאמרי פרסאי\u0004 \u0005[כמו שאומרים הפרסים]:\u0006 \u0003אברנים\u0004 \u0005[\u0006צלוי \u0005למחצה].\u0006","\u0003אמר רב חסדא: המבשל בחמי טבריא,\u0004 אם בישל \u0003בשבת\u0004 — הרי הוא \u0003פטור.\u0004 שבישול שלא על האש, אינו נקרא בישול גמור לענין שבת. ו\u0003פסח שבשלו בחמי טבריא — חייב\u0004 עליו משום בישול.","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 לענין \u0003שבת\u0004 ש\u0003לא,\u0004 שבחמי טבריא אינו קרוי בישול, כי אש או \u0003תולדות אש\u0004 (דבר המוחם מן האש) \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שחמי טבריא אין חומם בא מכוח האש. ואם כן \u0003פסח נמי\u0004 \u0005[גם כן],\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003תולדות אש הוא,\u0004 ואין לקרוא לבישול זה בישול גמור!","\u0003אמר רבא: מאי\u0004 \u0005[מהו]\u0006 \u0003\"חייב\" דקתני\u0004 \u0005[ששנינו]\u0006 פה הכוונה \u0003דקא עבר משום \"צלי אש\"\u0004 כלומר, שלא קיים את מצות העשה שבתורה שיהא הפסח צלי אש אף שלא עבר על בישול.","ואכן \u0003רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן מתני לה להא\u0004 \u0005[היה שונה את\u0006 ההלכה \u0005הזו]\u0006 של \u0003רב חסדא בהדיא\u0004 \u0005[במישרין],\u0006 \u0003אמר רב חסדא: המבשל בחמי טבריא בשבת — פטור, ופסח שבשלו בחמי טבריא — חייב, שעבר משום \"צלי אש\".\u0004","\u0003אמר רבא: אכלו נא\u0004 —"],["\u0003לוקה שתים,\u0004 משום שעבר על \"אל תאכלו ממנו נא\" (שמות יב, ט) וגם עבר על האמור \"אל תאכלו ממנו וגו' כי אם צלי אש\" (שמות יב, ט), ואם אכלו \u0003מבושל — לוקה שתים,\u0004 משום שהוא \"ובשל מבושל\" (שמות יב, ט), ומשום \"כי אם צלי אש\". אם אכלו לאחר שהיה הקרבן \u0003נא ו\u0004אחר כך \u0003מבושל — לוקה שלש\u0004 משום נא, משום מבושל, ומשום \"כי אם צלי אש\".","\u0003אביי אמר: אין לוקין על לאו שבכללות,\u0004 כי האיסור של \"כי אם צלי אש\" כולל סוגי בישול שונים, ואין לוקים על לאו שאינו מיוחד לאיסור אחד.","ובביאור דברי אביי אלה נחלקו; \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003תרתי\u0004 \u0005[שתי\u0006 מלקיות\u0005]\u0006 \u0003הוא\u0004 ש\u0003לא לקי\u0004 \u0005[לוקה]\u0006 שאין הלאו של \"כי אם צלי אש\" מתווסף על האיסור הפרטי של נא או מבושל, אבל \u0003חדא מיהת לקי\u0004 \u0005[אחת מכל מקום לוקה].\u0006 שאם עשה את הפסח בדרך שאינו מבושל כדרכו או נא וגם אינו צלי — לוקה עליו, שהרי עבר רק משום \"כי אם צלי אש\".","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003חדא נמי לא לקי\u0004 \u0005[אחת גם כן אינו לוקה]\u0006 \u0003דלא מייחד לאויה כלאו דחסימה\u0004 \u0005[שאין הלאו שלו מיוחד\u0006 לענין אחד \u0005כמו הלאו של חסימה]\u0006 שאת ההלכה שעונש ביטול מצות לא תעשה הוא מלקות, למדים מן הלאו של \"לא תחסום שור בדישו\" שנסמך בתורה לדין המלקות. וממנו למדים שכל איסור לאו שאיננו מיוחד לענין אחד כאיסור זה של חסימה — אין לוקים עליו, וכיון שהלאו שלא לאכול מן הבשר אלא צלי איננו מיוחד לדין אחד בלבד — אין לוקים עליו כלל. מחלוקת דומה לזו היתה גם בדין אחר.","\u0003רבא אמר:\u0004 נזיר ש\u0003אכל זג\u0004 (קליפה) של ענב — \u0003לוקה שתים,\u0004 שנאמר בתורה \"כל ימי נזרו מכל אשר יעשה מגפן היין מחרצנים ועד זג לא יאכל\" (במדבר ו, ד), ולוקה הן משום אכילת הזג שנתפרש איסורה והן משום שאכל מדבר שנעשה מגפן היין. וכן אם אכל \u0003חרצן — לוקה שתים,\u0004 משום איסור אכילת חרצן שנתפרש איסורו, ומשום אשר יעשה מגפן היין. אכל \u0003זג וחרצן — לוקה שלש,\u0004 משום זג, משום חרצן, ומשום \"אשר יעשה מגפן היין\".","\u0003אביי אמר\u0004 כשיטתו בפסח: \u0003אין לוקין על לאו שבכללות. איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003תרתי\u0004 \u0005[שתי\u0006 מלקיות\u0005]\u0006 \u0003הוא\u0004 ש\u0003לא לקי\u0004 \u0005[לוקה],\u0006 \u0003חדא מיהת לקי\u0004 \u0005[\u0006על \u0005אחת מכל מקום לוקה].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003חדא נמי לא לקי, דלא מייחד לאויה כלאו דחסימה\u0004 \u0005[אחת גם כן אינו לוקה, שאין הלאו שלו מיוחד\u0006 לענין אחד \u0005כמו הלאו של חסימה].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אכל כזית נא\u0004 מקרבן פסח \u0003מבעוד יום\u0004 בארבעה עשר בניסן — \u0003פטור,\u0004 אכל \u0003כזית נא משחשיכה — חייב. אכל כזית צלי\u0004 מקרבן פסח \u0003מבעוד יום — לא פסל עצמו מבני חבורה\u0004 שלו. שאף שאין אדם אוכל פסח בשתי חבורות, והאוכל מפסח אחד פסל עצמו מכל קרבן פסח אחר. אבל כיון שהיה זה לפני זמן חובת אכילת הפסח — אינו פוסל. אבל אכל \u0003כזית צלי משחשיכה,\u0004 שכבר חלה חובת אכילת הפסח — \u0003פסל עצמו מבני החבורה\u0004 שנמנה עמה קודם לכן.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003יכול אכל כזית נא\u0004 מקרבן הפסח \u0003מבעוד יום יהא חייב\u0004 על כך, \u0003ודין\u0004 (קל וחומר] \u0003הוא: ומה בשעה שישנו בקום אכול צלי\u0004 כלומר, משחשיכה, שיש מצות עשה לאכול את הפסח — \u0003ישנו\u0004 עם זאת \u0003ב\"בל תאכל נא\". בשעה שאינו בקום אכול צלי,\u0004 מבעוד יום — \u0003אינו דין שישנו ב\"בל תאכל נא\"?\u0004","\u0003או לא\u0004 נאמר כך, ונטען: \u0003בשעה שאינו בקום אכול צלי — ישנו בבל תאכל נא,\u0004 אבל משחשיכה \u0003בשעה שישנו בקום אכול צלי — אינו בבל תאכל נא,\u0004 שאין איסור אכילת נא חל אלא לפני הזמן הראוי לאכילת הפסח.","\u0003ואל תתמה\u0004 על סברה זו, \u0003שהרי הותר מכללו אצל צלי,\u0004 שכן לפני חשיכה אסור היה לאכול מן הפסח כלל, אפילו צלי, ומשחשכה הותר. ושמא בדיעבד אף באכילת נא אינו עובר?","\u0003תלמוד לומר: \"אל תאכלו ממנו נא ובשל מבשל במים כי אם צלי אש\"\u0004 (שמות יב, ט), \u0003שאין תלמוד לומר \"כי אם צלי אש\",\u0004 שהרי כבר נאמר \"ואכלו את הבשר בלילה הזה צלי אש\" וגו' (שמות יב, ח), \u0003ומה תלמוד לומר \"כי אם צלי אש\"? לומר לך בשעה שישנו בקום אכול צלי — ישנו בבל תאכל נא, בשעה שאינו בקום אכול צלי — אינו בבל תאכל נא.\u0004","\u0003רבי אומר: אקרא אני \"בשל\"\u0004 ודי במקרא זה, \u0003מה תלמוד לומר\u0004 החזרה \u0003\"מבשל\" — שיכול אין לי אלא שבישלו משחשיכה\u0004 שהוא עיקר זמנו יהא חייב עליו, אבל \u0003בשלו מבעוד יום מנין\u0004 שחייב עליו — \u0003תלמוד לומר \"בשל מבשל\" מכל מקום.\u0004","ותוהים: \u0003והאי\u0004 \u0005[ו\u0006הרי \u0005זה]\u0006 \u0003\"בשל מבשל\" אפקיה\u0004 \u0005[הוציאו]\u0006 \u0003רבי\u0004 עצמו ללמוד ממנו הלכה אחרת לענין איסור \u0003צלי קדר\u0004 (בשר המתבשל בקדירה בלא תוספת נוזלים כלשהם, פרט לאלו הנפלטים ממנו), \u0003ו\u0004כן \u0003ל\u0004בישול הפסח ב\u0003שאר משקין.\u0004 וכיצד הוא לומד עתה מכאן הלכה שונה לגמרי?","ומשיבים: \u0003אם כן,\u0004 אילו בא כתוב זה ללמדנו רק ענין אחד — \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003או \"בשל בשל\" או \"מבשל מבשל\",\u0004 ותהא זו לשון ריבוי פשוטה, \u0003מאי\u0004 \u0005[מה]\u0006 לשון כפולה וזרה של \u0003\"בשל מבשל\" — שמעת מינה תרתי\u0004 \u0005[לומד אתה מכאן שתים]\u0006 הן לדרך הבישול והן לזמן הבישול.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אכל צלי\u0004 מקרבן הפסח \u0003מבעוד יום\u0004 — \u0003חייב, וכזית נא משחשיכה\u0004 — \u0003חייב.\u0004","\u0003קתני\u0004 \u0005[שנה]\u0006 \u0003צלי דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003נא: מה נא\u0004 אם אכלו עבר \u0003בלאו, אף צלי,\u0004 אם אכלו מבעוד יום — עבר \u0003בלאו.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003נא\u0004 שחייבים עליו, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במקרא: \u0003\"אל תאכלו ממנו נא\", אלא צלי מנלן\u0004 \u0005[מנין לנו]\u0006 שעוברים עליו אם אכלו לפני זמנו?","ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 \u0003\"ואכלו את הבשר בלילה הזה\u0004 צלי אש ומצות על מרורים יאכלוהו\u0003\"\u0004 (שמות יב, ח), ומכאן למדים: \u0003בלילה — אין\u0004 \u0005[כן]\u0006 אוכלים, \u0003ביום — לא,\u0004 הרי שאסור באכילה לפני הלילה.","ושואלים: ועדיין \u0003האי\u0004 \u0005[\u0006איסור \u0005זה]\u0006 \u0003לאו הבא מכלל עשה הוא,\u0004 שלא נתפרש בתורה בלשון שלילה, \u0003ו\u0004יודעים אנו כי \u0003כל לאו הבא מכלל עשה\u0004 שנובע רק ממשמעות הלשון ממצות עשה — \u0003עשה\u0004 הוא, והעובר עליו נקרא עובר על מצות עשה, ולא על מצות לא תעשה!","\u0003אמר רב חסדא: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006"],["\u0003ר' יהודה היא, דתניא\u0004 \u0005[שכן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"\u0004ו\u0003שור ושה שרוע וקלוט נדבה תעשה אתו\u0004 ולנדר לא ירצה\u0003\"\u0004 (ויקרא כב, כג), ולמד מכאן: \u0003אותו\u0004 — את בעל המום שאינו ראוי לקרבן, \u0003אתה מתפיס\u0004 (יכול להקדיש) \u0003לבדק הבית\u0004 במקדש, \u0003ואי\u0004 (ואין) \u0003אתה מתפיס תמימים לבדק הבית,\u0004 שבהמה הראויה לקרבן אין להקדישה לנדבת בדק הבית. \u0003מכאן אמרו\u0004 חכמים: \u0003כל המתפיס תמימים לבדק הבית — עובר\u0004 על מצות \u0003עשה.\u0004","\u0003אין לי אלא\u0004 ללמוד מכאן שעובר \u0003בעשה,\u0004 שאף עובר \u0003בלא תעשה מנין — תלמוד לומר \"וידבר ה' אל משה לאמר\"\u0004 (ויקרא כב, יז), \u0003לימד על כל הפרשה כולה שיהא בלא תעשה\u0004 כל העובר עליה, אלה \u0003דברי ר' יהודה.\u0004","ומוסיפים, \u0003אמר לו רבי לבר קפרא: מאי\u0004 \u0005[מה]\u0006 \u0003משמע?\u0004 כלומר כיצד מבין ר' יהודה מהכתוב \"וידבר ה' אל משה לאמור\" שכל הפרשה כולה בלא תעשה?","\u0003אמר לו: דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"לאמר\".\u0004 והוא דורשו כמו: לא-אמור, \u0003\"לא\" נאמר בדברים,\u0004 שיש גם איסור לאו בדברים האמורים שם.","\u0003בי\u0004 \u0005[\u0006ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב אמרי\u0004 \u0005[היו אומרים]\u0006 בשינוי מועט: \u0003\"לאמר\" — לאו אמור,\u0004 שיש לומר לישראל שיש כאן מצוות לא תעשה בדבר זה. ומכל מקום למדנו לעניננו שלשיטת ר' יהודה לאו הבא מכלל \"לאמור\" נידון כלאו. ומתוך שנאמר בפסח \"ויאמר ה' אל משה ואל אהרן בארץ מצרים לאמור\" (שמות יב, א), הרי שכל שנאמר בפרשה נידון אף בלאו.","שנינו במשנה כי \u0003מי תשמישו של נחתום\u0004 נשפכים ואין משתמשים בהם משום חמץ שבהם. \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003שופכין\u0004 אותם \u0003במקום מדרון, ואין שופכין\u0004 אותם \u0003במקום האישבורן\u0004 (מקום שהמים נקוים בו). \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003שופכין במקום האישבורן!\u0004","ומתרצים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 מברייתא לברייתא; \u0003הא\u0004 \u0005[זה]\u0006 שאסרו באישבורן — \u0003דנפישי, דקוו\u0004 \u0005[\u0006כשהמים \u0005מרובים,\u0006 והם \u0005נקוים]\u0006 במקומם ואינם נבלעים בקרקע ומחמיצים. \u0003הא\u0004 \u0005[זה]\u0006 שהתירו — כשהם \u0003לא נפישי\u0004 \u0005[מרובים],\u0006 ו\u0003לא קוו\u0004 \u0005[נקוים],\u0006 ונבלעים בקרקע לפני שמספיקים להחמיץ.","ב\u0003אמר רב יהודה: אשה לא תלוש\u0004 את המצות \u0003אלא במים שלנו,\u0004 שהיו בבית במשך הלילה והתקררו בבית. כי אם יקחו מים פושרים כפי שהם נשאבים, יזרזו אלה את חימוצה של העיסה.","ומסופר: \u0003דרשה רב מתנה בפפוניא\u0004 להלכה זו. \u0003למחר אייתו כולי עלמא חצבייהו ואתו לגביה\u0004 \u0005[למחרת\u0006 בערב פסח \u0005הביאו הכל את כדיהם ובאו לפניו],\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הב לן מיא\u0004 \u0005[תן לנו מים].\u0006 כי הם הבינו \"מים שלנו\" — מים ששייכים לנו, לבית החכם, ולכן באו כולם אליו לקבל מהמים שלו. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא במיא דביתו אמרי\u0004 \u0005[אני במים שלנו\u0006 בלילה בבית \u0005אמרתי].\u0006","\u0003דרש רבא: אשה לא תלוש\u0004 את המצה \u0003בחמה\u0004 אלא בבית, \u0003ולא בחמי חמה\u0004 במים שהתחממו מחום השמש, \u0003ולא במים הגרופין מן המולייר\u0004 (ממיחם שיש בו גחלים), \u0003ולא תגביה ידה מן התנור,\u0004 כלומר לא תפסיק להתעסק באפיה \u0003עד שתגמור את כל הפת\u0004 מן העיסה שלא תחמיץ בינתים. \u0003וצריך\u0004 שיהיו לה \u0003שני כלים, אחד שמקטפת בו\u0004 כלומר, שנותנת את המים על העיסה, \u0003ואחד שמצננת בו את ידיה\u0004 לאחר הקיטוף, כדי שלא יחמיץ חום ידיה את העיסה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003עברה ולשה\u0004 במים חמים, \u0003מהו? מר זוטרא אמר: מותר, רב אשי אמר: אסור.\u0004","\u0003אמר מר זוטרא: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את הלכתי זו? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין לותתין השעורין בפסח. ואם לתת,\u0004 אם \u0003נתבקעו — אסורים, לא נתבקעו — מותרין.\u0004 הרי שגם מי שעובר על דברי חכמים ועושה שלא כדין, כל עוד שלא החמיץ ממש אין חכמים אוסרים. אף כאן לעניננו, כל עוד לא החמיצה העיסה ממש אין חכמים אוסרים אותה.","\u0003ורב אשי אמר: אטו כולהו חדא מחיתא מחיתינהו\u0004 \u0005[וכי\u0006 את \u0005כולם אורג אתה באריגה אחת]?!\u0006 וכי כל ההלכות כולן שוות זו לזו? \u0003היכא דאיתמר\u0004 \u0005[\u0006ב\u0005מקום שנאמר] —\u0006 \u0003איתמר\u0004 \u0005[נאמר]\u0006 שלא קנסו חכמים, \u0003והיכא\u0004 \u0005[ובמקום]\u0006 ש\u0003לא איתמר\u0004 \u0005[נאמר] —\u0006 \u0003לא איתמר\u0004 \u0005[נאמר],\u0006 ויש מקום לקנוס את האשה שעברה על דברי חכמים ולאסור את עיסתה.","","\u0003ואלו עוברין\u0004 עליהם \u0003בפסח\u0004 משום \"בל יראה\" ו\"בל ימצא\", אף על פי שלא כולם הם דברי מאכל ממש; \u0003כותח הבבלי\u0004 שהוא תבלין חריף שנותנים בו גם קמח, \u0003ושכר המדי, וחומץ האדומי, וזיתום\u0004 (מין שיכר) \u0003המצרי, וזומן של צבעים, ועמילן של טבחים, וקולן\u0004 (דבק) \u0003של סופרים.\u0004 \u0003ר' אליעזר אומר: אף תכשיטי נשים\u0004 שיש בהם חמץ.","","\u0003זה הכלל: כל שהוא ממין דגן\u0004 והחמיץ, אף שאינו לחם חמץ ממש — \u0003הרי זה עובר\u0004 עליו \u0003בפסח\u0004 משום \"בל יראה\" ו\"בל ימצא\". \u0003הרי אלו\u0004 שנמנו קודם \u0003באזהרה\u0004 (באיסור לא תעשה), \u0003ו\u0004אולם \u0003אין בהם משום כרת\u0004 אם אוכל אותם. כיון שהוזכר כותח במשנה מביאים ברייתא הדנה בכותח. \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003שלשה דברים נאמרים בכותח הבבלי: מטמטם\u0004 \u0005[סותם]\u0006 \u0003את הלב, ומסמא את העינים, ומכחיש\u0004 (מחליש, גורם חולי) \u0003את הגוף.\u0004","ומבארים: \u0003מטמטם את הלב — משום נסיובי דחלבא\u0004 \u0005[נסיוב החלב]\u0006 הנוזל הנותר כשמפרישים את הגבינה מן החלב, שכן היו נותנים בכותח את הנסיוב, והוא מאכל תפל וגרוע. \u0003ומסמא את העינים — משום מילחא\u0004 \u0005[מלח]\u0006 שיש בו, העשוי להיות סכנה לעינים. \u0003ומכחיש את הגוף\u0004 — \u0003משום קומניתא דאומא\u0004 \u0005[עיפוש הפת],\u0006 שמכניסים בכותח פירורי פת שהחמיצה מאד, כמעט עד כדי עיפוש. וכיון שהובאה ברייתא זו מביאים עוד דברים שנאמרו בעניני בריאות הגוף ובמאכלים; \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה דברים מרבין\u0004 את \u0003הזבל, וכופפין את הקומה\u0004 של אדם, \u0003ונוטלין אחד מחמש מאות ממאור עיניו של אדם\u0004 אם רגיל לאוכלם, \u0003אלו הם: פת קיבר\u0004 (העשויה מקמח לא משובח), \u0003ושכר חדש, וירק חי.\u0004 וכן \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת: \u0003שלשה דברים ממעטין את הזבל, וזוקפין את הקומה, ומאירין את העינים, אלו הם: פת נקייה\u0004 שנעשית מקמח סולת, \u0003בשר שמן, ויין ישן.\u0004 ומבארים: \u0003פת נקייה\u0004 —","","",""],["\u0003דסמידא\u0004 \u0005[של סולת],\u0006 \u0003בשר שמן — דצפירתא\u0004 \u0005[של עז]\u0006 שעדיין \u0003לא אפתח\u0004 \u0005[נפתחה,\u0006 ילדה\u0005],\u0006 \u0003יין ישן — עתיק עתיקי\u0004 \u0005[ישן נושן]\u0006 לפחות בן שלוש שנים.","ואומרים כלל: \u0003כל מילי\u0004 \u0005[דבר]\u0006 רפואה \u0003דמעלי להאי\u0004 \u0005[שמועיל לזה]\u0006 לחולי או לאבר — \u0003קשה להאי\u0004 \u0005[לזה],\u0006 \u0003ו\u0004כל \u0003דבר ש\u0004\u0003קשה להאי — מעלי להאי\u0004 \u0005[מועיל לזה],\u0006 \u0003בר\u0004 \u0005[חוץ]\u0006 \u0003מזנגבילא רטיבא, ופילפלי אריכתא\u0004 \u0005[זנגביל לח, ופלפלים ארוכים],\u0006 \u0003ופת נקייה, ובשר שמן, ויין ישן, דמעלי לכולי גופיה\u0004 \u0005[שמועילים לכל\u0006 איברי \u0005הגוף].\u0006","מעתה מבארים קצת את פרטי הדברים שהוזכרו במשנה. \u0003שכר המדי\u0004 מפני מה אסור בפסח, \u0003דרמו ביה מי שערי\u0004 \u0005[שמטילים\u0006 מכניסים \u0005בו\u0006 בני מדי \u0005מי שעורים].\u0006","\u0003\"וחומץ האדומי\"\u0004 אסור מפני \u0003דשדו בי שערי\u0004 \u0005[שמשליכים בתוכו שעורים].\u0006","\u0003אמר רב נחמן בר יצחק: בתחלה\u0004 כשבית המקדש היה קיים ו\u0003היו מביאים נסכים מיהודה\u0004 היתה הברכה שולטת ביינם והיה משתמר. ו\u0003לא היה יינן של יהודה מחמיץ, עד שנותנים לתוכם שעורים\u0004 להחמיצו. \u0003והיו קורין\u0004 (קוראים) \u0003אותו חומץ סתם,\u0004 כי יין שלא עשו מעשה להחמיצו, לא הגיע מעצמו לידי חימוץ.","\u0003ועכשיו\u0004 לאחר החורבן \u0003אין יינם של אדומיים מחמיץ עד שנותנים לתוכם שעורין, וקורין אותו חומץ האדומי, לקיים מה שנאמר\u0004 בצור, והוא הדין בשונאי ישראל אחרים \u0003\"\u0004יען אשר אמרה צור על ירושלים האח נשברה דלתות העמים נסבה אלי \u0003אמלאה החרבה\"\u0004 (יחזקאל כו, ב). ודרשו: \u0003אם מלאה זו\u0004 ירושלים — \u0003חרבה זו\u0004 אויבתה, \u0003ואם מלאה זו\u0004 האויבת — \u0003חרבה זו.\u0004 ולכן כאשר יש זמן נפילה לישראל, האויבים מגיעים להצלחה וגדולה שהיתה קודם נחלת ישראל. \u0003רב נחמן בר יצחק אמר: מהכא\u0004 \u0005[מכאן]\u0006 אפשר ללמוד דבר זה, שנאמר בעשו ויעקב \u0003\"ולאם מלאם יאמץ\"\u0004 (בראשית כה, כג), שכאשר עם זה עולה השני יורד, ששניהם כאחד אינם יכולים להיות בתוקפם.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יהודה: ביהודה, בראשונה הלוקח חומץ מעם הארץ\u0004 החשוד שאינו מפריש מעשרות כדין, \u0003אינו צריך לעשר, מפני שחזקה\u0004 שסתם חומץ \u0003אינו בא\u0004 לא היה נעשה \u0003אלא מהתמד\u0004 מפסולת הענבים. שלאחר סינון היין מן השמרים היו שופכים שוב מים עליהם וממצים את המשקה ואותו היו מחמיצים, שכן מתוך חוזקו של היין לא היה הוא עצמו מחמיץ, ומשקה זה הקרוי תמד, אין צריך להפריש ממנו מעשר. \u0003ו\u0004אילו \u0003עכשיו, הלוקח חומץ מעם הארץ צריך לעשר,\u0004 שעכשיו היין ממהר להחמיץ, \u0003שחזקתו\u0004 של חומץ \u0003אינו בא אלא מן היין.\u0004","ושואלים: \u0003וסבר ר' יהודה: תמד לאו בר עשורי\u0004 \u0005[לא בן עישור]\u0006 \u0003הוא? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המתמד ונתן מים במדה\u0004 מסויימת \u0003ומצא\u0004 משקה \u0003כדי מדתו\u0004 ולא יותר — \u0003פטור\u0004 מלעשר, משום שרואים שהענבים הוסיפו בהם רק טעם בלבד ולא כמות יין. \u0003ור' יהודה מחייב\u0004 אפילו בכך. וכיצד אם כן אמר קודם שאפשר לקחת תמד מעם הארץ? והרי תמד זה צריך לעשרו!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 התכוון\u0005]\u0006 ר' יהודה: לא שהתמד פטור ממעשר, אלא \u0003לא נחשדו עמי הארץ על התמד\u0004 שכיון שהוא זול ביותר, מן הסתם אין חוסכים בו ומעשרים אותו. \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 גם אם תאמר שאף על התמד \u0003נחשדו. ולא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 כשהוציא את התמד — \u0003בדרווקא\u0004 \u0005[בשמרי היין],\u0006 שיין כלשהו מעורב בו, ועל כך אמר ר' יהודה שחייב לעשר. \u0003הא\u0004 \u0005[זה] —\u0006 \u0003בדפורצני\u0004 \u0005[בחרצנים],\u0006 שהוציא את התמד מחרצני הגפנים בלבד שאין בהם כל תערובת יין ואינו צריך לעשר.","במשנה נאמר כי \u0003זיתום המצרי\u0004 יש בו משום חמץ, ושאלו: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003זיתום המצרי?\u0004","\u0003תנא\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 מתוך ברייתא: \u0003תלתא שערי, תלתא קורטמי, ותלתא מלחא\u0004 \u0005[שליש שעורים, שליש כרכום, ושליש מלח].\u0006","\u0003רב פפא מפיק שערי ומעייל חיטי\u0004 \u0005[היה מוציא שעורים ומכניס חיטים].\u0006 כלומר, לדעתו זיתום המצרי לא נעשה משעורים אלא מחיטים. ומעירים: \u0003וסימניך\u0004 הכלי הקרוי \u0003סיסני.\u0004 כלומר, אם רצונך לזכור מי מן החכמים אמר שיש שעורים בזיתום יהא סימנך המלה \u0003סיסני,\u0004 שמופיעה בה פעמיים האות ס', ותזכור כי רב יוסף שיש בשמו את האות ס' אמר שעורים (שהאות ש' הריהי כאות ס'), פעמיים ס'.","\u0003ותרו להו וקלו להו וטחני להו\u0004 \u0005[ושורים אותם\u0006 יחד \u0005ו\u0006אחר כך \u0005קולים אותם\u0006 באש \u0005וטוחנים אותם\u0006 יחד\u0005]\u0006 \u0003ושתו להו מדיבחא ועד עצרתא\u0004 \u0005[ושותים אותם מ\u0006זמן \u0005הפסח ועד העצרת],\u0006 \u0003דקמיט מרפי ליה, ודרפי מקמיט ליה\u0004 \u0005[\u0006שמי \u0005ש\u0006הוא \u0005עצור\u0006 הרי הוא \u0005מרפה\u0006 את מעיו, \u0005ו\u0006זה \u0005ש\u0006הוא \u0005מרופה\u0006 הרי הוא \u0005מחזק\u0006 את מעיו\u0005],\u0006 \u0003לחולה ולאשה עוברה\u0004 \u0005[מעוברת]\u0006 \u0003סכנתא\u0004 \u0005[סכנה]\u0006 הוא לשתות ממשקה זה.","במשנה הוזכר \u0003זומן של צבעים\u0004 שהוא חמץ. ומסבירים: \u0003הכא תרגימו\u0004 \u0005[כאן\u0006 בבבל, \u0005הסבירו]\u0006 שזהו \u0003מיא דחיורי דצבעי בהו לבא\u0004 \u0005[מים של סובין שצובעים בהם את העור].\u0006","עוד הוזכר במשנה \u0003ועמילן של טבחים\u0004 שאף הוא חמץ. ומסבירים מה טיבו: \u0003פת תבואה שלא הביאה שליש\u0004 בישולה, שקוטפים את המלילות בוסר ועושין מהם כעין ככר \u0003שמניחה על פי קדירה ושואבת\u0004 את \u0003הזוהמא\u0004 שבמרק.","עוד הוזכר במשנה \u0003קולן של סופרים\u0004 שהרי הוא חמץ. ומסבירים: \u0003הכא תרגומא\u0004 \u0005[כאן\u0006 בבבל, \u0005הסבירו]\u0006 שזהו \u0003פרורא דאושכפי\u0004 \u0005[דבק של סנדלרים]\u0006 העשוי מקמח.","\u0003רב שימי מחוזנאה אמר: זה טיפולן\u0004 (מריחתם) \u0003של בנות עשירים, שמשיירות אותו לבנות עניים.\u0004 כלומר, נוהגות היו הנשים כדי להשיר שיער ממקומות שונים בגוף למרוח באותם מקומות חומרים שונים, וביניהם מעורב גם קמח. ו\"קולן של סופרים\", הכוונה שאת שיירי המריחה (הטפילה) של בנות העשירים היו נותנות לבנות הסופרים (מלמדי התינוקות) שעניות היו, כדי שגם הן תוכלנה להשתמש בהם.","ותוהים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והא תנא\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא\u0004 לסימן, שהדברים במשנתנו יש ביניהם \u0003ארבעה מיני מדינה,\u0004 כלומר דברים שכל בני המדינה משתמשים בהם והם: כותח, שכר, חומץ, וזיתום. \u0003ו\u0004כן \u0003שלשה מיני אומנות,\u0004 דברים השייכים לבעלי מקצוע, והם: זומן, קולן, ועמילן. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שקולן של סופרים הוא \u0003טיפולן של בנות עשירים,\u0004 אם כן \u0003מאי\u0004 \u0005[איזה]\u0006 \u0003מיני אומנות איכא\u0004 \u0005[יש כאן]?\u0006 הלוא אין זה דבר השייך לבעלי מקצוע!","ומשיבים בשאלה: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 תאמר שכאן מדובר ב\u0003פרורא דאושכפי\u0004 \u0005[דבק של סנדלרים],\u0006 אם כן, \u0003אמאי קרי ליה האי\u0004 \u0005[מדוע קורא לזה]\u0006 \u0003קולן של סופרים? קולן של רצענים\u0004 (סנדלרים) \u0003מיבעיא ליה\u0004 \u0005[היה צריך]\u0006 לקרוא \u0005לו!\u0006 \u0003אמר רב אושעיא: לעולם\u0004 תפרש שקולן הוא \u0003פרורא דאושכפי\u0004 \u0005[דבק של סנדלרים],\u0006 \u0003ומאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 \u0003קולן של סופרים?\u0004 משום ש\u0003סופרים נמי\u0004 \u0005[גם כן]\u0006 \u0003מדבקין בהו ניירותיהן,\u0004 ובזמן המשנה קראו לכך דבק הסופרים.","במשנתנו נאמר כי \u0003ר' אליעזר אומר אף תכשיטי נשים\u0004 אסורים. ותוהים: \u0003תכשיטי נשים סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לאסור, תכשיטים העשויים כסף וזהב או אריגים, מה חמץ יש בהם? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 שהכוונה היא: \u0003אף טיפולי נשים\u0004 כלומר דברים שטופלות (מורחות) הנשים על עצמן לתיקון העור. ש\u0003אמר רב יהודה אמר רב בנות ישראל\u0004"],["\u0003שהגיעו לפרקן\u0004 שצומחות להן שערות כבוגרות, \u0003ו\u0004אולם \u0003לא הגיעו\u0004 עדיין \u0003לשנים\u0004 של בגרות, והן מתביישות בשל כך, ורוצות להשיר שערות אלה, מה הן עושות, \u0003בנות עניים טופלות\u0004 (מורחות) \u0003אותן בסיד\u0004 המשיר את השיער, \u0003בנות עשירים טופלות אותן בסולת, בנות מלכים בשמן המור,\u0004 והוא \u0003שנאמר:\u0004 \"כי כן ימלאו ימי מרוקיהן \u0003ששה חדשים בשמן המור\u0004 וששה חדשים בבשמים ובתמרוקי הנשים\" (אסתר ב, יב).","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"שמן המור\"? רב הונא בר ירמיה אומר: סטכת\u0004 (סוג של שמן המעורב בתמצית בושם). \u0003רב ירמיה בר אבא אמר:\u0004 זהו \u0003שמן זית שלא הביא שליש\u0004 שמתמצה מזיתים שעדיין לא נתבשלו והוא חריף ביותר.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' יהודה אומר: אנפיקנין\u0004 שאסרו חכמים להביאו למנחות זהו \u0003שמן זית שלא הביא שליש, ולמה סכין אותו? מפני שמשיר את השיער ומעדן את הבשר.\u0004","נאמר במשנה \u0003\"זה הכלל כל שהוא ממין דגן\u0004 אסור בפסח\". \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יהושע: וכי מאחר ששנינו כל שהוא מין דגן הרי זה עובר בפסח, למה מנו חכמים את אלו\u0004 בפרט? הרי היו יכולים להסתפק בכלל! אלא \u0003כדי שיהא רגיל בהן ובשמותיהן,\u0004 וידע שדברים אלה יש בהם משהו דגן.","מסופר: \u0003כי הא דההוא בר מערבא איקלע\u0004 \u0005[כגון זה שאחד בן המערב,\u0006 ארץ ישראל \u0005הזדמן]\u0006 \u0003לבבל, הוה בישרא בהדיה\u0004 \u0005[היה בשר עמו],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 למארחיו: \u0003קריבו\u0004 \u0005[הביאו]\u0006 \u0003לי מתכילתא\u0004 \u0005[תבלין]\u0006 לאכול עם הפת. \u0003שמע דקאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003קריבו ליה\u0004 \u0005[תנו לו]\u0006 \u0003כותח. כיון\u0004 ש\u0003שמע כותח — פירש,\u0004 שידע שבכותח יש חלב ואין לאוכלו עם הבשר. ומכאן שיש תועלת לאדם לדעת שמות המאכלים וממה הם עשויים, כדי שיוכל להיזהר מהם, גם כשאינו יודע כיצד הם נראים.","נאמר אף במשנה על הדברים השנויים שם \u0003\"הרי אלו באזהרה\"\u0004 באיסור לאו, אבל לא בכרת.","ושואלים: \u0003מאן תנא\u0004 \u0005[מי\u0006 הוא \u0005התנא]\u0006 הסבור ש\u0003חמץ דגן גמור,\u0004 אם הוא \u0003על ידי תערובות ו\u0004כן חמץ \u0003נוקשה\u0004 שהוא חמץ גרוע שאינו ראוי לאכילה, כשהוא \u0003בעיניה\u0004 \u0005[בעינו]\u0006 אסור \u0003בלאו?\u0004","\u0003אמר רב יהודה אמר רב:\u0004 שיטת \u0003ר' מאיר היא, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שיאור\u0004 כלומר, בצק שלא החמיץ לגמרי והוא רק בתחילת חימוץ והוא חמץ נוקשה — \u0003ישרף, ונותנו לכלבו, והאוכלו\u0004 — לוקה \u0003בארבעים.\u0004","לפני שדנים בברייתא זו לעניננו, מעירים תחילה על סתירה המצויה בה: \u0003הא גופא קשיא\u0004 \u0005[\u0006ברייתא \u0005זו עצמה קשה],\u0006 \u0003אמרת\u0004 מצד אחד \u0003\"שיאור ישרף\", אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003אסור בהנאה, והדר תני\u0004 \u0005[וחזר\u0006 ו\u0005שנה]:\u0006 \u0003ונותנו לפני כלבו, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מותר בהנאה!\u0004","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 לכך התכוון\u0005]:\u0006 \u0003שיאור ישרף,\u0004 כוונתו לאותו שיאור של שיטת \u0003ר' מאיר\u0004 בשיאור, שלדעת \u0003ר' מאיר\u0004 הוא חמץ גמור, או שיאור בדרך שקבע \u0003ר' יהודה\u0004 על פי שיטת \u0003ר' יהודה\u0004 שהוא חמץ גמור לדעתו, ולשיטת כל אחד מהם הוא אסור בהנאה. \u0003ונותנו לפני כלבו\u0004 הכוונה היא: אותו שיאור שלדעת \u0003ר' מאיר\u0004 חמץ גמור הוא, ולדעת \u0003ר' יהודה\u0004 אינו חמץ גמור אלא חמץ נוקשה בלבד הוא, שיכול לתיתו לפני כלבו, שאמנם אסור הוא באכילה אבל מותר בהנאה.","ומה שאמרו \u0003והאוכלו\u0004 לוקה \u0003בארבעים\u0004 הרי בכך \u0003אתאן\u0004 \u0005[באנו]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר,\u0004 שאותו חמץ שמותר בהנאה לשיטת ר' יהודה — האוכלו לוקה ארבעים,","ואם כן \u0003שמעינן ליה\u0004 \u0005[שמענו אותו]\u0006 את \u0003ר' מאיר\u0004 שסבור שחמץ \u0003נוקשה\u0004 שהוא \u0003בעיניה\u0004 \u0005[בעינו]\u0006 ללא תערובת, הוא \u0003בלאו\u0004 ועונשו מלקות. \u0003וכל שכן חמץ דגן גמור על ידי תערובת,\u0004 שאין חייב עליו כרת משום שאינו אוכלו לעצמו, אבל חייב עליו באיסור לא תעשה שבאכילת חמץ.","\u0003רב נחמן אמר:\u0004 שיטה זו שבמשנתנו שיטת \u0003ר' אליעזר היא, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003על חמץ דגן גמור — ענוש כרת, על עירובו — ענוש בלאו,\u0004 אלו \u0003דברי ר' אליעזר. וחכמים אומרים: על חמץ דגן גמור — ענוש כרת, על עירובו — בלא כלום\u0004 שאין חייבים על התערובת כלל. \u0003ושמעינן ליה\u0004 \u0005[ושמענו אותו]\u0006 את \u0003ר' אליעזר\u0004 ש\u0003אמר חמץ דגן גמור על ידי תערובת בלאו, וכל שכן\u0004 חמץ \u0003נוקשה בעיניה\u0004 \u0005[בעינו].\u0006","ושואלים: \u0003ורב נחמן, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כ\u0004שיטת \u0003רב יהודה\u0004 שמשנה זו היא כדעת ר' מאיר?","\u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 כי יש להבחין: \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' מאיר התם\u0004 \u0005[שם]\u0006 \u0003אלא נוקשה בעיניה\u0004 \u0005[בעינו],\u0006 \u0003אבל חמץ דגן גמור\u0004 גם \u0003על ידי תערובת לא,\u0004 ושמא לדעתו חייב עליו כרת.","ולהיפך, \u0003רב יהודה מאי טעמא\u0004 \u0005[מה הטעם]\u0006 \u0003לא אמר כרב נחמן\u0004 שמשנה זו כשיטת ר' אליעזר?","\u0003אמר לך: עד כאן לא\u0004 שמענו \u0003קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' אליעזר התם\u0004 \u0005[שם]\u0006 \u0003אלא חמץ דגן גמור,\u0004 שאם הוא \u0003על ידי תערובת\u0004 חייבים עליו בלאו. אבל \u0003נוקשה בעיניה\u0004 \u0005[בעינו],\u0006 שאין כאן חמץ גמור \u0003לא אמר,\u0004 ויהא פטור לגמרי.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב יהודה\u0004 שהלכה זו כשיטת ר' מאיר היא. שעל הכתוב \u0003\"כל מחמצת לא תאכלו\u0004 בכל מושבותיכם תאכלו מצות\u0003\"\u0004 (שמות יב, כ) דרשו חכמים: \u0003לרבות כותח הבבלי, ושכר המדי, וחומץ האדומי, וזיתום המצרי. יכול יהא\u0004 האוכל מאלה \u0003ענוש כרת? תלמוד לומר: \"כי כל אכל חמץ ונכרתה\u0004 הנפש ההיא מישראל\u0003\"\u0004 (שמות יב, טו), ללמדנו: \u0003על חמץ דגן גמור — ענוש כרת, ועל עירובו\u0004 — ענוש \u0003בלאו\u0004 בלבד.","ונדייק: \u0003מאן\u0004 \u0005[\u0006את \u0005מי]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר על עירובו\u0004 של חמץ שחייב \u0003בלאו? ר' אליעזר היא, ואילו נוקשה בעיניה\u0004 \u0005[בעינו]\u0006 \u0003לא קאמר\u0004 \u0005[אמר],\u0006 שהרי מנה כאן רק את מיני המאכל והמשקה שיש בהם תערובת חמץ גמור, אבל לא מנה את החומרים האחרים (זומן, עמילן וקולן) שהם חמץ נוקשה בלבד, \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 חמץ \u0003נוקשה לר' אליעזר לית ליה\u0004 \u0005[אין לו\u0006 בו איסור\u0005].\u0006","ושואלים: \u0003ור' אליעזר,\u0004 דין זה שעל \u0003עירובו\u0004 של חמץ \u0003בלאו, מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"כל מחמצת לא תאכלו\"\u0004 (שמות יב, כ).","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהוא סבור כי \"מחמצת\" פירושה תערובת חמץ, אם כן \u0003כרת נמי לחייב\u0004 \u0005[גם כן שיתחייב],\u0006 \u0003דהא כתיב\u0004 \u0005[שהרי נאמר]\u0006 \"שבעת ימים שאור לא ימצא בבתיכם \u0003כי כל אכל מחמצת ונכרתה\u0004 הנפש ההיא מעדת ישראל בגר ובאזרח הארץ\" (שמות יב, יט), ומפורש שיש באכילת מחמצת עונש כרת!","ומשיבים: \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[אותה\u0006 \"מחמצת\" \u0005נצרכה לו\u0006 ללימוד אחר, \u0005לכפי ששנויה\u0006 ברייתא\u0005],\u0006 \u0003\"מחמצת\" — אין לי אלא שנתחמץ\u0004 הדבר \u0003מאליו\u0004 שהוא הקרוי מחמצת, אם נתחמץ \u0003מחמת דבר אחר, מנין\u0004 שהוא כחמץ שחייב עליו כרת? — \u0003תלמוד לומר \"כל... מחמצת ונכרתה\",\u0004 שאפילו דבר שלא נתחמץ מעצמו, בכלל חמץ הוא.","ותוהים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 ש\"כל מחמצת\" פירושה לרבות דבר שנתחמץ מחמת דבר אחר, אם כן \"כל מחמצת\" שבאיסור ה\u0003לאו נמי להכי\u0004 \u0005[גם כן לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא ללמד]\u0006 ולא לענין תערובת!","\u0003אלא\u0004 אומרים: \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' אליעזר מ\"כל\",\u0004 שלא למד מן המלה \"מחמצת\" אלא מלשון הריבוי \"כל מחמצת\" הכתוב שם.","ומקשים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 בפסוק שיש בו כרת, \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \"כי \u0003כל\u0004 אוכל חמץ ונכרתה\"? ומשיבים: \u0003ההוא\u0004 \u0005[אותו]\u0006 \"כל\" \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללימוד אחר — \u0003לרבות את הנשים,\u0004 שאף הן אסורות באכילת חמץ.","ותוהים: וכי יש צורך ללימוד זה להלכה זו? הלוא ריבוי זה \u0003מ\u0004דברי \u0003רב יהודה אמר רב נפקא\u0004 \u0005[\u0006הוא \u0005יוצא],\u0006 שכן \u0003אמר רב יהודה אמר רב, וכן תנא דבי\u0004 \u0005[שנה\u0006 חכם \u0005בית\u0006 מדרשו של\u0005]\u0006 \u0003ר' ישמעאל: אמר קרא\u0004 \u0005[הכתוב]\u0006 \"דבר אל בני ישראל \u0003איש או אשה כי יעשו מכל חטאת האדם\u0004 למעול מעל בה' ואשמה הנפש ההיא\" (במדבר ה, ו), \u0003השוה הכתוב איש לאשה לכל עונשין שבתורה,\u0004 הרי שלגבי כרת שהוא בין שאר עונשים שבתורה אין צורך בריבוי מיוחד לאשה.","ומשיבים: אף על פי כן, בכל זאת בענין חמץ \u0003איצטריך\u0004 \u0005[נצרך\u0006 הדבר\u0005]\u0006"],["\u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"לא תאכל עליו חמץ שבעת ימים תאכל עליו מצות\u0004 לחם עוני\u0003\"\u0004 (דברים טז, ג), נלמד מכאן: \u0003כל שישנו ב\u0004מצוה זו של \u0003קום אכול מצה — ישנו\u0004 גם \u0003ב\u0004איסור זה של \u0003\"בל תאכל חמץ\", והני נשי\u0004 \u0005[ונשים אלה]\u0006 \u0003הואיל וליתנהו\u0004 \u0005[ואינן]\u0006 \u0003ב\u0004מצות \u0003קום אכול מצה, דהויא ליה\u0004 \u0005[שהרי היא]\u0006 \u0003מצות עשה שהזמן גרמא היא,\u0004 וכרגיל פטורות נשים ממצוות אלה, \u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003בבל תאכל חמץ נמי ליתנהו\u0004 \u0005[גם כן אינן],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב וחידש שאף נשים חייבות שלא לאכול חמץ.","ומעירים: \u0003והשתא דאתרבו להו\u0004 \u0005[ועכשיו שהתרבו\u0006 שנלמד ריבוי \u0005להן\u0006 לנשים] שחייבות \u0003בבל תאכל חמץ — איתרבי נמי\u0004 \u0005[התרבו גם כן]\u0006 \u0003ל\u0004ענין חיוב \u0003אכילת מצה,\u0004 אף שהוא מצות עשה שהזמן גרמא, \u0003כ\u0004שיטת \u0003ר' אליעזר,\u0004 ש\u0003אמר ר' אליעזר: נשים חייבות\u0004 במצות עשה של \u0003אכילת מצה\u0004 מ\u0003דבר תורה, שנאמר \"לא תאכל עליו חמץ\u0004 שבעת ימים תאכל עליו מצות \u0003\",\u0004 שהשווה הכתוב את שני הדברים הללו ללמדנו: \u0003כל שישנו ב\u0004איסור של \u0003בל תאכל חמץ, ישנו ב\u0004חובת \u0003אכילת מצה. והני נשי נמי\u0004 \u0005[ואותן נשים גם כן]\u0006 \u0003הואיל וישנן בבל תאכל חמץ ישנן\u0004 אף \u0003בקום אכול מצה.\u0004","על לימוד זה שואלים: \u0003ומאי חזית\u0004 \u0005[ומה ראית]\u0006 \u0003דהאי\u0004 \u0005[שזה]\u0006 \u0003\"כל\"\u0004 שנאמר \u0003לרבויי\u0004 \u0005[לרבות]\u0006 \u0003נשים\u0004 הוא שבא, \u0003ומפקת\u0004 \u0005[ואתה מוציא]\u0006 את ענין \u0003ערובו\u0004 של החמץ? \u0003אימא\u0004 \u0005[אמור]\u0006 להיפך: \u0003לרבויי\u0004 \u0005[לרבות]\u0006 \u0003עירובו\u0004 שגם על תערובת החמץ חייבים בכרת!","ומשיבים על כך: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 הדבר באופן זה, כאשר \u0003קאי\u0004 \u0005[עומד,\u0006 עוסק\u0005]\u0006 הפסוק \u0003ב\u0004אנשים ה\u0003אוכלין\u0004 הוא \u0003מרבה אוכלין,\u0004 שנאמר \"כי כל אוכל חמץ ונכרתה הנפש ההיא\", ולכן מסתבר לרבות על ידי ההדגשה \"כי כל\" לא מיני חמץ אחרים אלא סוגים נוספים של אנשים שחייבים כרת על אכילת החמץ. אבל כאשר \u0003קאי\u0004 \u0005[עומד,\u0006 עוסק\u0005]\u0006 הפסוק המדבר מענין אזהרת לאו \u0003באוכלין\u0004 (מיני מאכל) \u0003מרבה\u0004 על ידי המלה \"כל\" את ה\u0003נאכלים,\u0004 כלומר סוגי חמץ חדשים? אין הדבר מסתבר.","ומעירים על כך: \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב נתן אבוה\u0004 \u0005[אביו]\u0006 של \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן:\u0004 והאמנם כן הוא? \u0003ו\u0004כי \u0003בכל היכא דקאי\u0004 \u0005[מקום שעומד,\u0006 עוסק\u0005]\u0006 הפסוק באנשים ה\u0003אוכלין לא מרבה נאכלין? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שיטת לימוד שונה, שעל הפסוק \u0003\"כי כל אכל חלב מן הבהמה אשר יקריב\u0004 ממנה אשה לה' ונכרתה הנפש האוכלת מעמיה\u0003\"\u0004 (ויקרא ז, כה) דרשו: \u0003אין לי אלא\u0004 ללמוד מכאן שהאיסור הוא על \u0003חלב\u0004 בעלי חיים \u0003תמימין שראוי ליקרב\u0004 להקריבם למזבח, \u0003חלב בעלי מומין\u0004 שאינם ראויים למזבח והוקדשו, \u0003מנין\u0004 הדבר שאסור? \u0003תלמוד לומר: \"מן הבהמה\". חלב חולין\u0004 שלא הוקדשו כלל למזבח \u0003מנין\u0004 שאסור לאוכלו? \u0003תלמוד לומר: \"כי כל\u0004 אוכל חלב \u0003\". והא הכא\u0004 \u0005[והרי כאן]\u0006 בפסוק זה \u0003דקאי\u0004 \u0005[שעומד,\u0006 עוסק\u0005]\u0006 \u0003באוכלין\u0004 באוכלי החלב, \u0003ו\u0004בכל זאת \u0003קא מרבה נאכלין,\u0004 שאינו לומד מ\"כי כל אוכל חלב\" סוגי אנשים נוספים האסורים באכילה אלא מינים אחרים של חלב!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003דליכא\u0004 \u0005[שאין]\u0006 מקום לרבות ב\u0003אוכלין\u0004 אחרים, שהכל אסורים באיסור זה, \u0003מרבה\u0004 הכתוב בלשון ייתור זו \u0003נאכלין\u0004 אחרים, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 בענין חמץ \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003אוכלין\u0004 נוספים שאפשר לרבותם כגון נשים, \u0003לא שביק להו\u0004 \u0005[יעזוב אותם]\u0006 את ה\u0003אוכלין ומרבה נאכלין,\u0004 שמסתבר שהפסוק בא לרבות כענין הכתוב בו, ורק במקום שאי אפשר ללמדו לענינו למדים ממנו אפילו דבר שונה במקצת.","ומסבירים: \u0003ורבנן דלית להו\u0004 \u0005[וחכמים שאין להם\u0006 שאינם מקבלים\u0005]\u0006 את האיסור ב\u0003עירוב\u0004 (תערובת חמץ) והם \"\u0003כל\u0004\" \u0003לא דרשי\u0004 \u0005[דורשים]\u0006 ואינם סבורים ש\"כל\" זה בא לרבות את התערובת, אם כן אף \"כל\" שנאמר בכרת אינם דורשים. ושואלים: \u0003אלא\u0004 אם כן \u0003נשים מנא להו\u0004 \u0005[מנין להם]\u0006 שהן אסורות לאכול חמץ?","ומשיבים: אמנם \u0003\"כל\"\u0004 — \u0003לא דרשי\u0004 \u0005[דורשים],\u0006 ואולם \u0003\"כי כל\"\u0004 — \u0003דרשי\u0004 \u0005[דורשים\u0006 הם\u0005],\u0006 שנראה להם שלשון \"כי כל\" האמורה בענין \"כי כל אוכל מחמצת\" שונה היא ובאה כדי לרבות.","ושואלים: אם כן, שלשון \"כי כל\" היא לשון ריבוי יותר מאשר \"כל\" בלבד, אף ל\u0003ר' אליעזר\u0004 נלמד מכאן ריבוי כפול, ו\u0003אימא\u0004 \u0005[נאמר]\u0006 לשיטתו: \u0003\"כל\u0004 אוכל מחמצת \u0003\"\u0004משמעו: \u0003לרבות את הנשים, \"כי כל\u0004 אוכל \u0003\"\u0004— \u0003לרבות את עירובו\u0004 של החמץ, ויהיו חייבים כרת אף על תערובת חמץ!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003\"כי כל\" ר' אליעזר לא דריש\u0004 \u0005[דורש],\u0006 שאינו מוצא בכך לשון ריבוי יתירה, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 באותו ענין על הכתוב \"כי כל שאור וכל דבש לא תקטירו ממנו אשה לה'\", ולמדים: אילו היה כתוב \u0003\"שאר בל תקטירו\" — אין לי\u0004 איסור \u0003אלא\u0004 כשמקטיר את השאור \u0003כולו, מקצתו מנין? תלמוד לומר: \"כל\u0004 שאור\u0003\"\u0004— שחייבים אף בחלק ממנו. \u0003עירובו מנין\u0004 שחייבים על הקטרתו? \u0003תלמוד לומר: \"כי כל\u0004 שאור\u0003\".\u0004 ונדייק: \u0003מאן\u0004 \u0005[מי]\u0006 הוא החכם ש\u0003שמעת ליה דדריש\u0004 \u0005[אותו ש\u0006הוא \u0005דורש]\u0006 לשון ריבוי מהמלה \u0003\"כל \"? ר' אליעזר\u0004 הוא, \u0003וקא דריש\u0004 \u0005[ו\u0006הרי \u0005הוא דורש]\u0006 \u0003\"כי כל\"\u0004 לריבוי נוסף!","ומסכמים: אמנם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר וצריך עיון, ולא מצאנו תירוץ מספיק מדוע אין ר' אליעזר דורש כן אף לענין תערובת חמץ.","כיון שעסקנו בדין תערובת איסור, מביאים הלכה כללית יותר. \u0003אמר ר' אבהו אמר ר' יוחנן: כל איסורין שבתורה אין היתר מצטרף לאיסור,\u0004 שאם אוכל אדם מן ההיתר, והאיסור יחד כדי השיעור שמתחייבים בו באיסור זה — פטור עליו. \u0003חוץ מאיסורי נזיר,\u0004 שחייבים גם על תערובתם, \u0003שהרי אמרה תורה\u0004 בנזיר \"מיין ושכר יזיר חומץ יין וחומץ שכר לא ישתה וכל \u0003משרת\u0004 ענבים לא ישתה\" (במדבר ו, ג), משמע שחייב לא רק על יין ושכר עצמם, אלא גם על דברים השרויים ביין ובשכר.","\u0003וזעירי אמר: אף שאור בל תקטירו,\u0004 שנאמר בתורה \"כל שאור וכל דבש לא תקטירו ממנו אשה לה'\" (ויקרא ב, יא), חייבים עליו לא רק אם הקטיר שאור בלבד אלא גם על תערובת שאור.","ושואלים: \u0003כמאן\u0004 \u0005[כמי]\u0006 אמר זעירי את הדברים הללו? ומשיבים: \u0003כ\u0004שיטת \u0003ר' אליעזר, דדריש\u0004 \u0005[ש\u0006הוא \u0005דורש]\u0006 את המלה \u0003\"כל\"\u0004 לאסור תערובת איסור בכל שהוא.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006"],["\u0003לענין חמץ בפסח נמי\u0004 \u0005[גם כן]\u0006 צריך שיחייב כאשר היתר מצטרף לאיסור.","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך הוא גם כן]\u0006 הדין. ומה שהזכיר שאור בהקטרה היה כדי \u0003לאפוקי מדאביי\u0004 \u0005[להוציא מ\u0006שיטת \u0005אביי]\u0006 ש\u0003אמר: יש הקטרה לפחות מכזית\u0004 כלומר, שלוקים על הקטרת שאור אף אם מקטיר שיעור פחות מזית, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כאשר דיבר על כך שהיתר מצטרף לאיסור שאיסור \u0003הקטרה לאו לפחות\u0004 \u0005[אינו בפחות]\u0006 \u0003מכזית, ש\u0004בכל זאת יש צורך בכמות מינימום מסויימת כדי להתחייב עליה.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב דימי וקאמר לה להא שמעתא\u0004 \u0005[ואמר את ההלכה הזו]\u0006 של ר' יוחנן שבכל איסורי התורה אין היתר מצטרף לאיסור פרט לאיסורי נזיר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב דימי: וכל איסורין שבתורה\u0004 חוץ מאיסורי נזיר אכן \u0003אין היתר מצטרף לאיסור?\u0004","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003המקפה\u0004 (מרק סמיך) \u0003של תרומה\u0004 והיו \u0003השום והשמן\u0004 שבו \u0003של חולין ונגע טבול יום במקצתן — פסל את כולן\u0004 משום מקפת התרומה. ולהיפך אם היתה ה\u0003מקפה של חולין והשום והשמן של תרומה ונגע טבול יום במקצתן — לא פסל אלא מקום מגעו בלבד,\u0004","\u0003והוינן בה\u0004 \u0005[והיינו עסוקים\u0006 בבעיה \u0005זו]\u0006 \u0003מקום מגעו אמאי\u0004 \u0005[מדוע]\u0006 \u0003פסולה, הא בטלי להו\u0004 \u0005[הרי בטלו להם]\u0006 ה\u0003תבלין ברוב!\u0004 וכיון שהרוב חולין הוא אין חולין אלה נפסלים עוד ממגעו של טבול יום. ועל כך \u0003אמר רבה בר בר חנה: מה טעם\u0004 אמרו שנפסלו — \u0003הואיל וזר לוקה עליהן בכזית\u0004 על המקפה המעורבת אם אכלה, שכל דבר שמעורבת בו תרומה — שם תרומה עליו מן התורה. \u0003והיכי דמי\u0004 \u0005[וכיצד בדיוק\u0006 הענין\u0005]\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003היתר מצטרף לאיסור?\u0004","ודחה רב דימי: \u0003לא, מאי\u0004 \u0005[מהו]\u0006 \u0003כזית\u0004 שאמרנו \u0003דאיכא\u0004 \u0005[שיש]\u0006 שיעור \u0003כזית\u0004 תרומה בתוך כמות שאפשר לאכול \u0003בכדי אכילת פרס,\u0004 והוא חייב על אכילת כזית התרומה אף שלא אכלו בבת אחת.","ושאל אותו אביי: \u0003וכזית בכדי אכילת פרס דאורייתא היא\u0004 \u0005[מן התורה הוא]\u0006 שמתחייבים עליו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006","ושאל אביי: \u0003אי הכי, אמאי פליגי רבנן עליה\u0004 \u0005[אם כן מדוע חולקים חכמים עליו]\u0006 על \u0003ר' אליעזר בכותח הבבלי\u0004 (תבלין חריף שמעורב בו קמח) בפסח, שהם אמרו שאין בתערובת חמץ עונש מן התורה. ואף שאין לחייבו מהריבוי של \"כל\" לרבות אף את התערובת, יחייבוהו משום שבתוך כדי אכילת פרס בא הוא לאכול כזית איסור?","אמר רב דימי: \u0003אלא מאי\u0004 \u0005[מה\u0006 תאמר\u0005]\u0006 שהטעם הוא באוכל תרומה \u0003משום\u0004 ש\u0003היתר מצטרף לאיסור, סוף סוף\u0004 מאותו טעם עצמו \u0003אמאי פליגי רבנן עליה\u0004 \u0005[מדוע חלקו חכמים\u0006 עצמם \u0005על]\u0006 \u0003ר' אליעזר בכותח הבבלי? אלא: הנח לכותח הבבלי דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003כזית בכדי אכילת פרס\u0004 שלא יכול להיות שיאכלו כזית חמץ שבו בזמן כה קצר, שהרי אינו אלא תבלין ורק חלקו הוא חמץ. \u0003אי בעיניה דקשריף וקאכיל ליה\u0004 \u0005[אם\u0006 כשאוכל \u0005בעינו שהוא גומע ואוכל אותו]\u0006 לא כתבלין אלא כאוכל, אם כן \u0003בטלה דעתיה אצל כל אדם,\u0004 שאין מנהג אדם לאכול תבלין חריף בפני עצמו ובמהירות כה מרובה, ואין מחייבים אדם על דבר שיוצא ממנהג הבריות. \u0003ואי משטר קשטר ואכיל\u0004 \u0005[ואם מטבל ואוכל]\u0006 \u0003לית ביה\u0004 \u0005[אין בו]\u0006 \u0003כזית בכדי אכילת פרס\u0004 שמחמת חריפותו מתבלים בו רק במעט.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי ממקור אחר, שנינו: היו \u0003שתי קדירות, אחת של חולין ואחת של תרומה, ולפניהן שתי מדוכות\u0004 שדכו בהן מאכל או תבלין, \u0003אחת\u0004 המדוכות היתה \u0003של חולין ואחת של תרומה, ונפלו אלו\u0004 (הדברים שבמדוכות) \u0003לתוך אלו\u0004 (הקדרות) ואין אנו יודעים מה נפל לתוך מה, פוסקים כי הכל \u0003מותרין\u0004 וחולין לעצמן ותרומה לעצמה ונאכלים החולין לזר. \u0003שאני אומר\u0004 כיון שאין לי הוכחה שאירע אחרת: ודאי \u0003תרומה לתוך התרומה נפלה וחולין לתוך חולין נפלו,\u0004","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 אכילת \u0003כזית\u0004 איסור אף בתערובת \u0003בכדי אכילת פרס דאורייתא\u0004 \u0005[מן התורה הוא]\u0006 \u0003אמאי אמרינן\u0004 \u0005[מדוע אומרים אנו]\u0006 \u0003שאני אומר תרומה לתוך תרומה\u0004 נפלה, שהרי אם נפל מן התבלין של תרומה לתוך החולין ואם יאכלם נמצא שאוכל כזית תרומת תבלין תוך כדי אכילת פרס מן הקדירה, הרי עובר על דברי תורה, ואם בכל זאת התירו הרי זו לכאורה ראיה שכזית באכילת פרס אינו אסור מן התורה. אלא חכמים הם שאסרוהו, ובמקרה כזה לא גזרו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב דימי: \u0003הנח לתרומת תבלין דרבנן\u0004 \u0005[שמדברי סופרים]\u0006 היא, שמן התורה אין חובת הפרשת תרומה אלא על מיני דגן, יין ושמן. ורק מדברי סופרים חייבו לתרום מן התבלין, לכן מקילים במקרה כזה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי עוד ממקור דומה: \u0003היו שתי קופות\u0004 (סלים גדולים) מלאים דגן, \u0003אחת של חולין ואחת של תרומה, ולפניהם שתי סאין\u0004 (מידות בנות סאה) \u0003אחת של חולין ואחת של תרומה\u0004 שאף בהן דגן, \u0003ונפלו אלו לתוך אלו — מותרין, שאני אומר: חולין לתוך חולין נפלו תרומה לתוך תרומה נפלה,\u0004 ואם כך יש להקשות: הרי פה מדובר בדגן שתרומתו מן התורה \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003כזית בכדי אכילת פרס דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003אמאי אמרינן\u0004 \u0005[מדוע אומרים אנו]\u0006 \u0003\"שאני אומר\",\u0004 הרי היינו צריכים לחשוש שמא יש כזית תרומה בכדי אכילת פרס ואסור?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הנח לתרומה בזמן הזה\u0004 שהיא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 כיון שלאחר שגלו ישראל מארצם ולא חזרו כולם אין דיני תרומות ומעשרות נוהגים מן התורה אלא רק מדברי סופרים, ולכן מקילים בספיקם ובתערובתם.","לעיקר דברי ר' אבהו שדן במלה \"משרת\" האמורה בנזיר שלמדים לצירוף היתר לאיסור, שואלים: \u0003והאי \"משרת\" להכי הוא דאתא\u0004 \u0005[וכי \"משרת\" זה לכך הוא שבא\u0006 ללמדנו\u0005]?\u0006 הרי \u0003האי מיבעי ליה\u0004 \u0005[זה נצרך לו]\u0006 \u0003לכדתניא\u0004 \u0005[למה ששנינו\u0006 בברייתא\u0005]\u0006 במקום אחר: \u0003\"משרת\"\u0004"],["\u0003ליתן טעם כעיקר\u0004 כלומר, שחייב על דבר שנבלע בו טעם של איסור כאילו היה הוא עצמו אסור. \u0003שאם שרה ענבים במים ויש בהן\u0004 במים \u0003טעם יין — חייב\u0004 הנזיר על שתייתם, שנעשים המים כיין.","\u0003מכאן אתה דן לכל התורה כולה,\u0004 שטעם איסור כאיסור עצמו, כיצד: \u0003ומה נזיר שאין איסורו איסור עולם\u0004 שכשסיים תקופת נזרו מותר שוב ביין, \u0003ואין איסורו\u0004 בענבים וביין \u0003איסור הנאה\u0004 אלא איסור אכילה ושתיה בלבד, \u0003ויש היתר לאיסורו\u0004 שאם ירצה יוכל לבוא לחכם, ולהישאל על נדר נזירותו ולהתירו, ובכל זאת \u0003עשה בו\u0004 הכתוב \u0003טעם כעיקר, כלאים\u0004 בכרם \u0003שאיסורו איסור עולם, ואיסורו איסור הנאה, ואין היתר לאיסורו — אינו דין שיעשה טעם כעיקר?\u0004","\u0003והוא הדין\u0004 יש ללמוד קל וחומר דומה \u0003לערלה בשתים\u0004 כלומר בשתי דרכים, שאיסורו איסור הנאה, ואין היתר לאיסורו (בתוך שלוש שני ערלה) אף על פי שאינו איסור עולם שלאחר שנות הערלה מותר ליהנות מפירות העץ, ואפשר ללמוד איפוא גם כאן טעם כעיקר מקל וחומר. וכן אפשר לומר ברוב איסורי התורה שהם חמורים בפרט זה או אחר מאיסור נזיר. ועל כל פנים קשה לר' יוחנן שדרש \"משרת\" להלכה אחרת!","ומשיבים: \u0003הא מני\u0004 \u0005[\u0006דרשה \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא\u0004 הלומדים \"משרת\" לצורך הלכה זו, ואילו \u0003ר' יוחנן דאמר\u0004 \u0005[שאמר]\u0006 שהיתר מצטרף לאיסור, סבר \u0003כר' עקיבא.\u0004","ושואלים: \u0003הי\u0004 \u0005[איזה]\u0006 \u0003ר' עקיבא\u0004 כלומר, לאיזה מדברי ר' עקיבא מתכוון ר' יוחנן? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שהכוונה לשיטת \u0003ר' עקיבא דמתניתין\u0004 \u0005[שבמשנתנו]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בה\u0005]:\u0006 \u0003ר' עקיבא אומר: נזיר ששרה פתו ביין, ויש בו לצרף כדי כזית — חייב,\u0004 אולם \u0003ממאי\u0004 \u0005[מנין]\u0006 שהכוונה שיש לצרף \u0003מפת ומיין\u0004 ושכזית שחציו פת וחציו יין חייב עליו. \u0003דילמא\u0004 \u0005[שמא]\u0006 הכוונה ש\u0003מיין לחודיה\u0004 \u0005[לחוד]\u0006 אפשר לצרף כזית,","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 אם \u0003מיין לחודיה מאי למימרא\u0004 \u0005[לחוד מהו לומר]\u0006 מה החידוש שבדבר? אולם יש בכך חידוש \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 שהאיסור ב\u0003תערובת\u0004 ואינו בעין, חייבים עליו. ואין איפוא להוכיח מכאן שיטת ר' עקיבא בצירוף היתר ואיסור.","אלא יש לומר שהכוונה לדברי \u0003ר' עקיבא דברייתא. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' עקיבא אומר: נזיר ששרה פתו ביין ואכל כזית מפת ומיין\u0004 כאחד — \u0003חייב,\u0004 ומכאן נתבררה שיטת ר' עקיבא בצירוף היתר ואיסור.","ושואלים לגוף השיטה: \u0003ור' עקיבא\u0004 עצמו \u0003טעם כעיקר מנא ליה\u0004 \u0005[מנין לו]\u0006 שהוא אסור? ומשיבים: \u0003יליף\u0004 \u0005[למד\u0006 דבר זה\u0005]\u0006 מאיסור \u0003בשר\u0004 שנתבשל \u0003בחלב,\u0004 שהרי \u0003לאו טעמא בעלמא\u0004 \u0005[האם לא טעם בלבד]\u0006 \u0003הוא\u0004 שנותן החלב בבשר \u0003ואסור, הכא נמי לא שנא\u0004 \u0005[כאן גם כן\u0006 בשאר איסורים \u0005אינו שונה].\u0006","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים על כך? ומשיבים שלדעתם מאיסור \u0003בשר בחלב לא גמרינן\u0004 \u0005[אין אנו לומדים]\u0006 לאיסורים אחרים משום שאיסור בשר בחלב \u0003חידוש הוא.\u0004","ושואלים: \u0003ומאי\u0004 \u0005[ומהו]\u0006 צד ה\u0003חידוש\u0004 שבו? \u0003אילימא דהאי לחודיה והאי לחודיה שרי ובהדי הדדי אסור\u0004 \u0005[אם תאמר שזה לעצמו\u0006 הבשר \u0005וזה לעצמו\u0006 החלב \u0005מותר וזה עם זה אסור],\u0006 אולם זה אינו חידוש שכן \u0003כלאים נמי האי לחודיה והאי לחודיה שרי ובהדדי אסור\u0004 \u0005[גם כן זה לחוד וזה לחוד מותר וביחד אסור],\u0006","\u0003אלא\u0004 כך יש לומר: \u0003דאי תרו ליה כולי יומא בחלבא — שרי\u0004 \u0005[אם ישרו\u0006 את הבשר \u0005כל היום בחלב —\u0006 \u0005מותר]\u0006 מן התורה, אף שמן הסתם נבלע משהו מטעם החלב בבשר, ואם \u0003בשיל ליה בשולי\u0004 \u0005[יבשלנו] —\u0006 \u0003אסור\u0004 מן התורה.","ושואלים: \u0003ור' עקיבא נמי\u0004 \u0005[גם כן]\u0006 הלוא \u0003בשר בחלב ודאי חידוש הוא,\u0004 וכיצד לומד הוא מדבר חידוש?","\u0003אלא יליף\u0004 \u0005[למד\u0006 הלכה זו\u0005]\u0006 מענין \u0003גיעולי גוים,\u0004 שלמדנו בתורה בפרשת שלל מדין שכלי שבישל בו הגוי אוכל יש להביאו באש כדי לטהרו לישראל. \u0003גיעולי גוים לאו טעמא בעלמא\u0004 \u0005[האם אינו טעם בלבד]\u0006 \u0003הוא\u0004 ובכל זאת \u0003אסור\u0004 כלומר, שכלים אלו אין איסורם אלא בטעם האיסור שנבלע בהן אגב בישול, \u0003הכא נמי לא שנא\u0004 \u0005[כאן גם כן אינו שונה].\u0006","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם למדים משם, לדעתם \u0003גיעולי גוים נמי\u0004 \u0005[גם כן]\u0006 הן עצמן \u0003חידוש הוא.\u0004 ומה החידוש בדבר — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003כל נותן טעם לפגם מותר\u0004 כלומר, אם האיסור איננו נותן טעם שיש בו כדי להשביח את ההיתר וטעם זה רק פוגם בו אינו אוסר, \u0003דגמרינן\u0004 \u0005[שלמדנו]\u0006 דבר זה \u0003מנבילה,\u0004 שנבילה שאיננה ראויה לאכילה שוב אינה קרויה נבילה ואינה אסורה. \u0003והכא\u0004 \u0005[וכאן]\u0006 בדין גיעולי גוים אמרה תורה שאפילו נותן טעם לפגם \u0003אסור.\u0004 ומוחזק בידינו שדבר שנבלע בכלי ושהה בו למעלה מעשרים וארבע שעות מזמן בישולו — טעם שהוא נותן הוא תמיד טעם לפגם. ואילו אותם כלי הגוים אסורים היו כולם אפילו לאחר זמן רב, אף שהם נותנים טעם לפגם במאכל.","\u0003ור' עקיבא\u0004 הלמד בכל זאת מגיעולי גוים סבור כדברי \u0003רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא\u0004 ש\u0003אמר: לא אסרה תורה\u0004 בגיעולי גוים \u0003אלא בקדירה בת יומא\u0004 שבישלו בה בו ביום, \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003לאו\u0004 \u0005[אינו]\u0006 \u0003נותן טעם לפגם הוא.\u0004","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים? לדעתם: \u0003קדירה בת יומא נמי לא אפשר דלא פגמה פורתא\u0004 \u0005[קדירה בת יומה גם כן אי אפשר שלא פגמה\u0006 טעמה \u0005במקצת]\u0006 אם שהתה בלא תבשיל, וכיון שכן לא היה ראוי לחשוש לאיסור זה, ונמצא שהלכה בגיעולי גוים היא חידוש, ואין למדים ממנה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי: מדרבנן\u0004 \u0005[מ\u0006דברי \u0005חכמים]\u0006 בענין זה \u0003נשמע\u0004 ונוכל לפרש את שיטת \u0003ר' עקיבא, מי לא אמרי רבנן\u0004 \u0005[האם לא אמרו חכמים]\u0006 כי \u0003\"משרת\"\u0004 בא ללמד \u0003ליתן טעם כעיקר\u0004 לענין איסור יין לנזיר, \u0003ומכאן אתה דן לכל איסורין שבתורה.\u0004 אם כן \u0003לר' עקיבא נמי\u0004 \u0005[גם כן]\u0006 \u0003\"משרת\"\u0004 בא ללמד \u0003להיתר מצטרף לאיסור\u0004 אצל נזיר, \u0003מכאן אתה דן לכל איסורין שבתורה כולה,\u0004 ושלא כר' יוחנן המקבל את ההלכה הזו רק לאיסורי נזיר בלבד!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: אין להוכיח מכאן,"],["\u0003משום דהוה\u0004 \u0005[שהיו]\u0006 \u0003נזיר\u0004 וקרבן \u0003חטאת שני כתובין הבאין כאחד\u0004 ללמד אותו דין עצמו, וכלל בידינו ש\u0003אין מלמדין\u0004 כלומר, אין למדים מהם הלכה כללית לשאר דינים.","ומפרשים: \u0003נזיר\u0004 — \u0003הא דאמרן\u0004 \u0005[זה שאמרנו].\u0006 \u0003חטאת מאי היא\u0004 \u0005[מה הוא]\u0006 ענינה — \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"כל אשר יגע בבשרה יקדש\"\u0004 (ויקרא ו, כ), \u0003יכול\u0004 תהא אסורה \u0003אפילו לא בלעה\u0004 אותה חתיכה שנגעה בחטאת שום דבר מן החטאת, \u0003תלמוד לומר \"בבשרה\" יקדש — עד שיבלע בבשר.\u0004","\u0003\"יקדש\"\u0004 משמעו — \u0003להיות כמוה\u0004 כמו החטאת, \u0003שאם פסולה היא\u0004 החטאת — \u0003תיפסל\u0004 גם אותה חתיכה שבלעה ממנה. \u0003ואם כשירה היא\u0004 החטאת — \u0003תאכל\u0004 החתיכה שנגעה בה \u0003כחמור שבה\u0004 כחטאת, כלומר תיאכל ככל החומרות שיש בחטאת (מבחינת המקום ומבחינת הזמן). הרי אף כאן דנים טעם כעיקר, ומשום כך אין למדים מהלכות אלה לכל התורה כולה.","ושואלים: \u0003ורבנן נמי\u0004 \u0005[ו\u0006לשיטת \u0005חכמים גם כן]\u0006 \u0003ניהוי\u0004 \u0005[שיהיו]\u0006 \u0003נזיר וחטאת שני כתובין הבאין כאחד, ואין מלמדין\u0004 שייאסר טעם כעיקר בשאר דינים שבתורה!","ומשיבים: \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003הנהו מיצריך צריכי\u0004 \u0005[אלה צריכים\u0006 כל אחד לעצמו\u0005]\u0006 וכיון שכך אין לראותם כשני כתובים הבאים כאחת ואפשר ללמוד מהם.","ושואלים: \u0003ור' עקיבא\u0004 שבכל זאת אינו לומד מכאן אינו סבור כן, כי \u0003מאי צריכי\u0004 \u0005[ל\u0006שם \u0005מה נצרכו]\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003אי כתב רחמנא\u0004 \u0005[אם הכתוב אומר]\u0006 רק \u0003בחטאת לא גמר נזיר מינה\u0004 \u0005[לא היה לומד נזיר ממנה]\u0006 משום ש\u0003חולין מקדשים לא גמרינן\u0004 \u0005[אין אנו למדים],\u0006 שהרי ידוע שיש בקדשים חומרות ודינים מיוחדים. \u0003אלא, לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003בנזיר, ותיתי\u0004 \u0005[ותבוא]\u0006 ה\u0003חטאת ותגמור מיניה\u0004 \u0005[ותלמד ממנה]\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003כל איסורין שבתורה קא גמר\u0004 \u0005[למד]\u0006 \u0003מנזיר,\u0004 וכיון שבכל זאת כתובים בתורה שניהם, הרי כאן שני כתובים הבאים כאחד ואין מלמדים.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם לומדים כן \u0003אמרי לך\u0004 \u0005[אומרים לך]\u0006 \u0003מיצרך צריכי\u0004 \u0005[צריכים הם]\u0006 שניהם ואין ללמוד זה מזה, כי הדין הנזכר ב\u0003חטאת\u0004 ללמדנו הלכה ש\u0003היתר מצטרף לאיסור, וחולין מקדשים לא גמר\u0004 \u0005[אינו לומד]\u0006 \u0003ו\"משרת\"\u0004 הכתובה בנזיר — \u0003ליתן טעם כעיקר,\u0004 ומכיון שנצרכים שניהם הרי שאינם שני כתובים הבאים כאחד ויכולים ללמד, \u0003ומכאן אתה דן לכל התורה כולה.\u0004","ולשיטת \u0003ר' עקיבא — תרוייהו\u0004 \u0005[שניהם]\u0006 באו ללמדנו כי \u0003היתר מצטרף לאיסור, והוו להו\u0004 \u0005[ונעשו להם]\u0006 \u0003שני כתובין הבאין כאחד\u0004 באותו נושא \u0003וכל שני כתובין הבאין כאחד אין מלמדין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: אלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]\u0006 על הכתוב: \u0003\"מכל אשר יעשה מגפן היין מחרצנים ועד זג\u0004 לא יאכל\u0003\"\u0004 (במדבר ו, ד), \u0003לימד על איסורי נזיר שמצטרפים זה עם זה,\u0004 שגם אם לא אכל כדי שיעור שלם מאחד מהם אלא מאחדים יחד — חייב. \u0003השתא\u0004 \u0005[עכשיו]\u0006 אפשר לשאול: הרי לשיטת \u0003ר' עקיבא איסור והיתר מצטרפין, איסור ואיסור מיבעיא\u0004 \u0005[נצרך\u0006 לומר\u0005]\u0006 שהם מצטרפים?! ולשיטה זו הרי כל הפסוק מיותר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 בכל זאת יש צורך בפסוק זה כי אין הדברים זהים זה לזה, כי \u0003איסור והיתר\u0004 מצטרפים רק כאשר אוכלים את שניהם \u0003בבת אחת,\u0004 ואילו \u0003איסור ואיסור\u0004 מצטרפים גם \u0003בזה אחר זה\u0004 כלומר, שאם אכל כחצי זית חרצנים וכחצי זית זג מצטרפים האיסורים לשיטת ר' עקיבא.","\u0003בצק\u0004 שנמצא \u0003בסידקי עריבה\u0004 (כלי גדול שלשים בו), \u0003אם יש כזית\u0004 בצק \u0003במקום אחד — חייב לבער, ואם לא — בטל\u0004 הבצק \u0003במיעוטו.\u0004","\u0003וכן לענין\u0004 דיני \u0003הטומאה\u0004 והטהרה, \u0003אם מקפיד עליו\u0004 על הבצק שבסדקים להסירו — \u0003חוצץ\u0004 שהוא חומר זר, ואין לעריבה טהרה בטבילה וכיוצא בה כשנשאר דבוק, \u0003ואם רוצה בקיומו\u0004 של הבצק באותו מקום — \u0003הרי הוא\u0004 נדון \u0003כעריבה\u0004 עצמה ואינו חוצץ.","\u0003אמר רב יהודה אמר שמואל: לא שנו\u0004 שכזית חמץ במקום אחד חייב לבער \u0003אלא במקום שאין עשויין\u0004 פירורי הבצק \u0003לחזק\u0004 את העריבה, \u0003אבל במקום שעשויין לחזק\u0004 ומן הסתם ישאירם לצורך זה — \u0003אינו חייב לבער\u0004 שכן הוא מבטלו.","ומסיקים מכאן: \u0003מכלל\u0004 הדברים נלמד כי \u0003פחות מכזית אפילו במקום שאין עשוי לחזק — אינו חייב לבער.\u0004","\u0003איכא דמתני לה אסיפא\u0004 \u0005[יש ששונים את\u0006 הערת ר' יהודה \u0005על סופה\u0006 של המשנה\u0005]\u0006 שנאמר בה: \u0003\"ואם לאו בטל במיעוטו\". אמר רב יהודה אמר שמואל: לא שנו\u0004 שפחות מכזית במקום אחד אינו חייב לבער \u0003אלא\u0004 כשהוא \u0003במקום העשוי לחזק, אבל\u0004 כשהוא \u0003במקום שאין עשוי לחזק — חייב לבער,\u0004 ומכאן נסיק \u0003מכלל\u0004 הדברים נלמד כי \u0003כזית, אפילו במקום העשוי לחזק — חייב לבער.\u0004","ומעירים: \u0003תניא כלישנא קמא, תניא כלישנא בתרא\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כלשון ראשונה שנוייה\u0006 ברייתא \u0005כלשון אחרונה].\u0006 \u0003תניא כלישנא קמא\u0004 \u0005[שנויה\u0006 ברייתא \u0005כלשון ראשונה]:\u0006 \u0003בצק שבסידקי עריבה במקום העשוי לחזק — אינו חוצץ\u0004 לטהרה מטומאה \u0003ואינו עובר\u0004 עליו משום חמץ בפסח. \u0003ובמקום שאין עשוי לחזק — חוצץ ועובר. במה דברים אמורים — בכזית, אבל בפחות מכזית אפילו במקום שאין עשוי לחזק — אינו חוצץ ואינו עובר.\u0004","\u0003ותניא כלישנא בתרא\u0004 \u0005[ושנויה\u0006 ברייתא \u0005כלשון אחרונה]:\u0006 \u0003בצק שבסידקי עריבה, במקום העשוי לחזק\u0004 —"],["\u0003אינו חוצץ\u0004 לטהרה \u0003ואינו עובר\u0004 בפסח, ואילו אם היה החמץ \u0003במקום שאין עשוי לחזק — חוצץ ועובר. במה דברים אמורים\u0004 — כשהיה פירור החמץ \u0003בפחות מכזית, אבל בכזית, אפילו במקום העשוי לחזק — חוצץ ועובר.\u0004","ומעירים: מכל מקום, \u0003קשיין אהדדי\u0004 \u0005[קשות הן\u0006 הברייתות \u0005זו על זו].\u0006 \u0003אמר רב הונא: סמי קילתא מקמי חמירתא\u0004 \u0005[מחוק\u0006 את \u0005המקילה\u0006 שבהן, \u0005מפני המחמירה]\u0006 ואמור שהברייתא הראשונה אינה מדוייקת.","\u0003רב יוסף אמר:\u0004 האם את \u0003תנאי שקלת מעלמא\u0004 \u0005[התנאים נוטל אתה מן העולם]?!\u0006 מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא,\u0004 ואין ברייתא אחת משובשת אלא אך מבטאה דעתו של חכם אחד. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הפת שעיפשה,\u0004 ושוב אינה ראויה למאכל — \u0003חייב לבער, מפני שראוי לשוחקה ולחמע\u0004 (להחמיץ) \u0003בה כמה עיסות אחרות,\u0004 משמע שאף חמץ שאינו ראוי לאכילה חייב לבערו.","ואילו \u0003ר' שמעון בן אלעזר אומר: במה דברים אמורים\u0004 — \u0003ב\u0004זמן שאותה פת \u0003מקויימת לאכילה, אבל כופת\u0004 (גוש) \u0003שאור שייחדה לישיבה\u0004 ולא לאכילה — \u0003בטלה.\u0004 ונדייק: \u0003מ\u0004מה ש\u0003אמר ר' שמעון בן אלעזר בטלה, מכלל\u0004 הדברים נבין ש\u0003תנא קמא סבר לא בטלה, אלמא\u0004 \u0005[מכאן]\u0006 כי \u0003קסבר\u0004 \u0005[הוא,\u0006 התנא הראשון, \u0005סבר]:\u0006 \u0003כל כזית, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003מבטל\u0004 אותו — הוא \u0003לא בטיל\u0004 \u0005[בטל],\u0006 וכמחלוקת זו, כן גם לעניננו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: תרצת בכזית,\u0004 שאת הסתירה בין הברייתות לגבי כזית חמץ תרצת על פי מחלוקת התנאים, שלדעת תנא קמא אין לכזית ביטול כלל, ולדעת ר' שמעון בן אלעזר יש לו ביטול. ואולם \u0003פחות מכזית מי\u0004 \u0005[האם]\u0006 \u0003תרצת?\u0004 הרי הברייתות מחולקות לא רק בכזית, אלא גם בפחות מכזית במקום שאינו עשוי לחזק, וכיצד מסביר אתה סתירה זו? \u0003אלא הא והא\u0004 \u0005[זו וזו\u0006 ברייתות אלו\u0005]\u0006 שיטת \u0003ר' שמעון בן אלעזר היא, ולא קשיא\u0004 \u0005[קשה\u0006 הסתירה\u0005],\u0006 \u0003הא\u0004 \u0005[כאן]\u0006 שאסר — הרי זה \u0003במקום לישת\u0004 הבצק, שהעיסה נוגעת בחמץ שבסדק. \u0003הא\u0004 \u0005[זה]\u0006 שהתיר — \u0003שלא במקום לישה.\u0004","\u0003אמר רב אשי: לא תימא\u0004 \u0005[תאמר]\u0006 שזה שנאמר כי אפילו פחות מכזית חוצץ \u0003שלא במקום לישה\u0004 הוא דווקא, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 הוא דווקא \u0003אגבה דאגנא\u0004 \u0005[על גב האגן\u0006 מבחוץ\u0005]\u0006 \u0003אלא אשיפתא דאגנא\u0004 \u0005[על שפת האגן]\u0006 גם כן אינו נקרא מקום לישה, שהרי אין הבצק מגיע לשם.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ולשם מה לומר זאת? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003זמנא דאטיף ומטי להתם\u0004 \u0005[פעמים ש\u0006הוא \u0005נוטף ומגיע לשם],\u0006 \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאינו קרוי מקום לישה קבוע, ולכן משם אינו חייב לבער.","\u0003אמר רב נחמן אמר רב: הלכה כר' שמעון בן אלעזר\u0004 בענין כופת שאור שייחדה לישיבה.","ותוהים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 והרי \u0003אמר רב יצחק בר אשי אמר רב: אם טח פניה של\u0004 כופת השאור \u0003בטיט — בטלה.\u0004 ונדייק: אם \u0003טח — אין\u0004 \u0005[כן]\u0006 בטלה, \u0003לא טח — לא,\u0004 וסותרים דברי רב אלה את אלה!","ומשיבים: \u0003מאן דמתני הא\u0004 \u0005[מי ששונה\u0006 את \u0005זאת]\u0006 \u0003לא מתני הא\u0004 \u0005[שונה\u0006 את \u0005זו].\u0006 כלומר, חלוקים שני האמוראים בשיטתו של רב.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, \u0003אמר רב נחמן אמר רב: אין הלכה כר' שמעון בן אלעזר,\u0004 וראיה לדבר ש\u0003אמר ר' יצחק בר אשי אמר רב: אם טח פניה בטיט — בטלה,\u0004 משמע שאם לא טח — לא בטלה, וכדברי תנא קמא.","\u0003אמר רב נחמן אמר שמואל: היו שני חצאי זיתים\u0004 של חמץ \u0003וחוט של בצק ביניהן\u0004 המחברם יחד, \u0003רואין: כל שאילו ינטל החוט\u0004 ויוגבה, \u0003וניטלין עמו\u0004 שני חצאי הזית — \u0003חייב לבער,\u0004 שהחוט מחברם לכזית שלם אחד. \u0003ואם לאו — אינו חייב לבער.\u0004","\u0003אמר עולא: לא אמרן\u0004 \u0005[אמרנו]\u0006 הגבלה זו \u0003אלא\u0004 בשני זיתים המצויים \u0003בעריבה\u0004 שהם דבוקים בדפנותיה, \u0003אבל\u0004 אם היו מונחים \u0003בבית\u0004 — \u0003חייב לבער,\u0004 אף אם אין החוט מצרפם,","\u0003מאי טעמא\u0004 \u0005[מה הטעם],\u0006 \u0003דזימנין דכניש להו\u0004 \u0005[שפעמים שאוסף אותם]\u0006 כאשר מנקה את הבית \u0003ונפלי גבי הדדי\u0004 \u0005[ונופלים זה אל זה],\u0006 ונמצא כזית חמץ במקום אחד.","\u0003אמר עולא: בעו במערבא\u0004 \u0005[שאלו בארץ ישראל]\u0006 כהמשך לענין זה, \u0003בית ועלייה מהו,\u0004 אם היה חצי זית בבית וחצי זית בעלייה, מה יהא הדין? או \u0003בית ואכסדרה מהו?\u0004 וכן \u0003שני בתים זה לפנים מזה מהו?\u0004","ולא נמצאה תשובה לשאלה ונשארה ב\u0003תיקו.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הפת שעיפשה ונפסלה מלאכול לאדם, ו\u0004אולם \u0003הכלב\u0004 עדיין \u0003יכול לאוכלה — מטמאה טומאת אוכלין ב\u0004שיעור \u0003כביצה,\u0004 שלא בטלה ממנה מכל וכל תורת מאכל, ודין טומאה. ואם היתה פת זו של תרומה טהורה — \u0003נשרפת עם\u0004 התרומה \u0003הטמאה בפסח,\u0004 שכיון שנפסלה מאכילת אדם שוב אין איסור לטמאה. \u0003משום\u0004 \u0005[בשם]\u0006 \u0003ר' נתן אמרו: אינה מטמאה.\u0004","ושואלים: \u0003כמאן אזלא הא דתנן\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת זו ששנינו\u0006 במשנה\u0005],\u0006 \u0003כלל אמרו בטהרות: כל\u0004 מאכל \u0003המיוחד לאוכל אדם — טמא עד שיפסל מלאכול לכלב. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 — ש\u0003לא כ\u0004דברי \u0003ר' נתן,\u0004 שהרי מדבריו יוצא שהמיוחד לאוכל אדם, אם נפסל לאכילת אדם נטהר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עריבת העבדנין\u0004 (מעבדי העורות) \u0003שנתן לתוכה קמח\u0004 לסייע בעיבוד העור, אם חל פסח \u0003תוך שלשה ימים\u0004 לנתינת הקמח — \u0003חייב לבער,\u0004 שעדיין הוא בבחינת חמץ הניתן לאכילה. \u0003קודם שלשה ימים — אינו חייב לבער,\u0004 שכבר התקלקל הקמח ונפסל לגמרי לאכילה. \u0003אמר ר' נתן: במה דברים אמורים\u0004 שיעור זמן זה — ש\u0003לא נתן לתוכה\u0004 לעריבה \u0003עורות, אבל נתן לתוכה עורות — אפילו תוך שלשה\u0004 ימים \u0003אין חייב לבער,\u0004 שהעורות שריחם רע בוודאי הפסידו לגמרי את הקמח לאכילת אדם.","\u0003אמר רבא: הלכה כר' נתן\u0004 בענין זה. ואין שיעור זמן קצוב לכך, \u0003ואפילו\u0004 היו העורות \u0003יום אחד ואפילו שעה אחת,\u0004 פסלו את הקמח מאכילה.","שנינו במשנה: \u0003וכן לענין טומאה אם מקפיד עליו\u0004 על החמץ להסירו — \u0003חוצץ, ואם רוצה בקיומו\u0004 — \u0003הרי הוא כעריבה.\u0004","ותוהים: \u0003מי דמי\u0004 \u0005[האם דומים]\u0006 דיני פסח וטומאה זה לזה? הרי \u0003התם\u0004 \u0005[שם]\u0006 בענין חמץ — \u0003בשיעורא תליא מילתא\u0004 \u0005[בשיעור תלוי הדבר],\u0006 שכזית חמץ יש בו איסור. \u0003הכא\u0004 \u0005[כאן]\u0006 בדין טומאה — \u0003בקפידא תליא מילתא\u0004 \u0005[בהקפדה תלוי הדבר],\u0006 שאין שיעור קבוע בכך, ודנים אם הדבר נחשב כחלק מן העריבה רק לפי הדרך בה הוא מתייחס ומקפיד בדבר.","\u0003אמר רב יהודה: אימא\u0004 \u0005[אמור]\u0006 ותקן בלשון המשנה: \u0003ולענין הטומאה אינו כן,\u0004 שאין הדבר תלוי בשיעור אלא בהקפדה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: הא\u0004 \u0005[הרי]\u0006 \u0003\"וכן לענין טומאה\" קתני\u0004 \u0005[שנינו]\u0006 ואין לשבש לשון המשנה רק משום שאיננו יודעים לתרצה! \u0003אלא אמר אביי\u0004 יש לחזור מתירוץ זה ו\u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש להבין: \u0003וכן\u0004"],["\u0003לענין צירוף טומאה\u0004 של שני דברים \u0003בפסח\u0004 הדין תלוי בשיעור, \u0003ו\u0004אילו \u0003בשאר ימות השנה איכא פלוגתא\u0004 \u0005[יש חילוק]\u0006 בין מקפיד לשאינו מקפיד.","ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה\u0006 הדבר\u0005],\u0006 \u0003כגון דאיכא\u0004 \u0005[שהיה]\u0006 \u0003פחות מכביצה אוכלין\u0004 שנטמאו, \u0003ונגעו בהאי\u0004 \u0005[בזה]\u0006 ה\u0003בצק\u0004 שבעריבה ואחר כך נגעו בו אוכלים טהורים. \u0003בפסח,\u0004 ש\u0003איסורו\u0004 של אותו בצק \u0003חשוב,\u0004 אף על פי ששיעורו קטן — \u0003מצטרף\u0004 הוא ומשלים את השיעור לכביצה אוכלים ומטמא. ואילו \u0003בשאר ימות השנה,\u0004 שאין איסורו מחשיבו אלא \u0003בקפידא תליא מילתא\u0004 \u0005[בהקפדה\u0006 עליו \u0005תלוי הדבר],\u0006 \u0003אם מקפיד עליו\u0004 להסירו — \u0003מצטרף\u0004 שעדיין תורת אוכל עליו, ו\u0003אם רוצה בקיומו\u0004 באותו מקום — \u0003הרי הוא\u0004 נחשב \u0003כעריבה\u0004 עצמה, ושוב אינו כאוכל.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רבא: מי קתני\u0004 \u0005[האם שנינו\u0006 במשנה\u0005]\u0006 \u0003\"מצטרף\"? והא\u0004 \u0005[והרי]\u0006 \u0003\"חוצץ\" קתני\u0004 \u0005[שנינו],\u0006 ואין דברי אביי מסבירים זאת. \u0003אלא אמר רבא,\u0004 כך יש להבין את המשנה: \u0003וכן\u0004 הדין לגבי \u0003להעלות טהרה\u0004 (לטהר) \u0003לעריבה.\u0004","ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה\u0006 הדבר\u0005],\u0006 \u0003כגון דאיטמי הך\u0004 \u0005[שנטמאה זו]\u0006 ה\u0003עריבה, ובעי לאטבולי\u0004 \u0005[ורוצה להטבילה].\u0006 \u0003בפסח,\u0004 ש\u0003איסורו\u0004 של אותו כזית חמץ \u0003חשוב — חוצץ\u0004 הוא בעריבה, \u0003ולא סלקא\u0004 \u0005[עלתה]\u0006 \u0003לה\u0004 לעריבה \u0003טבילה\u0004 זו. ואילו \u0003בשאר ימות השנה בקפידא תליא מילתא\u0004 \u0005[בהקפדה תלוי הדבר]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003מקפיד עליו\u0004 על בצק זה להסירו — \u0003חוצץ, ואם רוצה בקיומו — הרי הוא כעריבה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב פפא: מי קתני\u0004 \u0005[האם שנינו\u0006 במשנה\u0005]\u0006 \u0003\"וכן לענין טהרה\"? הא\u0004 \u0005[הרי]\u0006 \u0003\"לענין טומאה\" קתני\u0004 \u0005[שנינו]!\u0006 \u0003אלא אמר רב פפא: וכן לענין להוריד טומאה\u0004 (לטמא) \u0003לעריבה\u0004 על ידי בצק זה.","ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה\u0006 הדבר\u0005],\u0006 \u0003כגון\u0004 ש\u0003נגע שרץ\u0004 מת \u0003בהאי\u0004 \u0005[בזה]\u0006 ה\u0003בצק. בפסח\u0004 ש\u0003איסורו\u0004 של כזית חמץ \u0003חשוב — חוצץ,\u0004 ונחשב כדבר לעצמו, \u0003ולא נחתה\u0004 \u0005[ירדה]\u0006 \u0003לה\u0004 ה\u0003טומאה\u0004 לעריבה אגב הבצק, שהרי הוא נחשב כדבר לעצמו ולא כחלק מן העריבה. \u0003בשאר ימות השנה דבקפידא תליא\u0004 \u0005[שבקפידתו\u0006 של האדם \u0005תלוי\u0006 הדבר\u0005],\u0006 \u0003אם מקפיד עליו\u0004 על הבצק להסירו אף בפחות מכזית — \u0003חוצץ\u0004 ואינו מטמא את העריבה, ו\u0003אם רוצה בקיומו — הרי הוא\u0004 כחלק מן \u0003העריבה\u0004 ונטמאה כל העריבה כאשר נגעה טומאה בבצק זה.","\u0003בצק החרש\u0004 שהוא כחרש שאינו מדבר ואין יודעים מה בליבו, כלומר, בצק שאין ניכרים בו סימנים ברורים אם החמיץ או לא, \u0003אם יש כיוצא בו\u0004 בצק אחר שהטילו בו מים באותה שעה עצמה \u0003שהחמיץ — הרי זה אסור,\u0004 שמן הסתם אף הבצק הזה, למרות שאין בו סימנים גלויים החמיץ אף הוא.","לאור הנאמר במשנה מבררים: \u0003אם אין שם כיוצא בו מהו,\u0004 כיצד בודקין אותו? \u0003אמר ר' אבהו אמר ר' שמעון בן לקיש:\u0004 נתנו חכמים שיעור זמן של חימוץ, והוא \u0003כדי שילך אדם ממגדל נוניא\u0004 ועד \u0003טבריא,\u0004 שהוא שיעור \u0003מיל.\u0004 ותוהים על הלשון: לשם מה הוא מזכיר את המרחק בין המקומות?","\u0003ונימא\u0004 \u0005[ושיאמר]\u0006 רק \u0003מיל!\u0004 ומסבירים: \u0003הא קא משמע לן\u0004 \u0005[זה השמיע לנו]\u0006 בדרך אגב \u0003דשיעורא\u0004 \u0005[ששיעור]\u0006 \u0003מיל\u0004 הוא כמו המרחק \u0003ממגדל נוניא ועד טבריא.\u0004","\u0003אמר ר' אבהו אמר ר' שמעון בן לקיש: לגבל\u0004 כלומר, לאדם המגבל עיסתם של אחרים, שראוי לו להקפיד על טהרת העיסה שהוא מגבל. \u0003ו\u0004כן על נטילת ידים \u0003לתפלה\u0004 (ערוך), \u0003ו\u0004כן \u0003לנטילת ידים\u0004 שלפני האוכל, שיעור הזמן הראוי לו לאדם ללכת למצוא מקוה מים כדי לטבול את הכלי בו הוא מגבל את העיסה, וכן מים לטהר ידיו הוא \u0003ארבעה מילין.\u0004","\u0003אמר רב נחמן בר יצחק: אייבו אמרה\u0004 להלכה זו, \u0003וארבעה\u0004 דברים \u0003אמר בה\u0004 ולא שלושה בלבד, \u0003וחדא מינייהו\u0004 \u0005[ואחד מהם]\u0006 \u0003עבוד\u0004 עורות שיש להם שיעור כדי הליכת ארבעה מילין. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003וכולן\u0004 כל מיני העורות הרכים, שמשום רכותם דינם לענין טומאה כבשר, \u0003שעיבדן\u0004 לעשות מהם עור, \u0003או שהילך בהן\u0004 לדורסם, שהוא חלק מעיבודם, כדי שיעור \u0003עבודה\u0004 — \u0003טהורין,\u0004 שדינם מעתה כעור ואינם עוד כבשר, \u0003חוץ מעור האדם\u0004 שאינו יוצא מידי טומאתו מיד. ושאלו: \u0003וכמה\u0004 הוא \u0003כדי עבודה? אמר ר' אינייא אמר ר' ינאי: כדי הילוך ארבעה מילין.\u0004","\u0003אמר ר' יוסי בר' חנינא: לא שנו\u0004 שיעור זה שצריך לחזר אחרי מים לנטילת ידים שלפני האוכל ולתפילה \u0003אלא לפניו,\u0004 כשמקום המים הוא בתוך דרך הילוכו, \u0003אבל לאחריו\u0004 — \u0003אפילו מיל אינו חוזר. אמר רב אחא: ומינה\u0004 \u0005[וממנה]\u0006 משמועה זו נלמד: \u0003מיל\u0004 — \u0003הוא\u0004 ש\u0003אינו חוזר, הא\u0004 \u0005[הרי]\u0006 אם היה המרחק \u0003פחות ממיל — חוזר.\u0004","\u0003כיצד מפרישין חלה בטומאה ביום טוב\u0004 של פסח, כי חלה טהורה יכול להפרישה מן העיסה ולתתה מיד לכהן, ויאכלנה. ואולם חלה טמאה שאינה ראויה לכהן שצריכים להפרישה ולשורפה, ולשורפה אי אפשר — משום שאסור לשרוף דבר שאינו ראוי לאכילה ביום טוב. ולהמתין בשריפתה עד מוצאי החג אינו יכול — שמא תחמיץ.","\u0003ר' אליעזר אומר: לא תקרא לה\u0004 האשה שם, כלומר, לא תקדיש אותה בתור חלה \u0003עד שתאפה.\u0004 כלומר, תמתין עד שתאפה כל העיסה, ואחר כך תפריש חלה, ואז ישאירו את חלק החלה האפויה עד מוצאי יום טוב ולא יחמיץ, ואז ישרפוהו. \u0003בן בתירא אומר:\u0004 תפריש קודם אפיה, ו\u0003תטיל\u0004 את עיסת החלה \u0003בצונן\u0004 כדי שלא תחמיץ עד למוצאי החג. \u0003אמר ר' יהושע:\u0004"],["\u0003לא זה הוא חמץ שמוזהרין עליו בבל יראה ובבל ימצא\u0004 לפי שהחלה אינה שלו אלא כהקדש היא ואין לחשוש. \u0003אלא\u0004 כך יש לעשות: \u0003מפרישתה\u0004 האשה \u0003ומניחתה עד הערב, ואם החמיצה — החמיצה.\u0004","מציעים בגמרא: \u0003לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 שבשאלת מהותה של \u0003טובת הנאה קמיפלגי\u0004 \u0005[נחלקו],\u0006 כי החלה עצמה אינה שייכת למפריש אותה, אלא לכהן שיקבל אותה. ואולם בידי הבעלים יש טובת הנאה כלשהי. שכן כיון שהבעלים יכולים לתת את החלה ושאר מתנות כהונה למי שירצו, יכולים הם לקבל עבור נתינת החלה לכהן מסויים טובת הנאה ידועה. ונחלקו האם טובת הנאה זו יכולה להיחשב ממון השייך למפריש החלה או לא. ונאמר ש\u0003ר' אליעזר סבר:\u0004 כי \u0003טובת הנאה\u0004 הריהי נחשבת \u0003ממון,\u0004 ולכן יש לו צד ממון בחלה וצריך להיזהר שלא תחמיץ. \u0003ו\u0004אילו \u0003ר' יהושע סבר: טובת הנאה אינה\u0004 נחשבת \u0003ממון,\u0004 ולכן יכול להניחה שתחמיץ.","ודוחים: \u0003לא, דכולי עלמא סברי\u0004 \u0005[הכל סבורים]\u0006 ש\u0003טובת הנאה אינה\u0004 נחשבת \u0003ממון, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה של \u0003\"הואיל\" קמיפלגי\u0004 \u0005[נחלקו].\u0006 כיצד? ש\u0003ר' אליעזר סבר: אמרינן\u0004 \u0005[אומרים,\u0006 משתמשים \u0005אנו]\u0006 בנימוק של \u0003\"הואיל\".\u0004 והואיל \u0003ואי בעי איתשיל עלה\u0004 \u0005[ואם היה רוצה להישאל עליה\u0006 על הפרשת החלה\u0005]\u0006 ולהתחרט על כך — היה יכול לבטל את הקדשו כדין שאר הקדשות, הרי נמצא ש\u0003ממוניה\u0004 \u0005[ממונו]\u0006 \u0003הוא.\u0004 ואף שלא עשה כן, הואיל ויכול לעשות זאת — יש כאן צד ממון שלו. \u0003ו\u0004אילו \u0003ר' יהושע סבר: לא אמרינן\u0004 \u0005[אומרים,\u0006 משתמשים \u0005אנו]\u0006 בנימוק של \u0003\"הואיל\"\u0004 ויכול להישאל על הפרשתו יכול לשהותה לערב, ואין לחשוש מאיסור החמץ.","כיון שהוזכרה בעיה זו של \"הואיל\", מביאים מחלוקת אמוראים הקשורה בנושא זה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדין \u0003האופה\u0004 לחם \u0003מיום טוב ל\u0004צורך אכילת יום \u0003חול, רב חסדא אמר: לוקה\u0004 משום שחילל את יום טוב, \u0003רבה אמר: אינו לוקה.\u0004","ומבארים, \u0003רב חסדא אמר: לוקה\u0004 וטעם הדבר — \u0003לא אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003הואיל ו\u0004אם \u0003מיקלעי ליה\u0004 \u0005[מזדמנים לו]\u0006 \u0003אורחים\u0004 ביום טוב עצמו \u0003חזי ליה\u0004 \u0005[ראוי לו]\u0006 איפוא הלחם ליום טוב עצמו. ונמצא שבשעת אפיה אין זה הכרחי לומר שאותו לחם שאפה הוא לצורך החול. ואפילו לא יבואו אליו אורחים, מכל מקום אם בשעת אפיה היה מקום להניח שיכולים לבוא, יש להתיר. ורב חסדא אינו מקבל נימוק זה. \u0003רבה אמר: אינו לוקה,\u0004 כי לשיטתו \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003\"הואיל\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה לרב חסדא: לדידך\u0004 \u0005[לשיטתך],\u0006 \u0003דאמרת\u0004 \u0005[שאומר אתה]\u0006 ש\u0003לא אמרינן\u0004 \u0005[אומרים אנו]\u0006 נימוק זה של \u0003\"הואיל\", היאך\u0004 אם כן מתירים ו\u0003אופין מיום טוב לשבת? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משום עירובי תבשילין,\u0004 שעל ידי שמניחים עירובי תבשילין כתקנת חכמים — מותר לאפות מיום טוב לשבת.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003משום עירובי תבשילין שרינן איסורא דאורייתא\u0004 \u0005[מתירים אנו איסור מן התורה]?\u0006 שהרי עירובי תבשילין תקנת חכמים היא, וכיצד יכולים הם להתיר איסור מן התורה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מדאורייתא\u0004 \u0005[מ\u0006דין \u0005תורה]\u0006 \u0003צורכי שבת נעשים ביום טוב\u0004 ואיסור מלאכה ביום טוב לא חל על כך, ואולם \u0003רבנן הוא\u0004 \u0005[חכמים הם]\u0006 ש\u0003גזרו ביה\u0004 \u0005[בו]\u0006 \u0003גזירה שמא יאמרו אופין מיום טוב אף לחול. וכיון דאצרכוה רבנן\u0004 \u0005[שהצריכו חכמים]\u0006 \u0003עירובי תבשילין —\u0004 ממילא \u0003אית ליה היכירא\u0004 \u0005[יש לו היכר]\u0006 ויודע שלשבת שעושים עירוב תבשילין — מותר לבשל, ואילו לחול — אסור.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו: \u0003בהמה המסוכנת\u0004 העומדת למות מחמת סיבה כלשהי, ורוצה לשוחטה כדי שלא תמות מעצמה ותיאסר משום נבילה, \u0003לא ישחוט\u0004 ביום טוב \u0003אלא כדי שיכול לאכול הימנה כזית צלי מבעוד יום,\u0004 שאז ניתן לומר ששחט את הבהמה לצורך החג. ונדייק: \u0003יכול לאכול — אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא בעי למיכל\u0004 \u0005[צריך לאכול].\u0006 \u0003בשלמא לדידי, דאמרי\u0004 \u0005[נניח לי\u0006 לשיטתי, \u0005שאני אומר]\u0006 נימוק זה של \u0003\"הואיל\",\u0004 אפשר לומר: \u0003\"הואיל ואי בעי למיכל\u0004 \u0005[ואם היה רוצה לאכול] —\u0006 \u0003מצי אכיל\u0004 \u0005[היה יכול לאכול]\u0006 \u0003\"\u0004, \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003ישחוט. אלא לדידך, דאמרת לא אמרינן\u0004 \u0005[לך,\u0006 לשיטתך, \u0005שאומר אתה שאין אנו אומרים]\u0006 \u0003\"הואיל\", אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003ישחוט?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: הטעם שהתירו לו לשחוט אינו משום \"הואיל\", אלא \u0003משום הפסד ממונו.\u0004 ותהה רבה: \u0003ומשום הפסד ממונו שרינן איסורא דאורייתא\u0004 \u0005[מתירים אנו איסור מן התורה]?!\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 ולא בדיוק, אלא יש לומר: \u0003משום הפסד ממונו גמר בלבו לאכול כזית\u0004 צלי, שכיון שהבהמה עומדת למות ויפסיד את כולה, החליט שכדאי לו לפחות לאכול כזית ממנה, אף שכבר אינו צריך לאכילה זו, \u0003ו\u0004כיון ש\u0003אי אפשר\u0004 אפילו \u0003לכזית\u0004 אחד של \u0003בשר בלא שחיטה,\u0004 ממילא שוחט את הבהמה כולה אף שאינו יכול לאכול הכל.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 עוד רבה: שנינו כי \u0003לחם הפנים\u0004 שהיה בבית המקדש"],["\u0003נאכל לתשעה\u0004 ימים מזמן אפייתו, או \u0003לעשרה, ו\u0004כן \u0003לאחד עשר — לא פחות ולא יותר. כיצד? כדרכו,\u0004 כלומר כרגיל \u0003לתשעה.\u0004 כיצד? \u0003נאפה בערב שבת — נאכל בשבת\u0004 הבאה \u0003לתשעה,\u0004 הרי שעוברים תשעה ימים מאפייתו עד אכילתו. ואם \u0003חל יום טוב להיות בערב שבת\u0004 — אין אופים אותו ביום טוב, אלא מקדימים לאפותו יום קודם לכן, ו\u0003נאכל לשבת\u0004 שבשבוע הבא, \u0003לעשרה\u0004 ימים. אם היו \u0003שני ימים טובים של ראש השנה,\u0004 לפני השבת — \u0003נאכל לשבת\u0004 הבאה, \u0003לאחד עשר\u0004 ימים, \u0003לפי שאינו\u0004 (אין עשייתו) \u0003דוחה לא את השבת ולא את היום טוב. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003צורכי שבת נעשין ביום טוב, אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא דחי\u0004 \u0005[דוחה]\u0006 את \u0003יום טוב?\u0004 שהרי לחם הפנים נאכל בשבת ונחשב כצורכי שבת!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003שבות קרובה,\u0004 צד חילול קדושת החג שנעשה עבור שבת הקרובה לחג — \u0003התירו.\u0004 ואולם \u0003שבות רחוקה,\u0004 עבור השבת שבשבוע הבא — \u0003לא התירו.\u0004","ושואלים: \u0003ול\u0004דעת \u0003רבן שמעון בן גמליאל\u0004 ש\u0003אמר משום\u0004 (בשם) \u0003ר' שמעון בן הסגן\u0004 כי אפיית לחם הפנים \u0003דוחה את יום טוב ואינו דוחה את יום צום\u0004 הכיפורים, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שכן רואים שיש מחלוקת תנאים בכך שר' שמעון בן הסגן סבור שמותר לעשות בחג צורכי שבת וחכמים אוסרים.","ומשיבים: לא בעיקרון היסודי נחלקו אלא \u0003בהא פליגי\u0004 \u0005[ב\u0006דבר \u0005זה נחלקו],\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 התנא הראשון\u0005]\u0006 \u0003סבר\u0004 כי \u0003שבות קרובה התירו, שבות רחוקה לא התירו,\u0004 ולכן אין אפיית לחם הפנים דוחה יום טוב. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון\u0005]\u0006 \u0003סבר: שבות רחוקה נמי\u0004 \u0005[גם כן]\u0006 \u0003התירו.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב מרי: שתי הלחם\u0004 שאופים לחג השבועות \u0003אינן נאכלות\u0004 לכהנים \u0003לא פחות משנים, ולא יותר על שלשה\u0004 ימים. \u0003כיצד? נאפות\u0004 כרגיל ב\u0003ערב יום טוב — נאכלות ליום טוב לשנים. חל יום טוב להיות אחר השבת,\u0004 ונאפות בערב שבת — \u0003נאכלות ליום טוב לשלשה. לפי שאינה דוחה\u0004 אפיית שתי הלחם \u0003לא את השבת ולא את היום טוב. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003צורכי שבת נעשין ביום טוב, השתא\u0004 \u0005[עכשיו]\u0006 שצורכי \u0003שבת ביום טוב שרי\u0004 \u0005[מותר],\u0006 צורכי \u0003יום טוב ביום טוב מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שמותר לאפות ביום טוב עצמו? ואם כן, מדוע אין אופים לצורכי יום טוב בו ביום?!","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בענין שתי לחם ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"\u0004אך אשר יאכל לכל נפש הוא לבדו יעשה \u0003לכם\"\u0004 (שמות יב, טז), ולמדים: \u0003\"לכם\" — ולא לגבוה,\u0004 כלומר ההיתר לאפות ולבשל ביום טוב הוא רק לצורכי אדם ולא לצורך הקודש.","ושואלים: \u0003ולרבן שמעון בן גמליאל\u0004 ש\u0003אמר משום\u0004 (בשם) \u0003ר' שמעון בן הסגן\u0004 שאפיית לחם הפנים \u0003דוחה את יום טוב, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 כלומר, כיצד מבין הוא את ה\"לכם\". ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003אבא שאול\u0004 ש\u0003אמר\u0004 שיש להבין בדרך זו: \u0003\"לכם\" ולא לגוים,\u0004 אבל לצורך הקדש — מותר.","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרבה\u0004 קושיה \u0003ביד רב אחא בר רב הונא: מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003\"הואיל\"? והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003יש חורש תלם אחד וחייבין עליה\u0004 על חרישה זו \u0003משום שמונה לאוין,\u0004 שעשה בכך שמונה איסורים. ומסבירים כיצד יכול דבר זה להיות: אם היה \u0003חורש בשור וחמור,\u0004 ועבר על \"לא תחרוש בשור ובחמור יחדיו\" (דברים כב, י). \u0003והן מוקדשים,\u0004 ונמצא שמעל בהקדש על ידי חרישה זו. \u0003ו\u0004אם עשה זאת לסייע בעיבוד \u0003כלאים בכרם,\u0004 עובר אף משום גידול כלאים"],["\u0003ו\u0004אם היה הדבר בשנה ה\u0003שביעית\u0004 (בשמיטה), שהוא עובר משום עבודת קרקע בשמיטה. \u0003ו\u0004היה הדבר \u0003ביום טוב,\u0004 ועבר משום עושה מלאכה ביום טוב. \u0003ו\u0004היה החורש \u0003כהן, ו\u0004נוסף לזה גם קיבל על עצמו גם להיות \u0003נזיר, ו\u0004אותו מקום היה \u0003בית הטומאה\u0004 מקום הטמא בטומאת המת שיש איסור מן התורה לכהן וכן לנזיר להיות בו ועובר בשני לאוים. ונמצא שעובר שמונה לאוין כאחד. \u0003ואי אמרינן\u0004 \u0005[ואם אומרים אנו]\u0006 \u0003\"הואיל\"\u0004 להתיר ביום טוב, אם כן על \u0003חרישה\u0004 ביום טוב ש\u0003לא ליחייב\u0004 \u0005[יתחייב],\u0006 \u0003הואיל וחזי\u0004 \u0005[וראויה]\u0006 חרישה זאת \u0003לכיסוי דם ציפור.\u0004 שהשוחט ציפור או חיה חייב מן התורה לכסות את הדם בעפר, ויתכן שיזדמנו לידו מספר רב של ציפורים או חיות ויחסר לו עפר לכסות את הדם, ואם כן נמצא שחרש כדי להשיג לעצמו עפר לכיסוי הדם, ואין בכך מלאכה אסורה!","\u0003אמר רב פפא בר שמואל:\u0004 כאן מדובר שחרש \u0003באבנים מקורזלות,\u0004 כלומר בגושי אדמה נוקשים שאינם ראויים לכיסוי.","ושואלים: והרי אבנים מקורזלות אף הן \u0003ראויות לכותשן\u0004 לעפר! ודוחים: \u0003וכתישה ביום טוב מי שרי\u0004 \u0005[האם מותרת]?\u0006 ושואלים: והרי \u0003ראויות\u0004 הן \u0003לכותשן כלאחר יד,\u0004 שלא יעשה מלאכה כדרכו אלא בשינוי ובאופן שאינו אסור מן התורה. ודוחים: מדובר כאן כשחרש \u0003בצונמא\u0004 (באדמת טרשים קשה).","ותוהים: \u0003ו\u0004כי \u0003צונמא בר\u0004 \u0005[בן,\u0006 ראויה\u0005]\u0006 ל\u0003זריעה\u0004 היא?! והרי אמרנו שאותו אדם עושה באותה שעה מלאכה בזרעים ובכרם! ומשיבים: היה כאן \u0003צונמא מלמעלה ועפר תיחוח מלמטה,\u0004 ובו צומחים הזרעים. ודוחים: \u0003ו\u0004אם כן, \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 \u0003משום עפר תיחוח,\u0004 שהרי בעפר תיחוח זה יכול לכסות את דם הציפור!","\u0003אלא אמר מר בר רב אשי:\u0004 מדובר כאן \u0003בטינא\u0004 \u0005[בטיט],\u0006 שאינו ראוי לכיסוי. ושואלים: \u0003ו\u0004כי \u0003טינא בר\u0004 \u0005[בן,\u0006 ראוי\u0005]\u0006 ל\u0003זריעה הוא?!\u0004 ומשיבים: \u0003במתונתא\u0004 \u0005[באדמה לחה],\u0006 שאינה טיט גמור וראויה לזריעה, אבל עכשיו אי אפשר לפורר את הרגבים שלה ולעשותם עפר לכיסוי הדם.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 לרבה על שיטתו שהוא מתיר משום \"הואיל\" ממה ששנינו: \u0003המבשל\u0004 את \u0003גיד הנשה בחלב ביום טוב ואוכלו — לוקה חמש.\u0004 כיצד? \u0003לוקה משום מבשל גיד ביום טוב,\u0004 שבישל דבר שאינו ראוי לאכילה. \u0003ולוקה משום אוכל גיד,\u0004 בניגוד לאיסור המפורש בתורה. \u0003ולוקה משום מבשל בשר בחלב, ולוקה משום אוכל בשר בחלב. ולוקה משום הבערה,\u0004 שהבעיר אש ביום טוב שלא לצורך. \u0003ואי אמרינן\u0004 \u0005[ואם אומרים אנו]\u0006 \u0003\"הואיל\"\u0004 — אם כן, על ה\u0003הבערה\u0004 ש\u0003לא ליחייב\u0004 \u0005[יתחייב],\u0006 \u0003הואיל דחזי ליה\u0004 \u0005[שראוי לו]\u0006 הבערה זו \u0003לצרכו,\u0004 שהרי יכול להשתמש לבישול שלצורך החג!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003אפיק\u0004 \u0005[הוצא]\u0006 מרשימה זו \u0003הבערה ועייל\u0004 \u0005[והכנס]\u0006 במקומה איסור אחר, כגון שהיה זה \u0003גיד הנשה של נבילה,\u0004 שחייב אף משום אכילת נבילה.","הקשה לו אביי: \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא\u0004 כהסבר למשנה זו: \u0003לוקין שתים על אכילתו\u0004 של גיד זה (גיד, ובשר בחלב), \u0003ושלוש על בישולו\u0004 (הבערה ובישול ביום טוב, בישול בשר בחלב). \u0003ואי איתא\u0004 \u0005[ואם יש\u0006 לומר\u0005]\u0006 שמדובר בגיד הנשה של נבילה, הרי נמצא \u0003שלש על אכילתו מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]:\u0006 משום גיד, משום בשר בחלב, ומשום נבילה!","\u0003אלא\u0004 אמר רבה: \u0003אפיק\u0004 \u0005[הוצא]\u0006 מכאן מלאכת \u0003הבערה, ועייל\u0004 \u0005[והכנס]\u0006 איסור אחר, כגון שבישל ב\u0003עצי מוקצה\u0004 שמוקצים משימוש ביום טוב מפני שלא הוכנו לכך.","ותוהים: \u0003ו\u0004כי איסור \u0003מוקצה דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוא\u0004 שילקו עליו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והיה ביום הששי והכינו את אשר יביאו\"\u0004 (שמות טז, ה). ומכאן אפשר ללמוד שכל דבר שאינו מוכן מבעוד יום — הריהו מוקצה, ואסור. ואף שמכאן למדים אנו שיש איסור בשימוש במוקצה, מכל מקום איסור זה לא נתפרש בלשון \"לאו\". ולכן יש להוסיף \u0003ואזהרתה\u0004 של עבירה זו שמפורש שיש מצוות לא תעשה בדבר, \u0003מהכא\u0004 \u0005[מכאן],\u0006 \u0003מ\u0004מה שנאמר בשבת \u0003\"לא תעשה כל מלאכה\"\u0004 (שמות כ, י) שנאסרה באופן כולל כל מלאכה האסורה בשבת, ובכלל זה גם שימוש בדברים שלא הכין מבעוד יום.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003את\u0004 \u0005[אתה]\u0006 \u0003הוא\u0004 ש\u0003אמרת: בעאי מיניה\u0004 \u0005[שאלתי אותו]\u0006 את \u0003רב חסדא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר: \u0003בעאי מיניה\u0004 \u0005[שאלתי אותו]\u0006 את \u0003רב הונא:\u0004 אם \u0003הביא שה מאפר\u0004 (מן המרעה) שהוא מוקצה, מתוך שלא זימנוהו ובדקוהו מבעוד יום, \u0003ושחטו\u0004 לצורך \u0003תמיד ביום טוב, מהו?\u0004 האם אפשר להקריבו.","\u0003ואת אמרת לן\u0004 \u0005[ואתה אמרת לנו]\u0006 ש\u0003אמר לי עלה\u0004 \u0005[עליה,\u0006 על כך\u0005],\u0006 שדבר זה נלמד מן הכתוב ביחזקאל בדיני הקרבנות: \"ושה אחת מן הצאן מן המאתים ממשקה ישראל\" (יחזקאל מה, טו), ופסוק זה נדרש כך: \u0003\"שה\"\u0004 הכוונה לכל שה בין זכר בין נקבה ששניהם קרויים שה — \u0003ולא הבכור,\u0004 שהוא מיוחד שאינו אלא מן הזכרים.","\u0003\"אחת\"\u0004 — \u0003ולא מעשר,\u0004 שצריך להיות שה שאפשר שיהיה אחד בפני עצמו ולאו דווקא כאחד בין עשרה, ושה המעשר היא תמיד העשירית במנין השיות היוצאות מן הדיר, ולכן אינה בכלל הראויים לקרבן.","\u0003\"מן הצאן\",\u0004 המלה \"מן\" משמעותה לשון צמצום, להוציא מן הכלל — \u0003ולא הפלגס,\u0004 כלומר שלא יביא כבש שעבר את גיל שנה ועדיין לא הגיע להיות קרוי איל."],["\u0003\"מן המאתים\"\u0004 — נדרש לענין הבאת יין לנסכים: \u0003ממותר שתי מאות שנשתיירו\u0004 בבור, שרק אם נשארו בבור שתי מאות כנגד אותה מידה שניטלה — אפשר לקחת ממנו לצורך הנסכים. ומתוך שהצריך מאתים ודאי הוא משום איסור ערלה שנתערב ביין זה והריהו בטל במאתים, \u0003מכאן לערלה שבטילה במאתים,\u0004 כגון שענבי ערלה נתערבו ועשו מהם יין, והיו בבור היין מאתים שיעורים של היתר כנגדם — מתבטלת הערלה ברוב.","\u0003\"ממשקה ישראל\"\u0004 — משמעו: \u0003מן המותר לישראל,\u0004 שאין מעלים למזבח דבר שיש בו איסור לישראל. \u0003מכאן אמרו: אין מביאין נסכין מן הטבל,\u0004 שכן הטבל אסור לישראל.","\u0003יכול לא יביא\u0004 קרבן מן \u0003המוקצה\u0004 בשבת או ביום טוב. \u0003אמרת: מה טבל מיוחד שאיסור גופו גרם לו — אף כל שאיסור גופו גרם לו\u0004 הוא נאסר משום שאסור לישראל. \u0003יצא מוקצה שאין איסור גופו גרם לו, אלא איסור דבר אחר גרם לו,\u0004 הוא איסור שבת. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003איסור מוקצה דאורייתא\u0004 \u0005[שמן התורה]\u0006 הוא, \u0003מה לי איסור גופו מה לי איסור דבר אחר?\u0004 ומה טעם לחלק ביניהם? שאם הדבר אסור, אסור הוא מכל מקום. אלא ודאי איסור מוקצה הוא רק מדברי סופרים, ולכן אינו נאסר במקדש, משום שלא גזרו בו חכמים דיני שבות.","\u0003ועוד\u0004 אפשר להקשות על אותה ברייתא מצד אחר: \u0003הא את\u0004 \u0005[הרי אתה]\u0006 \u0003הוא\u0004 ש\u0003אמרת\u0004 במסכת מכות \u0003חילוק מלאכות לשבת,\u0004 שאדם חייב להביא שני קרבנות אם עושה שתי מלאכות איסור בהעלם אחד, או מלאכה אחת בשתי העלמות. \u0003ו\u0004אולם \u0003אין חילוק מלאכות ליום טוב,\u0004 שאין מתחייבים פעמיים במלקות אם עושה שתי מלאכות שונות בהעלם אחד ביום טוב, כי ביום טוב יש איסור מלאכה כללי שאינו מתחלק לאיסורי מלאכה נפרדים שיהא איסור על כל סוג מלאכה לעצמו. ואם כן, איך אתה מחייבו על איסור מוקצה ועל בישול גיד ביום טוב בנפרד.","\u0003אלא\u0004 כדי לתקן את הברייתא לשיטת רבה \u0003אפיק\u0004 \u0005[הוצא]\u0006 איסור \u0003הבערה, ועייל\u0004 \u0005[והכנס]\u0006 איסור \u0003עצי אשירה,\u0004 שמשתמש כאן בעצי אשירה. \u0003ואזהרה\u0004 כלומר, מקור האיסור בלשון \"לאו\" שיש בכך, נלמד \u0003מהכא\u0004 \u0005[מכאן]\u0006 מכתוב זה, שנאמר בעיר הנשרפת בשל עבודה זרה שבה \u0003\"ולא ידבק בידך מאומה מן החרם\"\u0004 (דברים יג, יח).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לאביי:\u0004 אם כן, \u0003ונלקי נמי\u0004 \u0005[ושילקה גם כן]\u0006 אם משתמש בעצי אשירה \u0003משום\u0004 איסור נוסף המפורש בעבודה זרה: \u0003\"ולא תביא תועבה אל ביתך\"\u0004 (דברים ז, כו). ואי אפשר לומר כן, שהרי הוא מוסיף לאו יתר על המנוי בברייתא.","\u0003אלא\u0004 יש לומר: \u0003אפיק\u0004 \u0005[הוצא]\u0006 איסור \u0003הבערה, ועייל\u0004 \u0005[והכנס]\u0006 במקומו איסור אחר, וכגון שמשתמש ב\u0003עצי הקדש. ואזהרה,\u0004 מקור לאיסור זה בלשון לאו הוא \u0003מהכא\u0004 \u0005[מכאן]\u0006 מכתוב זה שנאמר \u0003\"ואשריהם תשרפון באש... לא תעשון כן לה' אלהיכם\"\u0004 (דברים יב, ג-ד), שהשורף דבר של קודש בדרך השחתה — לוקה. ובסיכומם של דברים לא הצליחו להביא הוכחה לסתור לטענה של \"הואיל\".","\u0003אמר רמי בר חמא: הא\u0004 \u0005[\u0006המחלוקת \u0005הזו]\u0006 בין \u0003רב חסדא ורבה\u0004 ביחס ל\"הואיל\" \u0003מחלוקת\u0004 של \u0003ר' אליעזר ור' יהושע\u0004 במשנתנו \u0003היא.\u0004 ש\u0003ר' אליעזר\u0004 האומר שלא תפריש חלתה אלא לאחר אפייה \u0003סבר: אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003\"הואיל\",\u0004 ולכן מותר לאפות את העיסה כולה בלא להפריש ממנה חלה מלכתחילה, הואיל וכל חלק שבה ראוי לאכילה כשלעצמו, שמא לא ממנו יפרישו חלה. \u0003ור' יהושע סבר: לא אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003\"הואיל\".\u0004","\u0003אמר רב פפא:\u0004 אפשר לדחות באופן זה, \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003עד כאן לא\u0004 שמענו \u0003קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' אליעזר התם\u0004 \u0005[שם]\u0006 לגבי הפרשת חלה \u0003דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 \u0003\"הואיל\", אלא דבעידנא דקא עיילי לתנורא, כל חדא וחדא חזיא ליה לדידיה\u0004 \u0005[שבזמן שנכנסות לתנור, כל אחת ואחת ראויה לו עצמו]\u0006 ואין ראיה שמעיסה זו דוקא יפריש לחלה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בענין האופה ביום טוב שההיתר הוא משום ש\u0003לאורחין הוא דחזי\u0004 \u0005[שראוי],\u0006 \u0003לדידיה\u0004 \u0005[לעצמו]\u0006 \u0003לא חזי\u0004 \u0005[ראוי]\u0006 \u0003אימא הכי נמי דלא אמרינן\u0004 \u0005[אמור כך גם כן שאין אנו אומרים]\u0006 \u0003\"הואיל\".\u0004","ובאופן אחר דוחה את ההשוואה, \u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: ודילמא\u0004 \u0005[ושמא]\u0006 \u0003לא היא\u0004 ההשוואה; כי \u0003עד כאן לא\u0004 שמענו \u0003קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' יהושע התם דלא אמרינן\u0004 \u0005[שם שאין אנו אומרים]\u0006 \u0003\"הואיל\", אלא דאיכא חדא דלא חזיא\u0004 \u0005[שיש\u0006 חתיכה \u0005אחת שאינה ראויה]\u0006 \u0003לא לדידיה\u0004 \u0005[לו]\u0006 \u0003ולא לאורחין,\u0004 שהרי החלה הזו שבסופו של דבר תופרש אינה ראויה לשום אדם. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 באופה מיום טוב לחול, \u0003דחזי מיהת\u0004 \u0005[שראויה היא על כל פנים]\u0006 \u0003לאורחין, אימא הכי נמי אמרינן\u0004 \u0005[אמור\u0006 ש\u0005כך גם כן אומרים אנו]\u0006 \u0003\"הואיל\".\u0004","במקרה זה מסופר: \u0003אמרוה רבנן\u0004 \u0005[אמרו חכמים]\u0006 את דברי רמי בר חמא \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' ירמיה ור' זירא, ר' ירמיה קיבלה\u0004 את הסברו של רמי בר חמא, \u0003ר' זירא לא קיבלה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא: מילתא דקשיא לן ואתיא כמה שני במאי פליגי\u0004 \u0005[דבר שקשה לנו במשך כמה שנים במה חלוקים]\u0006 \u0003ר' אליעזר ור' יהושע, השתא אמרוה משמיה דגברא רבה, ולא ניקבלה\u0004 \u0005[עכשיו אמרו\u0006 את הסברה \u0005משמו של אדם גדול, ולא נקבל אותה]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003היכי\u0004 \u0005[כיצד]\u0006 \u0003אקבלה\u0004 את ההסבר הזה, \u0003דתנינא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]\u0006 שנמשך הויכוח, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהושע\u0004 לר' אליעזר: \u0003לדבריך, הרי הוא עובר משום \"לא תעשה כל מלאכה\"\u0004 (שמות כ, י), \u0003ושתיק ליה\u0004 \u0005[ושותק לו]\u0006 ולא השיב לו ר' אליעזר. \u0003ואי איתא\u0004 \u0005[ואם יש]\u0006 מקום לומר כדברי רמי בר חמא, \u0003לימא ליה\u0004 \u0005[שיאמר לו]:\u0006 \u0003טעמא דידי\u0004 \u0005[הטעם שלי]\u0006 \u0003משום \"הואיל\",\u0004 ולכן אין בו משום חילול יום טוב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ירמיה: \u0003וליטעמיך, הא דתנינא\u0004 \u0005[ולשיטתך, זו ששנינו]\u0006 \u0003בברייתא\u0004 באותו ענין ש\u0003אמר לו ר' אליעזר: לדבריך, הרי הוא עובר משום \"בל יראה ובל ימצא\", ושתיק ליה\u0004 \u0005[ושתק לו]\u0006 ולא נתפרש שם שענה לו ר' יהושע. \u0003הכי נמי דלא אהדר ליה? הא קא מהדר ליה במתניתין\u0004 \u0005[האם כך גם כן\u0006 תאמר \u0005שלא השיב לו? הרי השיב לו במשנתנו]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]\u0006 שאמר ר' יהושע: \u0003לא זהו חמץ שמוזהרין עליו משום \"בל יראה ובל ימצא\", אלא\u0004 בעל כרחך אתה מפרש: \u0003שתיק ליה\u0004 \u0005[שתק לו]\u0006 \u0003בברייתא,\u0004 כלומר לא הביא תשובתו בברייתא, \u0003ומהדר ליה במתניתין\u0004 \u0005[והחזיר\u0006 השיב \u0005לו במשנה].\u0006 \u0003הכי נמי, אימור שתיק ליה במתניתין, ואהדר ליה במכילתא אחריתי\u0004 \u0005[כך גם כן, אמור שתק לו במשנתנו, והחזיר לו\u0006 דברים \u0005במסכת אחרת].\u0006","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: הלכה\u0004 בענין הפרשת חלה מעיסה טמאה בפסח \u0003כר' אליעזר, ור' יצחק אמר: הלכה כבן בתירא.\u0004","שאלו: \u0003וכמה שיעור עיסה,\u0004 מהו השיעור שראוי ללוש ללא חשש חימוץ בפסח? \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: בחיטין\u0004 — כמות קמח הנעשית משני \u0003קבין, ובשעורין — שלשת קבין. ר' נתן אומר משום\u0004 (בשם) \u0003ר' אליעזר: חילוף הדברים,\u0004 בחיטים — שלוש, ובשעורים — שניים.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]\u0006 ש\u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: בחטין — שלשת קבין, ובשעורין — ארבעה קבין!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003בחסיכתא\u0004 \u0005[בגרועות],\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003במעלייתא\u0004 \u0005[בטובות],\u0006 כי מן הגרועות אין מוציאים אלא כמות קטנה של קמח, ומן הטובות אפשר להוציא יותר קמח.","\u0003אמר רב פפא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003גריעין חיטי חסיכתא מחיטי מעלייתא, טפי מדגריען שערי חסיכתא משערי מעלייתא\u0004 \u0005[גרועות חיטים פחותות מחיטים טובות, יותר משגרועות שעורים פחותות משעורים טובות].\u0006 ש\u0003אילו התם תילתא\u0004 \u0005[שם\u0006 בחיטים \u0005שליש]\u0006 יורד, שזהו ההבדל בין קביים ושלושה קבין, \u0003והכא ריבעא\u0004 \u0005[וכאן\u0006 בשעורים \u0005רבע]\u0006 בלבד יורד, שזהו ההבדל בין שלושה לארבעה קבין.","\u0003אמר רב: קבא מלוגנאה לפיסחא\u0004 \u0005[קב\u0006 של המקום \u0005מלוגנא\u0006 הוא שיעור הראוי ללוש עיסה \u0005לפסח],\u0006 \u0003וכן לחלה,\u0004 כלומר: והוא שיעור שממנו יש חובת הפרשת חלה. ושואלים: \u0003והתניא\u0004 \u0005[ו\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006"],["\u0003חמשת רבעים\u0004 (רבעי הקב) \u0003קמח ועוד\u0004 משהו \u0003חייבין בחלה,\u0004 שאין מפרישים חלה אלא מעיסה בגודל זה, שהוא שיעור \"עריסותיכם\" האמור בתורה. ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 \u0003קבא מלוגנאי נמי אהאי שיעורא קאי\u0004 \u0005[הקב המלוגנאי גם כן על שיעור זה הוא עומד].\u0006 כלומר, קב זה אינו קב רגיל אלא קב גדול ומיוחד.","\u0003אמר רב יוסף: הני נשי דידן נהוג למיפא קפיזא קפיזא לפיסחא\u0004 \u0005[אלו הנשים שלנו\u0006 בנות משפחתנו \u0005נוהגות לאפות\u0006 בזה אחר זה \u0005מידה\u0006 של שלושת רבעי הקב \u0005לפסח],\u0006 משום שעיסות קטנות אפשר להשגיח עליהן שלא תחמצנה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי דעתיך, לחומרא\u0004 \u0005[מה דעתך\u0006 שאתה אומר להן לעשות כן, כדי \u0005להחמיר],\u0006 והרי \u0003חומרא דאתי\u0004 \u0005[שבאה]\u0006 \u0003לידי קולא הוא,\u0004 משום \u0003דקא מפקע ליה\u0004 \u0005[ש\u0006הרי \u0005הוא מפקיע אותה\u0006 את העיסה\u0005]\u0006 מחובת הפרשת \u0003חלה,\u0004 שכן הוא פחות משיעור החייב בחלה.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 איני מפקיען מחובת חלה, משום \u0003דעבדן\u0004 \u0005[ש\u0006הן \u0005עושות]\u0006 ומפרישות \u0003כ\u0004שיטת \u0003ר' אליעזר, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: הרודה\u0004 ככרות לחם מן התנור \u0003ונותן לסל — הסל מצרפן לחלה,\u0004 אף אם אין באחת מן הככרות בפני עצמה כשיעור חלה. וכן היו נוהגות בנות ביתו של רב יוסף להפריש חלה מן המצות שבסל, \u0003ו\u0004כבר \u0003אמר רב יהודה אמר שמואל: הלכה כר' אליעזר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003והא איתמר עלה\u0004 \u0005[והרי נאמר עליה]\u0006 על קביעת הלכה זו \u0003אמר ר' יהושע בן לוי: לא שנו\u0004 שהסל מצרפן לחיוב חלה \u0003אלא\u0004 ב\u0003ככרות של בבל שנושכות\u0004 (דבוקות מעט) \u0003זו מזו, אבל כעכין\u0004 שאופים כל אחד לעצמו — \u0003לא,\u0004 והוא הדין אם כן לחלות. השיב רב יוסף: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליו],\u0006 \u0003אמר ר' חנינא:\u0004 הלכה כר' אליעזר \u0003אפילו\u0004 ב\u0003כעכין,\u0004 ולפי זה נהגו הלכה למעשה.","בעקבות אותה שאלה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: טבלא שאין לה לבזבזין\u0004 (שוליים) \u0003מהו,\u0004 האם נחשבת היא כלי לענין צירוף לחובת הפרשת חלה? וצדדי השאלה: האם \u0003תוך כלי בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003והא ליכא\u0004 \u0005[וזה אינו],\u0006 שאין בטבלה חלקה כדי קיבול. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אויר\u0004 \u0005(\u0006חלל) \u0003כלי בעינן, והא איכא\u0004 \u0005[צריכים אנו, והרי ישנו].\u0006 שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 הבעיה במקומה.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' אליעזר אומר: הסל מצרפן\u0004 ומחייבן בחלה. \u0003ר' יהושע אומר: תנור מצרפן. רבן שמעון בן גמליאל אומר: ככרות של בבל שנושכות זו מזו — מצטרפות\u0004 יחד לחלה, ולא אחרות.","\u0003רבן גמליאל אומר: שלש נשים לשות כאחת\u0004 את הבצק \u0003ואופות בתנור אחד, זו אחר זו.\u0004 ואין לחשוש שתוך הזמן שממתינות שתיאפנה מצותיה של אחת מהן יחמיץ בצקן של האחרות.","\u0003וחכמים אומרים: שלש נשים עוסקות בבצק כאחת\u0004 בזו אחר זו, כדי שלא להביא לחימוץ, \u0003אחת לשה ואחת עורכת\u0004 (מתקנת את הלישה ונותנת לה צורת לחם), \u0003ואחת אופה.\u0004","\u0003ר' עקיבא אומר: לא כל הנשים ולא כל העצים ולא כל התנורים שוין,\u0004 וממילא אין לקבוע מידה קבועה. אלא \u0003זה הכלל: תפח\u0004 (עומד להתנפח וקרוב להחמיץ) — \u0003תלטוש\u0004 (תמרח) עליו \u0003בצונן\u0004 במים צוננים שטובלת בהם ידיה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]\u0006 להסביר את דברי חכמים שבמשנה. אותה אשה שהיתה \u0003לשה\u0004 ראשונה, \u0003היא\u0004 עכשיו לאחר גמר לישה \u0003מקטפת, וחבירתה לשה תחתיה\u0004 (במקומה). וזו שהיתה \u0003מקטפת\u0004 וסיימה את מלאכת הקיטוף, \u0003היא\u0004 עכשיו \u0003אופה, וחבירתה מקטפת תחתיה, והשלישית לשה\u0004 תחתיה. \u0003אופה היא\u0004 הראשונה וסיימה מלאכתה, \u0003לשה\u0004 השלישית, \u0003וחבירתה\u0004 השניה \u0003אופה תחתיה, והשלישית מקטפת, וחוזרת חלילה\u0004 (חוזרות סביב סביב). ש\u0003כל זמן שעוסקות בבצק אינו בא לידי חימוץ.\u0004","על דברי המשנה \u0003ר' עקיבא אומר לא כל הנשים\u0004 שוות ולא כל העצים ולא כל התנורים שווים, \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' עקיבא: דנתי לפני רבן גמליאל, ילמדינו רבינו\u0004 האם \u0003בנשים זריזות\u0004 אמרו \u0003או בנשים שאין זריזות? בעצים לחים\u0004 אמרו \u0003או בעצים יבשים\u0004 אמרו? \u0003בתנור חם\u0004 אמרו \u0003או בתנור צונן\u0004 אמרו? \u0003אמר לי\u0004 רבן גמליאל עצמו: \u0003אין לך אלא מה ששנו חכמים: זה הכלל תפח\u0004 (עומד להתנפח וקרוב להחמיץ) — \u0003תלטוש\u0004 (תמרח) עליו \u0003בצונן\u0004 מים צוננים למניעת החימוץ.","\u0003שיאור\u0004 כלומר, כאשר עיסה החמיצה רק במקצת — \u0003ישרף, והאוכלו פטור\u0004 משום שעדיין אינו חמץ גמור. \u0003סידוק\u0004 כלומר, בצק שהתנפח עד כדי כך שנסדקו פניו — \u0003ישרף, והאוכלו\u0004 במזיד \u0003חייב כרת\u0004 כאוכל חמץ בפסח.","\u0003איזהו שיאור?\u0004 — כאשר נראו על פני הבצק סדקים \u0003כקרני חגבים, סידוק — שנתערבו סדקין זה בזה,\u0004 אלו \u0003דברי ר' יהודה. וחכמים אומרים: זה וזה האוכלו\u0004 במזיד \u0003— חייב כרת,\u0004 שאם נסדק מלמעלה ודאי שהחמיץ מבפנים. \u0003ואיזהו שיאור שפטור על אכילתו — כל שהכסיפו פניו,\u0004 הלבין צבע הבצק כגוון פניו של \u0003אדם שעמדו שערותיו\u0004 מחמת פחד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו שיאור — כל שהכסיפו פניו כאדם שעמדו שערותיו. סידוק\u0004 — הרי הוא \u0003כקרני חגבים,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: איזהו שיאור — כקרני חגבים, סידוק — שנתערבו סדקין זה בזה. וזה וזה האוכלו\u0004 במזיד — \u0003חייב כרת.\u0004","ומקשים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]\u0006 \u0003שיאור ישרף, והאוכלו פטור, דברי ר' יהודה.\u0004 והרי שיטת חכמים שבברייתא הלוא היא שיטת ר' יהודה שבמשנתנו, ולשיטתו האוכל את השיאור פטור! ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 והבן בברייתא\u0005]\u0006 כך: \u0003לר' מאיר\u0004 שהזכרנו דבריו קודם \u0003זה וזה, האוכלו\u0004 במזיד \u0003חייב כרת,\u0004 ולשיטת חכמים אכן פטור.","\u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר — אין לך כל סדק וסדק מלמעלה שאין לו כמה סדקים מלמטה.\u0004 ואם יש סידוק מלמעלה, ודאי שכל הבצק מבפנים מלא כולו סדקים והחמיץ הרבה."],["\u0003ארבעה עשר\u0004 בניסן \u0003שחל להיות בשבת — מבערין את הכל\u0004 כל החמץ, בין חולין בין תרומה, \u0003מלפני השבת,\u0004 חוץ ממה שצריך לאכול ביום השבת עצמו, שהרי בשבת אינו יכול לבער כמו בשאר ערבי פסחים. אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004 כל דבר מבערים בזמנו, סמוך לפסח, ויבערנו על ידי זריקה או הפקר. \u0003ר' אליעזר בר צדוק אומר: תרומה\u0004 — מבערים \u0003מלפני השבת,\u0004 משום שאין רבים יכולים לאוכלה, ומן הסתם לא יימצאו לה אוכלים נוספים, \u0003וחולין — בזמנן.\u0004","\u0003תניא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005],\u0006 \u0003ר' אליעזר בר' צדוק אומר: פעם אחת שבת אבא\u0004 (הוא ר' צדוק) \u0003ביבנה, וחל ארבעה עשר\u0004 בניסן \u0003להיות בשבת. ובא זונין\u0004 שהיה \u0003ממונה של רבן גמליאל ואמר: הגיע עת לבער את החמץ, והלכתי אחר אבא וביערנו את החמץ,\u0004 משמע שנהגו כן למעשה, לבערו בזמנו.","\u0003ההולך לשחוט את\u0004 קרבן \u0003פסחו\u0004 בערב פסח, \u0003ו\u0004כן \u0003למול את בנו, ו\u0004כן \u0003לאכול סעודת אירוסין בבית חמיו, ונזכר שיש לו חמץ בתוך ביתו. אם יכול לחזור\u0004 מיד לביתו \u0003ולבער\u0004 את החמץ \u0003ו\u0004אחר כך \u0003לחזור למצותו — יחזור ויבער, ואם לאו\u0004 שלא יספיק לחזור ולבער — \u0003מבטלו בלבו,\u0004 שהרי מן התורה ביטול בלבד מועיל.","ואם הלך \u0003להציל\u0004 ישראל \u0003מן הגוים\u0004 המתנפלים עליהם, \u0003ומן הנהר\u0004 שגאה ושטף, \u0003ומן הלסטים, ומן הדליקה, ומן המפולת\u0004 — אינו צריך אף לנסות לחזור, אלא \u0003יבטל\u0004 החמץ \u0003בלבו,\u0004 אפילו כשברור שיכול לחזור ולבער בזמנו. \u0003ו\u0004אם הלך \u0003לשבות שביתת הרשות,\u0004 שלא הלך למקום שיש בו צד מצוה — \u0003יחזור מיד\u0004 ויבער את החמץ.","\u0003וכן\u0004 כיוצא בהלכות אלה שבביעור חמץ, אמרו לגבי \u0003מי שיצא מירושלים ונזכר שיש בידו בשר קדש\u0004 שנפסל עם יציאתו מחוץ לתחומי ירושלים, ויש לשורפו ליד המקדש. \u0003אם עבר\u0004 את כפר \u0003צופים\u0004 שממנו עדיין ניתן לראות את ירושלים, ומשעבר שוב אינו יכול לראותה — \u0003שורפו במקומו\u0004 (במקום שנזכר בו). \u0003ואם לאו,\u0004 שלא הרחיק ללכת כל כך — \u0003חוזר ושורפו לפני הבירה\u0004 (המקדש) \u0003מעצי המערכה\u0004 שמספקים לצורך שריפת קדשים שנפסלו.","\u0003ו\u0004שואלים: \u0003עד כמה הן חוזרין,\u0004 מהו שיעור חמץ או בשר קודש שיש לחזור עבורו? \u0003ר' מאיר אומר: זה וזה בכביצה, ר' יהודה אומר: זה וזה בכזית. וחכמים אומרים\u0004 שיש לחלק: \u0003בשר קדש\u0004 — חוזרים עליו \u0003בכזית, וחמץ\u0004 — חוזרים עליו אם גודלו \u0003בכביצה.\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממקור אחר, ששנינו: \u0003ההולך לאכול סעודת אירוסין בבית חמיו ולשבות שביתת הרשות — יחזור מיד,\u0004 ואילו במשנתנו נאמר שיכול אף לבטלה בליבו, ומשום שהיא נחשבת כסעודת מצוה!","\u0003אמר ר' יוחנן: לא קשיא\u0004 \u0005[קשה]\u0006 כי יש בכך מחלוקת תנאים, \u0003הא\u0004 \u0005[זו]\u0006 הברייתא — כשיטת \u0003ר' יהודה,\u0004 ו\u0003הא\u0004 \u0005[זו]\u0006 המשנה — כשיטת \u0003ר' יוסי, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003סעודת אירוסין — רשות, דברי ר' יהודה. ר' יוסי אומר: מצוה\u0004 היא.","\u0003והשתא\u0004 \u0005[ועכשיו]\u0006 ש\u0003אמר ר' חסדא: מחלוקת\u0004 ר' יהודה ור' יוסי היא דוקא \u0003בסעודה שניה\u0004 של אירוסין, שחוזר החתן לאחר האירוסין לסעוד עם משפחת ארוסתו. \u0003אבל בסעודה ראשונה — דברי הכל מצוה.\u0004 אין צורך לישב את הסתירה בין המשנה לברייתא כפי שפירשנו אלא \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003הא והא\u0004 \u0005[זו וזו\u0006 המשנה והברייתא\u0005]\u0006 הן כ\u0003ר' יהודה, ולא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 המשנה שרואה זאת כסעודת מצוה — מדובר בה \u0003בסעודה ראשונה\u0004 שהיא מצוה, \u0003הא\u0004 \u0005[זו]\u0006 הברייתא המחייבת לחזור — מדברת \u0003בסעודה שניה.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003אמר ר' יהודה: אני לא שמעתי\u0004 שיש מצוה \u0003אלא\u0004 ב\u0003סעודת אירוסין\u0004 עצמה \u0003אבל לא\u0004 סעודת \u0003סבלונות\u0004 (מתנות), שכאשר בא החתן ומביא מתנות לכלה ועושים סעודה חגיגית — אין בכך כל מצוה. \u0003אמר לו ר' יוסי: אני שמעתי\u0004 גם \u0003סעודת אירוסין ו\u0004גם סעודת \u0003סבלונות.\u0004","כיון שהוזכרה סעודת מצוה ודנו בהגדרתה, מביאים ברייתא בנושא קרוב. \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר: כל סעודה שאינה של מצוה — אין תלמיד חכם רשאי להנות ממנה.\u0004","ושואלים: \u0003כגון מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 סעודה שאינה של מצוה, אף שהיה מקום להגדירה ככזאת? \u0003אמר ר' יוחנן: כגון בת כהן\u0004 הנישאת \u0003לישראל, ו\u0004כן \u0003בת תלמיד חכם\u0004 הנישאת \u0003לעם הארץ.\u0004 שאף שסעודת נישואין בכלל מצוה היא — אבל כאן אין מצוה, ש\u0003אמר ר' יוחנן: בת כהן לישראל — אין זווגן עולה יפה,\u0004 שגנאי הוא לכהונה שתינשא בת כהן לישראל.","ושאלו: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 מה פירוש שאין זיווגם עולה יפה? \u0003אמר רב חסדא:\u0004 שמתקיים בהם כלשון הפסוק המדבר במקרה של בת כהן הנישאת לישראל וחוזרת לבית אביה \u0003\"או אלמנה או גרושה או זרע אין לה\"\u0004 (ויקרא כב, יג). \u0003במתניתא תנא\u0004 \u0005[בברייתא שנינו]:\u0006 \u0003קוברה\u0004 בעלה \u0003או קוברתו\u0004 היא בצעירותם, \u0003או מביאתו לידי עניות.\u0004","ותוהים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן\u0004 עצמו: \u0003הרוצה שיתעשר — ידבק בזרעו של אהרן, כל שכן\u0004 שזכות \u0003תורה\u0004 שלו \u0003ו\u0004זכות ה\u0003כהונה\u0004 שלה \u0003מעשרתן.\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמעשיר — \u0003בתלמיד חכם\u0004 הנושא בת כהן, ששבח לכהונה שנדבק בה תלמיד חכם וזיווגם עולה יפה. \u0003הא\u0004 \u0005[זה]\u0006 שאינו עולה יפה — מדובר \u0003בעם הארץ\u0004 הנושא בת כהן.","מסופר: \u0003ר' יהושע נסיב כהנתא\u0004 \u0005[נשא כהנת],\u0006 ו\u0003חלש\u0004 \u0005[חלה].\u0006 \u0003אמר:\u0004 בודאי \u0003לא ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003לאהרן\u0004 הכהן ש\u0003אדבק בזרעיה\u0004 \u0005[בזרעו],\u0006 \u0003דהוי ליה חתנא כי אנא\u0004 \u0005[שיהיה לו חתן כמוני].\u0006","ומסופר גם: \u0003רב אידי בר אבין נסיב כהנתא\u0004 \u0005[נשא כהנת],\u0006 \u0003נפקו מיניה תרי בני סמיכי\u0004 \u0005[יצאו ממנו שני בנים סמוכים\u0006 להוראה\u0005],\u0006 והם: \u0003רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי, ור' יהושע בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי.\u0004 וכן \u0003אמר רב פפא: אי\u0004 \u0005[אם]\u0006 \u0003לא נסיבנא כהנתא\u0004 \u0005[הייתי נושא כהנת],\u0006 \u0003לא איעתרי\u0004 \u0005[הייתי מתעשר].\u0006","ולצד אחר \u0003אמר רב כהנא\u0004 (שלא היה כהן): \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא נסיבנא כהנתא\u0004 \u0005[הייתי נושא כוהנת],\u0006 \u0003לא גלאי\u0004 \u0005[הייתי גולה],\u0006 שהוכרח רב כהנא לברוח מבבל לארץ ישראל. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003למקום תורה גלית\u0004 ואין זה עונש כלל! והשיב: \u0003לא גלאי כדגלי אינשי\u0004 \u0005[גליתי כמו שגולים בני אדם]\u0006 למקום תורה, אלא ברחתי מפני אימת המלכות.","\u0003אמר ר' יצחק: כל הנהנה מסעודת הרשות\u0004 שאין בה מצוה, \u0003לסוף גולה, שנאמר \"ואכלים כרים מצאן ועגלים מתוך מרבק\"\u0004 (עמוס ו, ד), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"לכן עתה יגלו בראש גלים\u0004 וסר מירזח סרוחים\u0003\"\u0004 (עמוס, ו, ז).","ועוד לענין תלמיד חכם הנהנה מסעודה שאינה של מצוה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל תלמיד חכם המרבה סעודתו בכל מקום,\u0004 גנאי הוא לו, ו\u0003סוף\u0004 דרכו נמצא שצרות רבות באות עליו בשל הנהגתו זו: \u0003מחריב את ביתו, ומאלמן את אשתו, ומייתם את גוזליו\u0004 (ילדיו), \u0003ותלמודו משתכח ממנו, ומחלוקות רבות באות עליו, ודבריו אינם נשמעים, ומחלל שם שמים ושם רבו ושם אביו, וגורם שם רע לו ולבניו ולבני בניו עד סוף כל הדורות.\u0004","ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 אותו שם רע שגורמת הנהגתו זו לו ולבניו? \u0003אמר אביי: קרו ליה בר מחים תנורי\u0004 \u0005[קוראים לו\u0006 לבנו של איש כזה \u0005בן מחמם התנורים]\u0006 כלומר, בן האיש שתמיד מצוי היה ליד תנור הבישול. \u0003רבא אמר: בר מרקיד בי כובי\u0004 \u0005[בן המרקד בפונדק]\u0006 שנראה שמוזמן לכל סעודה, וחייב לשעשע את הקהל. \u0003רב פפא אמר: בר מלחיך פינכי\u0004 \u0005[בן מלקק הקערות].\u0006 \u0003רב שמעיה אמר: בר מך רבע\u0004 \u0005[בן מקפל\u0006 הלבוש ו\u0005רובץ\u0006 וישן\u0005]\u0006 בכל מקום מתוך שיכרות.","כיון שמדובר בנישואין הראויים מביאים מה ש \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לעולם ימכור אדם כל מה שיש לו וישא בת תלמיד חכם, שאם\u0004 יזדמן \u0003מת או גולה\u0004 בצעירותו — \u0003מובטח לו שבניו תלמידי חכמים\u0004 משום שאמם תחנכם לכך. \u0003ואל ישא בת עם הארץ, שאם מת או גולה — בניו עמי הארץ.\u0004","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לעולם ימכור אדם כל מה שיש לו וישא\u0004 אדם \u0003בת תלמיד חכם\u0004 וידאג \u0003להשיא בתו לתלמיד חכם, משל ל\u0004נישואין שכאלה הוא \u0003ענבי הגפן\u0004 המסתבכות \u0003בענבי הגפן,\u0004 שהוא \u0003דבר נאה ומתקבל\u0004 בעיני אלוקים ואדם. \u0003ולא ישא בת עם הארץ, משל ל\u0004נישואין שכאלה הוא \u0003ענבי הגפן בענבי הסנה,\u0004 שהוא \u0003דבר כעור\u0004"],["\u0003ואינו מתקבל.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לעולם ימכור אדם כל מה שיש לו, וישא בת תלמיד חכם. לא מצא בת תלמיד חכם — ישא בת גדולי הדור,\u0004 שהם חסידים וצדיקים אף שאינם תלמידי חכמים. \u0003לא מצא בת גדולי הדור\u0004 — \u0003ישא בת ראשי כנסיות\u0004 (הממונים על בתי הכנסת). \u0003לא מצא בת ראשי כנסיות — ישא בת גבאי צדקה. לא מצא בת גבאי צדקה — ישא בת מלמדי תינוקות. ו\u0004אולם \u0003לא ישא\u0004 כלל \u0003בת עמי הארץ, מפני שהן שקץ\u0004 מפני היותם שקועים באיסורים, \u0003ונשותיהן שרץ, ועל בנותיהן הוא אומר: \"ארור שכב עם כל בהמה\"\u0004 (דברים כז, כא), שאין בהן לא מוסר ולא דעת.","ועוד בגנות עמי הארץ, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: עם הארץ אסור לאכול בשר, שנאמר: \"זאת תורת הבהמה והעוף\"\u0004 (ויקרא יא, מו), ודרש: \u0003כל העוסק בתורה — מותר לאכול בשר בהמה ועוף, וכל שאינו עוסק בתורה — אסור לאכול בשר בהמה ועוף.\u0004","ועוד אמרו חכמים דברי גנאי חריפים על עמי הארץ אותם הבורים שהם גם רשעים, והפליגו והגזימו (גאונים) בגנותם הרבה: \u0003אמר ר' אלעזר: עם הארץ מותר לנוחרו\u0004 (להורגו בנעיצת סכין) \u0003ביום הכיפורים שחל להיות בשבת. אמרו לו תלמידיו: רבי, אמור\u0004 לפחות זאת שאפשר \u0003לשוחטו! אמר להם:\u0004 בכוונה אמרתי לנוחרו, כי \u0003זה\u0004 (השחיטה) \u0003טעון ברכה\u0004 עליה, \u0003וזה\u0004 (הנחירה) \u0003אינו טעון ברכה.\u0004","\u0003אמר ר' אלעזר: עם הארץ אסור להתלוות עמו בדרך\u0004 מפני הסכנה שבדבר, \u0003שנאמר\u0004 בתורה: \u0003\"כי הוא חייך וארך ימיך\"\u0004 (דברים ל, כ), ועם הארץ שלא למד תורה מראה שאף \u0003על חייו\u0004 שלו \u0003לא חס\u0004 אינו חושש, \u0003על חיי חבירו לא כל שכן\u0004 שאינו חושש.","\u0003אמר ר' שמואל בר נחמני אמר ר' יוחנן: עם הארץ מותר לקורעו כדג. אמר ר' שמואל בר יצחק: ומגבו,\u0004 שהוא גורם למותו המיידי, שקורע גם את חוט השדרה ולא רק את בטנו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' עקיבא: כשהייתי עם הארץ אמרתי: מי יתן לי תלמיד חכם ואנשכנו כחמור. אמרו לו תלמידיו: רבי, אמור\u0004 אנשכנו \u0003ככלב! אמר להם:\u0004 בכוונה אמרתי כחמור, כי \u0003זה\u0004 החמור \u0003נושך ושובר עצם, וזה\u0004 הכלב \u0003נושך ואינו שובר עצם.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: כל המשיא בתו לעם הארץ, כאילו כופתה ומניחה לפני\u0004 ה\u0003ארי.\u0004 ומפני מה? \u0003מה ארי דורס ואוכל, ואין לו בושת פנים\u0004 על מה שעשה, \u0003אף עם הארץ מכה\u0004 את אשתו קודם, \u0003ו\u0004אחר כך \u0003בועל\u0004 אותה, \u0003ואין לו בושת פנים,\u0004 לפחות לפייסנה קודם.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: אילמלא אנו צריכים\u0004 (נחוצים) \u0003להם\u0004 לעמי הארץ \u0003ל\u0004צורך \u0003משא ומתן, היו הורגין אותנו.\u0004","ומאידך לגבי עמי הארץ שיש בהם צד של רגישות (מאירי) \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: כל העוסק בתורה לפני עם הארץ,\u0004 והרי הוא מביישו ומצערו בכך, שכן אין עם הארץ יכול לעסוק בה כמותו, ו\u0003כאילו בועל ארוסתו בפניו, שנאמר: \"תורה צוה לנו משה מורשה\u0004 קהילת יעקב\u0003\"\u0004 (דברים לג, ד), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"מורשה\" אלא מאורסה,\u0004 שהתורה נמשלת כארוסה לכלל ישראל, ותלמיד חכם העוסק בה נחשב כבעלה של התורה, ואילו עם הארץ אינו יכול לעסוק בה ומרוחק ממנה אף שהיא שלו.","ועוד אמר: \u0003גדולה שנאה ששונאים עמי הארץ לתלמיד חכם יותר משנאה ששונאים אומות העולם את ישראל, ונשותיהם\u0004 של עמי הארץ שונאות \u0003יותר מהן. תנא\u0004 \u0005[שנה\u0006 בתוספתא\u0005]\u0006 מי ש\u0003שנה\u0004 (למד תורה) \u0003ופירש\u0004 מן הלימוד, שונא \u0003יותר מכולן.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ששה דברים נאמרו בעמי הארץ: אין מוסרין להן עדות,\u0004 שאין להביאם כדי שיראו ויעידו על הדבר שנעשה. \u0003ואין מקבלין ממנו עדות,\u0004 שאינו נאמן. \u0003ואין מגלין להן סוד,\u0004 שוודאי יגלוהו לכל. \u0003ואין ממנין אותן אפוטרופוס על היתומים,\u0004 שמא ימעלו באימון, ויעשו שימוש שאינו הוגן בכספי היתומים. \u0003ואין ממנין אותן אפוטרופוס על קופה של צדקה,\u0004 מאותו טעם. \u0003ואין מתלוין עמהם בדרך,\u0004 מפני הסכנה שבדבר. \u0003ויש אומרים: אף אין מכריזין על אבידתו,\u0004 שאם אבידה נפלה מעם הארץ, אינו צריך להשתדל להחזירה (מאירי).","ושואלים: \u0003ותנא קמא\u0004 \u0005[והתנא הראשון]\u0006 שאינו סבור כן, מה טעמו? ומשיבים: \u0003זימנין דנפיק מיניה זרעא מעליא ואכיל ליה\u0004 \u0005[פעמים\u0006 יש \u0005שיוצא ממנו זרע,\u0006 בנים, \u0005מעולים ויאכלו הם\u0006 מן הנכסים\u0005],\u0006 \u0003ש\u0004הרי \u0003נאמר: \"יכין וצדיק ילבש\"\u0004 (איוב כז, יז), שייתכן שהרשע מכין דברים לעצמו, ולבסוף משתמש בהם הצדיק.","ומעתה שבים אנו לפירוש המשנה. שנינו: \u0003וכן מי ש\u0004שכח ו\u0003יצא\u0004 מירושלים ובשר קודש בידו, צריך לחזור כשם שחוזרים לבטל את החמץ. ונחלקו ר' מאיר ור' יהודה בשיעור שעליו חוזרים, אם כזית כדברי ר' יהודה, או כביצה כדברי ר' מאיר.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003ר' מאיר סבר כביצה הוא דחשיב\u0004 \u0005[שחשוב],\u0006 \u0003ור' יהודה סבר כזית נמי חשיב\u0004 \u0005[גם כן חשוב].\u0006 \u0003ורמינהו\u0004 \u0005[משליכים\u0006 מראים סתירה\u0005]:\u0006 \u0003עד כמה הן מזמנין,\u0004 מהו שיעור האוכל שחייבים אחריו בברכת המזון וברכת זימון? \u0003עד כזית\u0004 לדעת סתם משנה, שהיא כרגיל כר' מאיר, \u0003ור' יהודה אומר: עד כביצה\u0004 הפך דעותיהם כאן!","\u0003אמר ר' יוחנן: מוחלפת השיטה\u0004 כלומר, יש להחליף את השיטות באחד המקורות.","\u0003אביי אמר: לעולם לא תיפוך\u0004 \u0005[אל\u0006 תזדקק \u0005להפוך]\u0006 \u0003התם\u0004 \u0005[שם] —\u0006 \u0003בקראי פליגי\u0004 \u0005[במקראות הם חלוקים],\u0006 \u0003הכא\u0004 \u0005[כאן] —\u0006 \u0003בסברא פליגי\u0004 \u0005[הם חלוקים],\u0006 כיצד? \u0003התם בקראי פליגי\u0004 \u0005[שם במקראות הם חלוקים]\u0006 כי \u0003ר' מאיר סבר\u0004 שהכתוב \"ואכלת ושבעת וברכת את ה' אלהיך\" (דברים ח, י) מתפרש: \u0003\"ואכלת\" — זו אכילה, \"ושבעת\" — זו שתיה, ו\u0004סתם \u0003אכילה\u0004 האמורה בתורה שיעורה \u0003בכזית. ור' יהודה סבר: \"ואכלת ושבעת\"\u0004 הוא ענין אחד, \u0003באכילה שיש בה שביעה, ואיזו זו? בכביצה.\u0004","ואילו \u0003הכא בסברא פליגי\u0004 \u0005[כאן בסברה נחלקו]\u0006 ש\u0003ר' מאיר סבר: חזרתו\u0004 לירושלים כדי לשורפו — \u0003כטומאתו, מה טומאתו\u0004 של דבר מאכל אינו פחות מ\u0003בכביצה, אף חזרתו בכביצה. ור' יהודה סבר: חזרתו\u0004"]]};
